                result[field_name] = val_list[k]
            else:
                # Treat everything else as a key name
                if k in key_list:
                    idx = key_list.index(k)
                    result[k] = val_list[idx]
                else:
                    # key not present; insert None
                    result[k] = None
        return result

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer."""
    # Check that the data attribute exists and is mutable
    if not hasattr(self, 'data'):
        raise AttributeError("Object does not have a 'data' attribute")
    data = self.data
    # Ensure the data supports len() and pop()
    try:
        length = len(data)
    except TypeError:
        raise TypeError("'data' must support len()")
    if length < 2:
        raise ValueError("Not enough bytes to pop a 16-bit unsigned integer")
    try:
        # Pop the least significant byte first (last element)
        lsb = data.pop()
        # Then the most significant byte
        msb = data.pop()
    except Exception as exc:
        raise RuntimeError(f"Failed to pop bytes from data: {exc}") from exc
    # Combine into a big-endian 16-bit unsigned integer
    if not (0 <= msb <= 0xFF and 0 <= lsb <= 0xFF):
        raise ValueError("Popped values are not 8-bit bytes")
    return (msb << 8) | lsb

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :returns: Response object that will handle the result.
    """
    # Validate basic parameters
    if not isinstance(n, int):
        raise TypeError(f"'n' must be an int, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"'qid' must be an int, got {type(qid).__name__}")

    # Validate hooks
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError(f"'dehydration_hooks' must be a dict or None, got {type(dehydration_hooks).__name__}")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError(f"'hydration_hooks' must be a dict or None, got {type(hydration_hooks).__name__}")

    # Build the DISCARD message
    message = {
        "type": "DISCARD",
        "n": n,
        "qid": qid,
        "dehydration_hooks": dehydration_hooks if dehydration_hooks is not None else {},
        "hydration_hooks": hydration_hooks if hydration_hooks is not None else {},
        "handlers": handlers or {}
    }

    # Append to the output queue; use the most common attribute names with fallback
    queue_attr_candidates = ("_queue", "_outgoing", "queue", "outgoing")
    queue = None
    for attr in queue_attr_candidates:
        if hasattr(self, attr):
            queue = getattr(self, attr)
            break
    if queue is None:
        raise AttributeError("No output queue found on the object to append messages. "
                             f"Expected one of: {', '.join(queue_attr_candidates)}")

    try:
        queue.append(message)
    except Exception as exc:
        raise RuntimeError(f"Failed to append DISCARD message to queue: {exc}") from exc

    # Construct and return the Response object.  The Response class is assumed
    # to be defined elsewhere in the module and accepts the message and handlers.
    try:
        return Response(message, dehydration_hooks=dehydration_hooks,
                        hydration_hooks=hydration_hooks, **handlers)
    except Exception as exc:
        # If Response construction fails, we still return a generic object
        # that encapsulates the info for debugging.
        class _FallbackResponse:
            def __init__(self_inner, msg, **kw):
                self_inner.msg = msg
                self_inner.kw = kw
        return _FallbackResponse(message, **handlers)

