        raise TypeError("imp_user must be a string")

    # Build message arguments avoiding None values
    msg_args = {}
    if mode is not None:
        msg_args["mode"] = mode
    if bookmarks is not None:
        try:
            msg_args["bookmarks"] = list(bookmarks)
        except Exception as exc:
            raise TypeError("bookmarks must be convertible to a list") from exc
    if metadata is not None:
        msg_args["metadata"] = dict(metadata)
    if timeout is not None:
        msg_args["timeout"] = timeout
    if db is not None:
        msg_args["database"] = db
    if imp_user is not None:
        msg_args["imp_user"] = imp_user

    # Optional hooks - store or apply if the instance has suitable mechanisms
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict mapping types to callables")
        if hasattr(self, "_dehydration_hooks"):
            self._dehydration_hooks.update(dehydration_hooks)
        else:
            self._dehydration_hooks = dict(dehydration_hooks)

    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict mapping types to callables")
        if hasattr(self, "_hydration_hooks"):
            self._hydration_hooks.update(hydration_hooks)
        else:
            self._hydration_hooks = dict(hydration_hooks)

    # Append the BEGIN message to the output queue
    packet = ("BEGIN", msg_args)
    if hasattr(self, "_output_queue"):
        self._output_queue.append(packet)
    else:
