    if mode is not None:
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be either 'READ' or 'WRITE'")
        args["mode"] = mode

    # Validate and set bookmarks
    if bookmarks is not None:
        try:
            book_list = list(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable")
        args["bookmarks"] = book_list

    # Validate and set metadata
    if metadata is not None:
        if not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict")
        args["metadata"] = metadata.copy()

    # Validate and set timeout
    if timeout is not None:
        try:
            args["timeout"] = float(timeout)
        except (TypeError, ValueError):
            raise TypeError("timeout must be a number")

    # Validate and set database name
    if db is not None:
        if not isinstance(db, str):
            raise TypeError("db must be a string")
        args["database"] = db

    # Validate and set impersonated user
    if imp_user is not None:
        if not isinstance(imp_user, str):
            raise TypeError("imp_user must be a string")
        args["impersonatedUser"] = imp_user

    # Build the message tuple that will be queued
    message = ("BEGIN", args)

    # Try to append to a known output queue
    _queue = None
    if hasattr(self, "_out_queue"):
        _queue = getattr(self, "_out_queue")
    elif hasattr(self, "out_queue"):
        _queue = getattr(self, "out_queue")
    elif hasattr(self, "_out"):
        # Some implementations use a queue with put method
        if hasattr(getattr(self, "_out"), "put"):
            getattr(self, "_out").put(message)
            _queue = None
        else:
            _queue = getattr(self, "_out")
    else:
        raise AttributeError("No output queue attribute found on the session")

    if _queue is not None:
        try:
            # Prefer append for list-like queues
            _queue.append(message)
        except AttributeError:
            # Fallback to put method if available
            if hasattr(_queue, "put"):
                _queue.put(message)
            else:
                raise AttributeError("The output queue does not support append or put")

