    # with the message, hooks, and extra handlers. If it is not available, we
    # fall back to a simple tuple.
    try:
        Response = self._Response  # expecting a reference set on the instance
    except AttributeError:
        # Import fallback if Response is globally available
        try:
            from .response import Response  # pylint: disable=import-error
        except Exception:
            Response = None

    if Response is not None:
        return Response(message, dehydration_hooks=dehydration_hooks,
                        hydration_hooks=hydration_hooks, **handlers)
    # Fallback response: just return the constructed message tuple
    return message

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate `mode`
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError("mode must be either 'READ', 'WRITE', or None")

    # Validate `bookmarks`
    if bookmarks is not None:
        try:
            iter(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable of bookmark values")

    # Validate `metadata`
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")

    # Validate `timeout`
    if timeout is not None:
        try:
            timeout = float(timeout)
        except (TypeError, ValueError):
            raise TypeError("timeout must be a number")
        if timeout <= 0:
            raise ValueError("timeout must be positive")

    # Validate `db`
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")

    # Validate `imp_user`
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")

    # Validate `dehydration_hooks`
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary")
        for typ, func in dehydration_hooks.items():
            if not isinstance(typ, type):
                raise TypeError("dehydration_hooks keys must be types")
            if not callable(func):
                raise TypeError("dehydration_hooks values must be callables")

    # Validate `hydration_hooks`
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary")
        for typ, func in hydration_hooks.items():
            if not isinstance(typ, type):
                raise TypeError("hydration_hooks keys must be types")
            if not callable(func):
                raise TypeError("hydration_hooks values must be callables")

    # Default mode if unspecified
    current_mode = mode if mode is not None else "WRITE"

    # Build the BEGIN message payload
    message = {
        "type": "BEGIN",
        "mode": current_mode,
        "bookmarks": list(bookmarks) if bookmarks is not None else None,
        "metadata": metadata or {},
        "timeout": timeout,
        "db": db,
        "imp_user": imp_user,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks
    }

    # Append the message to the outgoing queue
    try:
        # We expect the implementation to have a method that queues
        # messages for transmission.  Use a fallback name if it does not exist.
        queue_method = getattr(self, "_queue_message", None)
        if not callable(queue_method):
            queue_method = getattr(self, "_enqueue_message", None)
        if not callable(queue_method):
            raise AttributeError("No queue method found")
        queue_method(message)
    except Exception as exc:
        raise RuntimeError("Failed to queue BEGIN message") from exc

    # Construct and return the Response object.  The Response class is
    # expected to exist in the surrounding context.
    try:
        Response = getattr(self, "Response", None)
        if Response is None:
            raise AttributeError("No Response class available")
    except Exception as exc:
        raise RuntimeError("Response class not available") from exc

    return Response(message, **handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate `name`
    if not isinstance(name, str):
        raise TypeError("`name` must be a string")
    if not name.isidentifier():
        raise ValueError(f"`name` '{name}' is not a valid Python identifier")

    # Validate `fields`
    if not hasattr(fields, "__iter__") or isinstance(fields, (str, bytes)):
        raise TypeError("`fields` must be an iterable of field names")
    field_names = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"Field name '{f}' is not a string")
        if not f.isidentifier():
            raise ValueError(f"Field name '{f}' is not a valid identifier")
        field_names.append(f)

    # Validate `srid_map`
    if srid_map is None:
        srid_map = {}
    elif not isinstance(srid_map, dict):
        raise TypeError("`srid_map` must be a dictionary")
    else:
        for k, v in srid_map.items():
            if k not in field_names:
                raise KeyError(f"SRID map key '{k}' is not in `fields`")
            if not isinstance(v, int):
                raise TypeError(f"SRID value for field '{k}' must be an integer")

    # Build the class dictionary
    cls_dict = {}

    def __init__(self, *args, **kwargs):
        if args and kwargs:
            raise TypeError("Use either positional or keyword arguments, not both.")
        # Positional arguments
        if args:
            if len(args) > len(field_names):
                raise TypeError(f"Expected at most {len(field_names)} positional arguments")
            for field, value in zip(field_names, args):
                setattr(self, field, value)
            # Initialize remaining fields to None
            for field in field_names[len(args):]:
                setattr(self, field, None)
        else:
            # Keyword arguments
            for field in field_names:
                if field in kwargs:
                    setattr(self, field, kwargs.pop(field))
                else:
                    setattr(self, field, None)
            if kwargs:
                unexpected = ", ".join(kwargs.keys())
                raise TypeError(f"Unexpected keyword arguments: {unexpected}")

    cls_dict["__init__"] = __init__

    def __repr__(self, nm=name):
        parts = [f"{field}={getattr(self, field)!r}" for field in field_names]
        return f"<{nm} {' '.join(parts)}>"

    cls_dict["__repr__"] = __repr__

    # Store SRID map on the class
    cls_dict["_srid_map"] = srid_map

    # Dynamically create the class
    try:
        new_cls = type(name, (object,), cls_dict)
    except Exception as exc:
        raise RuntimeError(f"Failed to create class '{name}': {exc}") from exc

    return new_cls

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage:
        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    Each call to the decorated function will emit a DeprecationWarning
    with the supplied message.

    Raises:
        TypeError: If the supplied message is not a string or the
        target of the decorator is not callable.
    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Cannot decorate non-callable object: {func!r}")
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

