def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise ValueError(f"Expected code to be a string, got {type(code).__name__}")
    # Define the R options that need to be set before running the script.
    options = [
        "options(stringsAsFactors = FALSE)",  # prevent automatic string-to-factor conversion
        "options(bitmapType = \"cairo\")",    # use Cairo for better plot rendering
        "options(error = function() { traceback(2); quit(status = 1) })",  # propagate errors properly
    ]
    # Ensure the user code runs after the options have been set.
    # Preserve any leading/trailing whitespace or newlines in the original code.
    if code.startswith("\n") or code.strip() == "":
        # If code is empty or contains only newlines, just return the options.
        return "\n".join(options)
    return "\n".join(options + [code])

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """
    A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    # Lazily import required modules to avoid top-level imports
    try:
        submod = __import__('subprocess')
        subprocess = submod
    except Exception:
        raise RuntimeError("subprocess module is required")

    try:
        concurrent_mod = __import__('concurrent.futures')
        futures = concurrent_mod.futures
    except Exception:
        futures = None

    # Validate cmd
    if not isinstance(cmd, tuple) or not all(isinstance(x, str) for x in cmd):
        raise TypeError("cmd must be a tuple of strings")
    if len(cmd) == 0:
        raise ValueError("cmd cannot be empty")
    # Ensure varargs is a sequence of strings
    if not isinstance(varargs, Sequence):
        raise TypeError("varargs must be a sequence of strings")
    # Compute partitions
    parts: list[list[str]] = []
    current: list[str] = []
    current_len = sum(len(arg) + 1 for arg in cmd)  # approximate base length
    for arg in varargs:
        arg_str = str(arg)
        # +1 for space
        if current_len + len(arg_str) + 1 > _max_length and current:
            parts.append(current)
            current = []
            current_len = sum(len(arg) + 1 for arg in cmd)
        current.append(arg_str)
        current_len += len(arg_str) + 1
    if current:
        parts.append(current)

    # Function to run a single command with a list of args
    def _run_one(part: list[str]) -> tuple[int, bytes]:
        full_cmd = list(cmd) + part
        try:
            result = subprocess.run(
                full_cmd,
                capture_output=True,
                text=True,
                **kwargs
            )
        except Exception as e:
            return (-1, f"Error running command: {e}\n".encode())
        out_bytes = result.stdout.encode()
        # If color requested and platform supports pty, we ignore for simplicity
        return (result.returncode, out_bytes)

    # Run commands with concurrency
    retcode = 0
    stdout_acc = bytearray()
    if target_concurrency <= 1 or futures is None:
        # Sequential execution
        for part in parts:
            code, out = _run_one(part)
            if code and retcode == 0:
                retcode = code
            stdout_acc.extend(out)
    else:
        # Parallel execution
        with futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            future_to_part = {executor.submit(_run_one, part): part for part in parts}
            for fut in futures.as_completed(future_to_part):
                code, out = fut.result()
                if code and retcode == 0:
                    retcode = code
                stdout_acc.extend(out)

    return (retcode, bytes(stdout_acc))

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings."""
    # Validate input
    if seq is None:
        raise TypeError("Input sequence cannot be None")
    # Accept list, tuple, or string; other sequences are allowed but must be iterable
    if not isinstance(seq, (list, tuple, str)):
        # Ensure it is iterable
        try:
            iter(seq)
        except TypeError:
            raise TypeError("Input must be a sequence of strings")
    # Check that every element is a string
    for item in seq:
        if not isinstance(item, str):
            raise TypeError("All elements of the sequence must be strings")
    # Perform deterministic Fisher-Yates shuffle
    result = list(seq)
    n = len(result)
    for i in range(n - 1, 0, -1):
        v = result[i]
        # Deterministic pseudo-random seed derived from element value and index
        seed = sum(ord(c) for c in v) + i * 7681
        j = seed % (i + 1)
        result[i], result[j] = result[j], result[i]
    return result

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings."""
    # Validate that the argument is a sequence
    if not isinstance(seq, Sequence):
        raise TypeError(f"Expected a sequence, got {type(seq).__name__}")
    # Validate that all elements are strings
    for i, item in enumerate(seq):
        if not isinstance(item, str):
