            return _CacheInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            order.clear()
            hits = 0
            misses = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)
