@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Basic validation
        try:
            if not isinstance(max_level, int) or max_level <= 0:
                raise ValueError(f"max_level must be a positive integer, got {max_level!r}")
            if not isinstance(max_path_level, int) or max_path_level <= 0:
                raise ValueError(f"max_path_level must be a positive integer, got {max_path_level!r}")
            if not isinstance(e, BaseException):
                raise TypeError(f"e must be an exception instance, got {type(e).__name__!r}")
        except Exception as init_exc:
            return f"Invalid parameters for extostr: {init_exc!s}"

        result_parts = []

        # Exception type and message
        try:
            exc_type = e.__class__.__name__
            exc_msg = str(e)
            result_parts.append(f"{exc_type}: {exc_msg}")
        except Exception as exc_err:
            result_parts.append(f"Exception formatting error: {exc_err!s}")

        # Stack trace
        try:
            tb = getattr(e, "__traceback__", None)
            if tb is not None:
                result_parts.append("Traceback (most recent call last):")
                level = 0
                while tb is not None and level < max_level:
                    frame = tb.tb_frame
                    lineno = tb.tb_lineno
                    func = frame.f_code.co_name
                    filename = frame.f_code.co_filename

                    # Normalize and shorten the path
                    try:
                        norm_path = os.path.normpath(filename)
                        parts = norm_path.split(os.sep)
                        if len(parts) > max_path_level:
                            displayed_path = os.sep.join(parts[-max_path_level:])
                        else:
                            displayed_path = norm_path
                    except Exception:
                        displayed_path = filename

                    result_parts.append(f'  File "{displayed_path}", line {lineno}, in {func}')
                    tb = tb.tb_next
                    level += 1
        except Exception as trace_err:
            result_parts.append(f"Error retrieving traceback: {trace_err!s}")

        return "\n".join(result_parts)

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        import traceback
        import os
    except Exception:
        # Fallback if imports fail
        return str(e)

    parts = []

    # Exception type and message
    try:
        exc_type, exc_value, exc_tb = e.__class__, e, e.__traceback__
    except AttributeError:
        # Not an exception instance
        return str(e)

    parts.append(f"{exc_type.__name__}: {exc_value}")

    # Process traceback frames
    if exc_tb:
        try:
            tb_entries = traceback.extract_tb(exc_tb, limit=max_level)
        except Exception:
            tb_entries = []

        for frame in tb_entries:
            # frame is a namedtuple: (filename, lineno, name, line)
            filename = frame.filename
            if max_path_level is not None and max_path_level > 0:
                # Split path and keep last max_path_level components
                parts_path = filename.split(os.sep)
                filename = os.sep.join(parts_path[-max_path_level:]) if len(parts_path) > max_path_level else filename
            part = f'File "{filename}", line {frame.lineno}, in {frame.name}'
            if frame.line:
                part += f'\n    {frame.line.strip()}'
            parts.append(part)

    # Join parts with newlines
    return "\n".join(parts)

