def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ...     ['x', 'y', 'z'],
    ...     ['q', 'z'],
    ...     [1, 3, 5],
    ...     ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list or tuple of orderings")
    adjacency = {}
    indegree = {}
    first_index = {}
    order_counter = 0

    for ordering in orderings:
        try:
            seq = list(ordering)
        except TypeError:
            raise TypeError("Each ordering must be an iterable")
        # check elements are hashable and unique within this ordering
        seen = set()
        for item in seq:
            try:
                hash(item)
            except TypeError:
                raise TypeError(f"Element {item!r} is not hashable")
            if item in seen:
                raise ValueError(f"Duplicate element {item!r} in ordering")
            seen.add(item)
            if item not in adjacency:
                adjacency[item] = set()
            if item not in indegree:
                indegree[item] = 0
            if item not in first_index:
                first_index[item] = order_counter
                order_counter += 1
        # add edges between consecutive elements
        for i in range(len(seq) - 1):
            a, b = seq[i], seq[i + 1]
            if b not in adjacency[a]:
                adjacency[a].add(b)
                indegree[b] = indegree.get(b, 0) + 1
                if b not in first_index:
                    first_index[b] = order_counter
                    order_counter += 1

    # Kahn's algorithm with deterministic priority based on first appearance
    zero_nodes = [node for node, deg in indegree.items() if deg == 0]
    from heapq import heapify, heappush, heappop

    # Use a min-heap keyed by first_index to get deterministic order
    heap = []
    for node in zero_nodes:
        heappush(heap, (first_index[node], node))

    result = []
    seen_in_result = set()

    while heap:
        _, node = heappop(heap)
        if node in seen_in_result:
            continue
        seen_in_result.add(node)
        result.append(node)
        for nbr in adjacency.get(node, []):
            indegree[nbr] -= 1
            if indegree[nbr] == 0:
                heappush(heap, (first_index[nbr], nbr))

    if len(result) != len(adjacency):
        raise ValueError("Orderings contain a cycle or conflict")

    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    if not isinstance(orderings, list):
        raise TypeError("orderings must be a list of lists")
    for idx, o in enumerate(orderings):
        if not isinstance(o, list):
            raise TypeError(f"ordering at index {idx} is not a list")
        seen = set()
        for t in o:
            if t in seen:
                raise ValueError(f"duplicate element {t!r} in ordering {idx}")
            seen.add(t)

    # Count occurrences and record suffixes
    from collections import defaultdict
    occ = defaultdict(int)
    suffix_map = defaultdict(list)  # element -> first suffix list seen
    for o in orderings:
        for i, elem in enumerate(o):
            occ[elem] += 1
        for elem in o:
            if occ[elem] >= 2:
                # record suffix that starts at elem in this ordering
                idx = o.index(elem)  # first occurrence in this ordering
                suffix = o[idx:]
                if elem not in suffix_map:
                    suffix_map[elem] = suffix
                else:
                    # check consistency
                    if suffix_map[elem] != suffix:
                        raise ValueError(
                            f"Inconsistent suffixes for element {elem!r}"
                        )

    # Build graph
    from collections import defaultdict, deque
    graph = defaultdict(set)
    indeg = defaultdict(int)
    nodes = set()
    for o in orderings:
        n = len(o)
        for i in range(n):
            nodes.add(o[i])
            if i + 1 < n:
                a, b = o[i], o[i+1]
                if b not in graph[a]:
                    graph[a].add(b)
                    indeg[b] += 1
                    if a not in indeg:
                        indeg[a] = indeg.get(a, 0)

    # First seen priority
    priority = {}
    seen_order = []
    for o in orderings:
        for t in o:
            if t not in priority:
                priority[t] = len(seen_order)
                seen_order.append(t)

    # Kahn's algorithm with priority
    zero = [node for node in nodes if indeg.get(node, 0) == 0]
    zero.sort(key=lambda x: priority.get(x, 10**9))
    result = []
    while zero:
        node = zero.pop(0)
        result.append(node)
        for nb in graph.get(node, ()):
            indeg[nb] -= 1
            if indeg[nb] == 0:
                zero.append(nb)
        zero.sort(key=lambda x: priority.get(x, 10**9))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in orderings")
    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Basic input validation
    if orderings is None:
        raise TypeError("orderings cannot be None")
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list or tuple of orderings")
    # Flatten orderings and preserve first occurrence order
    node_index = {}
    order_list = []
    for ordering in orderings:
        if ordering is None:
            continue
        if not hasattr(ordering, "__iter__"):
            raise TypeError(f"Each ordering must be iterable, got {type(ordering).__name__}")
        for node in ordering:
            if node not in node_index:
                node_index[node] = len(order_list)
                order_list.append(node)

    # Build adjacency list and indegree counts
    adj = {node: [] for node in order_list}
    indegree = {node: 0 for node in order_list}
    for ordering in orderings:
        if ordering is None:
            continue
        for a, b in zip(ordering, ordering[1:]):
            if b not in adj[a]:
                adj[a].append(b)
                indegree[b] += 1

    # Kahn's algorithm with deterministic tie-breaking based on first appearance
    result = []
    zero_indeg_nodes = [node for node in order_list if indegree[node] == 0]

    while zero_indeg_nodes:
        # Select the node that appeared earliest in the original order_list
        min_node = min(zero_indeg_nodes, key=lambda n: node_index[n])
        zero_indeg_nodes.remove(min_node)
        result.append(min_node)
        for neighbour in adj[min_node]:
            indegree[neighbour] -= 1
            if indegree[neighbour] == 0:
                zero_indeg_nodes.append(neighbour)

    if len(result) != len(order_list):
        raise ValueError("Orderings contain a cycle or inconsistent constraints")

    return result

