def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    if classes is None:
        return []
    res = []
    seen = set()
    for c in classes:
        if c in seen:
            continue
        if not isinstance(c, type):
            raise TypeError(f"Expected a class, got {type(c).__name__}")
        # Skip if c is subclass of any already kept base
        is_sub = False
        for base in res:
            try:
                if issubclass(c, base):
                    is_sub = True
                    break
            except TypeError:
                raise TypeError(f"Cannot determine subclass relationship between {c!r} and {base!r}")
        if is_sub:
            continue
        # Remove any previously kept bases that are subclasses of c
        kept = []
        for base in res:
            try:
                if issubclass(base, c):
                    continue
            except TypeError:
                raise TypeError(f"Cannot determine subclass relationship between {base!r} and {c!r}")
            kept.append(base)
        res = kept
        res.append(c)
        seen.add(c)
    return res

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    kept = []
    for c in classes:
        # Skip non‑class entries silently, they cannot participate in subclass checks
        if not isinstance(c, type):
            keep_entries = True
        else:
            # If any already kept class is a subclass of the candidate,
            # the candidate is a super‑class and can be omitted.
            keep_entries = not any(
                (isinstance(k, type) and issubclass(k, c)) for k in kept
            )

        if not keep_entries:
            continue

        # Remove any kept class that is a super‑class of the candidate,
        # because the candidate is a more specific base.
        if isinstance(c, type):
            kept = [k for k in kept if not issubclass(c, k)]
        kept.append(c)
    return kept

