    """
    try:
        # The interface may provide a class level metadata dictionary
        # named `_attribute_metadata` or similar.  If present,
        # prefer that as the authoritative source.
        metadata = getattr(self, "_attribute_metadata", None)
        if metadata is not None:
            return dict(metadata)
    except Exception:
        # If underlying metadata handling errors, fall back to reflection.
        pass

    result = {}
    cls = self.__class__

    try:
        if not all:
            # Only attributes that are defined in the class dictionary
            # and are not callable (i.e., not methods).
            candidates = [
                name
                for name, val in cls.__dict__.items()
                if not name.startswith("_") and not callable(val)
            ]
        else:
            # Include everything that is not a dunder method.
            candidates = [
                name
                for name in dir(self)
                if not name.startswith("_") and not callable(getattr(self, name))
            ]
    except Exception:
        # In case of unexpected attribute errors, fall back to a simple
        # introspection on the instance's __dict__.
        candidates = [k for k in self.__dict__ if not k.startswith("_")]

    for name in candidates:
        try:
            attr = getattr(self, name)
            # Prefer a description attribute if present.
            description = getattr(attr, "description", None)
            if description is None:
                # Fall back to the docstring of the attribute (if any).
                description = getattr(attr, "__doc__", None)
            if not description:
                description = ""
        except Exception:
            description = ""

        result[name] = description

    return result

