def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    The method returns a string containing the CSV representation.
    """
    # Ensure separator is a string
    try:
        sep = str(separator)
    except Exception:
        raise ValueError("Separator must be convertible to string") from None

    # Prepare list of CSV lines
    lines = []
    if header is not None:
        lines.append(str(header))

    # Helper to flatten value into parts
    def _value_parts(val):
        # Treat strings as scalar
        if isinstance(val, (list, tuple)):
            for sub in val:
                yield str(sub)
        else:
            yield str(val)

    # Try iterating over points
    try:
        iterator = iter(self)
    except TypeError:
        raise ValueError("Object is not iterable and cannot be converted to CSV") from None

    for point in iterator:
        # Attempt to extract coordinate and value
        # Default assumptions: point is a tuple (coord, val)
        if isinstance(point, (tuple, list)) and len(point) == 2:
            coord, val = point
        else:
            # Try attribute names commonly used for Point objects
            coord = getattr(point, "coordinate", None)
            if coord is None:
                # Fallback: check for 'coords', 'x', 'y', etc.
                if hasattr(point, "coords"):
                    coord = point.coords
                elif hasattr(point, "x") or hasattr(point, "y"):
                    # Attempt to build coordinate from x and y
                    coord = tuple(getattr(point, attr) for attr in ("x", "y") if hasattr(point, attr))
                else:
                    # Cannot determine coordinate
                    coord = None
            val = getattr(point, "value", None)
            if val is None and hasattr(point, "val"):
                val = point.val
            if val is None and hasattr(point, "data"):
                val = point.data
            if coord is None and isinstance(point, (dict,)):
                # For dict: key is coordinate, value is val
                if "coordinate" in point:
                    coord = point["coordinate"]
                if "value" in point:
                    val = point["value"]

        # Build row components
        row_parts = []

        # Coordinate handling
        if coord is None:
            row_parts.append("")
        else:
            if isinstance(coord, (list, tuple)):
                row_parts.extend(map(str, coord))
            else:
                row_parts.append(str(coord))

        # Value handling
        if val is not None:
            row_parts.extend(_value_parts(val))

        lines.append(sep.join(row_parts))

    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV format.

    Parameters
    ----------
    separator : str, optional
        The delimiter used between values. Defaults to ",".
    header : str or None, optional
        If supplied, this string will be added as the first line of
        the CSV output.

    Returns
    -------
    str
        CSV representation of the graph.

    Notes
    -----
    The graph is assumed to expose its points as an iterable of
    ``(coordinate, value)`` tuples.  ``coordinate`` can be a scalar or an
    iterable (e.g., a list or tuple for multidimensional data).  ``value``
    can be a scalar or iterable.  Both are converted to strings and
    joined using *separator*.
    """
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    # Determine the iterable that yields the graph's points.
    try:
        points_iter = getattr(self, "points")
    except AttributeError:
        try:
            points_iter = getattr(self, "data")
        except AttributeError:
            try:
                points_iter = getattr(self, "iter")()
            except AttributeError:
                # Fallback: if the instance itself is iterable
                points_iter = self

    if not hasattr(points_iter, "__iter__"):
        raise TypeError("Graph points are not iterable")

    lines = []
    if header is not None:
        lines.append(header)

    for record in points_iter:
        try:
            coordinate, value = record
        except Exception:
            # If the record doesn't unpack into two parts, treat entire
            # record as the coordinate and assume an empty value.
            coordinate, value = record, None

        # Convert coordinate to string list
        if isinstance(coordinate, (list, tuple)):
            coord_strs = [str(c) for c in coordinate]
        else:
            coord_strs = [str(coordinate)]

        # Convert value to string list
        if value is None:
            val_strs = []
        elif isinstance(value, (list, tuple)):
            val_strs = [str(v) for v in value]
        else:
            val_strs = [str(value)]

        line_parts = coord_strs + val_strs
        lines.append(separator.join(line_parts))

    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    Parameters
    ----------
    separator : str, optional
        The character used to separate values in the output.  Default is ','.
    header : str or None, optional
        If provided, this string is inserted as the first line of the output,
        followed by a newline.

    Returns
    -------
    str
        A CSV representation of the graph.

    Notes
    -----
    Each point of the graph is expected to be a 2‑tuple ``(coord, value)``.
    If a point is not a 2‑tuple, the point is converted directly via ``str()``.
    ``coord`` and ``value`` are individually inspected; if they are iterable
    (but not strings), their elements are joined using the given separator.

    Example
    -------
    >>> g = Graph([...])
    >>> print(g.to_csv())
    """
    # Helper to test for iterable but not string
    def _is_iterable(obj):
        return hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes))

    lines = []

    # Add header if supplied
    if header is not None:
        if not isinstance(header, str):
            raise TypeError("header must be a string or None")
        lines.append(header)

    # Iterate over graph points
    for point_index, point in enumerate(self):
        try:
            # Attempt to unpack a 2‑tuple point
            if isinstance(point, tuple) and len(point) == 2:
                coord, value = point
            elif hasattr(point, "coord") and hasattr(point, "value"):
                coord, value = point.coord, point.value
            elif hasattr(point, "__iter__") and not isinstance(point, str):
                # Might be an iterable of length 2
                parts = list(point)
                if len(parts) == 2:
                    coord, value = parts[0], parts[1]
                else:
                    # Fallback: use str on whole point
                    coord, value = point, None
            else:
                # Fallback: treat entire point as a single value
                coord, value = point, None
        except Exception as exc:
            # Skip points that cannot be processed
            raise ValueError(f"Error processing point at index {point_index}: {exc}") from exc

        # Convert coordinate
        if coord is None:
            coord_str = ""
        elif _is_iterable(coord):
            try:
                coord_str = separator.join(str(c) for c in coord)
            except Exception as exc:
                raise ValueError(f"Unable to convert coordinate at index {point_index}: {exc}") from exc
        else:
            coord_str = str(coord)

        # Convert value
        if value is None:
            value_str = ""
        elif _is_iterable(value):
            try:
                value_str = separator.join(str(v) for v in value)
            except Exception as exc:
                raise ValueError(f"Unable to convert value at index {point_index}: {exc}") from exc
        else:
            value_str = str(value)

        # Combine coordinate and value with separator
        if coord_str and value_str:
            line = f"{coord_str}{separator}{value_str}"
        elif coord_str:
            line = coord_str
        else:
            line = value_str

        lines.append(line)

    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.
    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).
    """
    # Validate separator
    if not isinstance(separator, str):
        raise ValueError("separator must be a string")

    rows = []

    # Optional header
    if header is not None:
        if not isinstance(header, str):
            raise ValueError("header must be a string or None")
        rows.append(header)

    # Attempt to iterate over points. Assume that the graph object
    # can be iterated, yielding (coordinate, value) pairs.  Some
    # implementations use a ``points`` attribute instead, so handle
    # that as a fallback.
    try:
        iterator = iter(self)
    except TypeError:
        try:
            iterator = iter(getattr(self, "points"))
        except AttributeError:
            raise ValueError("The graph object does not provide points for CSV conversion")

    for idx, point in enumerate(iterator):
        # Each point may be a tuple (coord, value) or a custom object
        try:
            coord, value = point
        except Exception as exc:
            raise ValueError(f"Point at index {idx} is not iterable into (coord, value) pair: {exc}")

        # Handle coordinate
        if isinstance(coord, (list, tuple, set)):
            coord_parts = list(map(str, coord))
        else:
            coord_parts = [str(coord)]

        # Handle value
        if isinstance(value, (list, tuple, set)):
            value_parts = list(map(str, value))
        else:
            value_parts = [str(value)]

        # Combine and join using the separator
        row = separator.join(coord_parts + value_parts)
        rows.append(row)

    # Join all rows with newline characters
    return "\n".join(rows) + ("\n" if rows else "")

