            indices = err_map[coord_name]
        else:
            raise TypeError("Error indices mapping is neither a dict nor a list that can be indexed by the coordinate name.")

    # Convert the indices to a list of integers, if possible.
    if isinstance(indices, (list, tuple)):
        try:
            return [int(i) for i in indices]
        except Exception:
            raise ValueError("Error indices values must be convertible to integers.")
    else:
        try:
            return [int(indices)]
        except Exception:
            raise ValueError("Error indices value must be convertible to an integer.")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    err_col = f"{coord_name}_err"

    # Locate the data container (common names: _data, data, df, frame)
    data = getattr(self, "_data", None) or getattr(self, "data", None) or getattr(self, "df", None) or getattr(self, "frame", None)
    if data is None:
        raise AttributeError("No data attribute found on the instance. Expected '_data', 'data', 'df', or 'frame'.")

    # Basic check for pandas-like DataFrame
    if not hasattr(data, "columns"):
        raise AttributeError("Data attribute must have a 'columns' attribute.")
    if err_col not in data.columns:
        raise KeyError(f"Error column '{err_col}' not found in data columns.")

    err_series = data[err_col]

    try:
        # Compute mask for non‑null and positive error values
        mask = err_series.notna() & (err_series > 0)
    except Exception:
        # Fallback for non‑numeric data (attempt to cast to float)
        mask = err_series.notna()
        for idx, val in enumerate(err_series):
            try:
                mask[idx] = float(val) > 0
            except Exception:
                mask[idx] = False

    # Return index values where mask is True
    # Ensure the index is iterable (pandas index, list, or array)
    try:
        return list(data.index[mask])
    except Exception:
        # For non‑pandas structures, fall back to numeric indices
        return [i for i, m in enumerate(mask) if m]

def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.
    """
    # Validate input
    if not isinstance(context, dict):
        raise TypeError("context must be a dictionary")

    # Ensure the error sub‑dict exists
    error_context = context.setdefault('error', {})

    # Determine the coordinate ordering (first three coordinates map to x, y, z)
    coordinates = getattr(self, 'coordinates', None)
    if coordinates is None:
        coordinates = getattr(self, 'coords', None)
    if not isinstance(coordinates, (list, tuple)):
        coordinates = []

    coord_map = {}
    if len(coordinates) > 0:
        coord_map[coordinates[0]] = 'x'
    if len(coordinates) > 1:
        coord_map[coordinates[1]] = 'y'
    if len(coordinates) > 2:
        coord_map[coordinates[2]] = 'z'

    # Inspect attributes for error fields
    for attr_name in dir(self):
        if not attr_name.startswith('error_'):
            continue

        # Parse attribute name (expected format: error_<coord>_<type>)
        parts = attr_name.split('_', 2)
        if len(parts) < 3:
            continue
        _, coord_name, error_type = parts[0], parts[1], parts[2]

        # Map coordinate to 'x', 'y', or 'z' if applicable
        error_coord = coord_map.get(coord_name, coord_name)

        # Build the key used in the context error mapping
        ctx_key = f"{error_coord}_{error_type}"

        # Retrieve the attribute value
        try:
            value = getattr(self, attr_name)
        except Exception:
            continue

        # Determine indices of errors
        indices = []
        try:
            # If the value is an iterable (e.g., list/array of indices or error values)
            if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
                for idx, val in enumerate(value):
                    # Consider non‑None, non‑zero values as indicative of an error
                    if val is not None and val:
                        indices.append(idx)
            # If the value itself is an integer or float, treat it as a single index
            elif isinstance(value, (int, float)):
                indices.append(int(value))
            # If the value is a dict with an 'index' key (common in some graph frameworks)
            elif isinstance(value, dict) and 'index' in value:
                indices.append(int(value['index']))
        except Exception:
            pass

        # If indices were found, add to the error context
        if indices:
            # In case of multiple indices, store them as a list; otherwise, just store the single value
            stored_value = {"index": indices[0]} if len(indices) == 1 else {"index": indices}
            # Preserve any pre‑existing entry for the same key by merging
            if ctx_key in error_context:
                existing = error_context[ctx_key]
                if isinstance(existing, dict) and 'index' in existing:
                    existing_idx = existing['index']
                    # Combine single values into a list
                    if not isinstance(existing_idx, list):
                        existing_idx = [existing_idx]
                    if isinstance(stored_value['index'], list):
                        existing_idx.extend(stored_value['index'])
                    else:
                        existing_idx.append(stored_value['index'])
                    error_context[ctx_key]['index'] = existing_idx
            else:
                error_context[ctx_key] = stored_value

    # Nothing to return; the context dict is mutated in place.

