    # Iterate over attributes of self to find error descriptors
    for attr_name in dir(self):
        try:
            if not isinstance(attr_name, str):
                continue
        except Exception:
            continue
        if not attr_name.startswith("error_"):
            continue
        # Expected pattern: error_<field>_<suffix>
        parts = attr_name.split("_")
        if len(parts) < 3:
            continue
        field_name = parts[1]
        suffix = "_".join(parts[2:])
        # Locate field index
        idx = field_index_map.get(str(field_name))
        if idx is None:
            # Try alternative lookup: maybe field stored in mapping
            try:
                idx = attributes := getattr(self, "__dict__", {}).get("_fields", None)
                if idx is not None and field_name in idx:
                    idx = idx.index(field_name)
                else:
                    continue
            except Exception:
                continue
        # Determine coordinate key ('x','y','z' or fallback)
        coord_key = "xyz"[idx] if idx < 3 else field_name.lower()
        # Build final key, e.g., "x_low" or "t_high"
        key = f"{coord_key}_{suffix}"
        # Append to errors_dict without overriding existing entries
        existing = errors_dict.get(key)
        if existing is None:
            errors_dict[key] = {"index": idx}
        else:
            # If existing does not contain index, add it
            if isinstance(existing, dict) and "index" not in existing:
                existing["index"] = idx
            elif isinstance(existing, dict) and isinstance(existing["index"], list):
                if idx not in existing["index"]:
                    existing["index"].append(idx)
    # No explicit return value needed; context is mutated in place.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to lists to allow indexing
    try:
        bins_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable of numeric values")
    try:
        edges_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable of numeric values")

    # Basic length checks
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("Number of edges must be exactly one more than number of bins")

    total = 0.0
    for i, (b, e0, e1) in enumerate(zip(bins_list, edges_list, edges_list[1:])):
        # Validate edge values
        try:
            width = float(e1) - float(e0)
        except Exception as exc:
            raise TypeError(f"Edge values must be numeric (edge {i} and {i+1})") from exc

        if width < 0:
            raise ValueError(f"Edges are not monotonically increasing: edge[{i}] > edge[{i+1}]")

        # Validate bin value
        try:
            bin_val = float(b)
        except Exception as exc:
            raise TypeError(f"Bin values must be numeric (bin {i})") from exc

        total += bin_val * width

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to lists of floats
    try:
        bins_list = list(bins)
    except Exception as exc:
        raise TypeError(f"bins must be an iterable, got {type(bins).__name__}") from exc
    try:
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError(f"edges must be an iterable, got {type(edges).__name__}") from exc

    # Validate lengths
    if len(edges_list) < 2:
        raise ValueError("edges must contain at least two boundary values")
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError(f"Number of bins ({len(bins_list)}) does not match number of edges minus one ({len(edges_list)-1})")

    # Compute the integral as sum(bins * widths)
    integral_value = 0.0
    for i, (b, e_start, e_end) in enumerate(zip(bins_list, edges_list[:-1], edges_list[1:])):
        try:
            bin_val = float(b)
            width = float(e_end) - float(e_start)
        except Exception as exc:
            raise TypeError(f"Bin and edge values must be numeric at index {i}") from exc
        integral_value += bin_val * width

    return integral_value

