                    if level == -1 or depth < level:
                        sub_result = _diff(value, other_value, depth + 1)
                        if sub_result:
                            result[key] = sub_result
                    else:
                        # Depth limit reached; consider them differing if unequal.
                        if value != other_value:
                            result[key] = value
                else:
                    # Non-dict values; include if they differ.
                    if value != other_value:
                        result[key] = value
