        except IndexError:
            # Should not happen due to earlier expansion
            target = {}
            last_applied_manifest.append(target)

        # Handle primitive items directly
        if not isinstance(resp_item, dict) or not isinstance(target, dict):
            if i >= len(last_applied_manifest) or last_applied_manifest[i] != resp_item:
                last_applied_manifest[i] = resp_item
            continue

        # Iterate over observed fields
        for field in observer_schema:
            # The field definition may be a string (field name) or a dict
            # with metadata. We attempt to extract the key name.
            if isinstance(field, str):
                key = field
            elif isinstance(field, dict):
                key = field.get("name") or field.get("field")
                if key is None:
                    # Unsupported schema format; skip
                    continue
            else:
                # Unsupported schema type; skip
                continue

            # If the response contains a value for the key but it isn't
            # yet in the target, copy it over. This preserves values
            # that have already been set manually.
            if key in resp_item and key not in target:
                target[key] = resp_item[key]

            # If the value is a nested dict/list, recursively apply the
            # update logic for that nested structure.
            if key in resp_item:
                sub_resp = resp_item[key]
                sub_target = target.get(key, {} if isinstance(sub_resp, dict) else [])
                if isinstance(sub_resp, dict) and isinstance(sub_target, dict):
                    # Recursive dict handling
                    try:
                        target[key] = update_last_applied_manifest_dict_from_resp(
                            sub_target, field.get("children", []), sub_resp
                        )
                    except Exception:
                        # If the helper is not available or fails, fall back
                        target[key] = sub_resp
                elif isinstance(sub_resp, list) and isinstance(sub_target, list):
                    # Recursive list handling
                    try:
                        target[key] = update_last_applied_manifest_list_from_resp(
                            sub_target, field.get("children", []), sub_resp
                        )
                    except Exception:
                        target[key] = sub_resp

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` dictionary with the
    values from a partial Kubernetes ``response`` based on an ``observer_schema``.

    The function walks through each key defined in ``observer_schema``, ensuring
    that the corresponding key is present in ``last_applied_manifest``. If a
    value is not already present it is initialized from ``response``. Nested
    dicts are handled with a recursive call to this function, while lists are
    delegated to ``update_last_applied_manifest_list_from_resp`` (assumed to be
    defined elsewhere).

    Args:
        last_applied_manifest (dict): The manifest dictionary to update.
        observer_schema (dict): Schema describing which fields to observe.
        response (dict): The Kubernetes API response containing the data to
            copy.

    Raises:
        KeyError: If a field listed in ``observer_schema`` is not present in
            ``response``.
    """
    for key, schema_val in observer_schema.items():
        # Validate that the response contains the key
        if key not in response:
            raise KeyError(
                f"Field '{key}' defined in observer schema is missing from the response"
            )

        # Handle nested dictionaries
        if isinstance(schema_val, dict):
            # Ensure the target key exists as a dict
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], dict
            ):
                last_applied_manifest[key] = {}
            # Recurse into the nested dictionary
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema_val, response[key]
            )

        # Handle lists (the list handling is delegated to a separate function)
        elif isinstance(schema_val, list):
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], list
            ):
                last_applied_manifest[key] = []
            # Delegate list handling
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], schema_val, response[key]
            )

        # Handle primitive fields – initialize only if missing
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: A mapping from Kubernetes kind to its default observer JSON schema.
    """
    try:
        # Ensure we have a manifest list to iterate over
        manifest = getattr(getattr(app, "spec", None), "manifest", [])
        if not isinstance(manifest, list):
            manifest = []
    except Exception:
        manifest = []

    # Custom observer schemas that user might have defined
    custom_schemas = getattr(getattr(app, "spec", None), "custom_observers", {})
    if not isinstance(custom_schemas, dict):
        custom_schemas = {}

    default_schemas = {}
    for resource in manifest:
        # Skip non‑dict entries
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        # Skip kinds that already have custom schemas
        if kind in custom_schemas:
            continue
        # Build a minimal default schema
        default_schemas[kind] = {
            "type": "object",
            "description": f"Default observer schema for {kind} resources",
            "additionalProperties": True,
        }

    return default_schemas

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from a unique resource identifier (in the form
        ``<kind>:<name>`` or just ``<kind>`` if no name is available) to a simple
        default schema. Existing custom schemas in ``app.spec.observer`` are
        preserved and not overwritten.
    """
    # Defensive input checks
    if app is None:
        raise TypeError("The 'app' parameter must not be None.")

    # Extract the manifest list; raise helpful errors on failure
    try:
        manifest = getattr(app.spec, 'manifest')
    except AttributeError:
        raise AttributeError("The application object must have a 'spec.manifest' attribute.")
    if manifest is None:
        raise ValueError("The application spec contains no manifest (manifest is None).")
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("The 'spec.manifest' attribute must be a list or tuple of resource dicts.")

    # Existing observer schemas, if any
    try:
        custom_schemas = getattr(app.spec, 'observer', {})
        if not isinstance(custom_schemas, dict):
            custom_schemas = {}
    except AttributeError:
        custom_schemas = {}

    default_schemas = {}
    for idx, res in enumerate(manifest):
        # Ensure res is a mapping
        if not isinstance(res, dict):
            raise TypeError(f"Manifest entry at index {idx} is not a dict.")

        # Build a unique key: kind:name if name exists, else kind only
        kind = res.get('kind', f'UnknownKind{idx}')
        metadata = res.get('metadata', {})
        name = None
        if metadata and isinstance(metadata, dict):
            name = metadata.get('name')
        key = f"{kind}:{name}" if name else kind

        # Skip if a custom schema is already defined for this key
        if key in custom_schemas:
            continue

        # For default, we use a minimal empty-object schema to allow any payload.
        # In a real implementation this might be a more sophisticated schema.
        default_schemas[key] = {"type": "object"}

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    Returns:
        dict: A mapping of resource kind to a minimal observer schema
    """
    try:
        # Safely extract the manifest list
        manifest = getattr(app, "spec", None)
        if manifest is None:
            return {}
        manifest = getattr(manifest, "manifest", None)
        if manifest is None:
            return {}

        # Existing custom observer schemas
        custom_schema = getattr(app.spec, "observer_schema", None)
        if custom_schema is None:
            custom_schema = {}

        default_schema = {}

        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not isinstance(kind, str):
                continue
            if kind in custom_schema:
                # Skip kinds that already have a custom schema
                continue

            # Build a very generic observer schema for this kind
            default_schema[kind] = {
                "metadata": {"name": {"type": "string"}},
                "spec": {"type": "object"},
                "status": {"type": "object"},
            }

        return default_schema
    except Exception:
        # In case of any unexpected error, return an empty schema
        return {}

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            return {}

        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            return {}

        # Convert manifest into an iterable list of resources
        if isinstance(manifest, dict):
            # If the manifest is a dict, assume its values are the resources
            resources = list(manifest.values())
        elif isinstance(manifest, (list, tuple)):
            resources = manifest
        else:
            # Unsupported format
            return {}

        # Custom schemas that the user has already defined
        custom_schemas = getattr(spec, "observer_schema", {})

        default_schemas = {}
        for resource in resources:
            if not isinstance(resource, dict):
                # Skip any non-dict entries
                continue

            kind = resource.get("kind")
            name = (
                resource.get("metadata", {})
                .get("name")
                if isinstance(resource.get("metadata", {}), dict)
                else None
            )

            # Skip resources that do not have both kind and name
            if not kind or not name:
                continue

            # If a custom schema already exists for this kind, skip it
            if kind in custom_schemas:
                continue

            # Create a very simple default schema
            # This can be expanded in the future to include more detailed fields
            # Here we just store the kind and name in the metadata section
            default_schemas[kind] = {
                "kind": kind,
                "metadata": {"name": name},
            }

        return default_schemas
    except Exception:
        # In case something unexpected happens, return an empty dict
        return {}

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application has a spec attribute
    if not hasattr(app, "spec"):
        raise AttributeError("The application object does not contain a 'spec' attribute.")

    # Retrieve the list of resources from the application's manifest
    manifest = getattr(app.spec, "manifest", None)
    if not isinstance(manifest, (list, tuple)):
        raise TypeError(
            "The `spec.manifest` attribute should be a list or tuple of resource objects."
        )

    # Retrieve any pre‑existing observer schemas
    observers = getattr(app.spec, "observers", [])
    if not isinstance(observers, (list, tuple)):
        raise TypeError("The `spec.observers` attribute should be a list or tuple.")

    # Build a lookup set of (kind, name) pairs that already have an observer schema
    existing = set()
    for obs in observers:
        try:
            # Different implementations might expose these attributes directly or through a
            # nested metadata dict. We try the most common patterns.
            kind = getattr(obs, "kind", None)
            if kind is None:
                kind = getattr(obs, "resource", None)
            name = (
                getattr(obs, "metadata", None)
                or getattr(obs, "metadata_name", None)
                or getattr(obs, "target_name", None)
            )
            if kind and name:
                existing.add((kind, name))
        except Exception:
            # If we cannot introspect this observer, ignore it
            continue

    # Determine which visitor helper to use for creating a new schema
    ObserverType = None
    if observers:
        ObType = type(observers[0])
        # If the observer type can be instantiated with keyword arguments, we will use it
        try:
            # Attempt a minimal construction to see if it works
            ObType(kind="temp", metadata={"name": "temp"})
            ObserverType = ObType
        except Exception:
            ObserverType = None

    # Generate default observer schemas for resources that lack one
    default_schemas = []
    for res in manifest:
        try:
            kind = getattr(res, "kind", None)
            name = (
                getattr(res, "metadata", {})
                or getattr(res, "name", None)
                or getattr(res, "metadata_name", None)
            )
            # Try nested metadata dict
            if isinstance(name, dict):
                name = name.get("name")
        except Exception:
            continue

        if not kind or not name:
            continue

        if (kind, name) in existing:
            continue

        if ObserverType:
            # Build a new observer schema using the discovered type
            try:
                oh = ObserverType(
                    kind=kind,
                    metadata={"name": name},
                    spec={"predicate": {"type": "default"}, "timeout": 60},
                )
                default_schemas.append(oh)
            except Exception:
                # Fallback to dict if the constructor fails
                oh = {
                    "kind": kind,
                    "metadata": {"name": name},
                    "spec": {"predicate": {"type": "default"}, "timeout": 60},
                }
                default_schemas.append(oh)
        else:
            # Fallback: use a plain dictionary representation
            oh = {
                "kind": kind,
                "metadata": {"name": name},
                "spec": {"predicate": {"type": "default"}, "timeout": 60},
            }
            default_schemas.append(oh)

    # Attach the generated schemas to the application's spec
    new_observers = list(observers) + default_schemas
    setattr(app.spec, "observers", new_observers)

    return None

def formatmany(self, sql, many_params):
    """
    Convert a SQL query using in‑style parameters to use an out‑style
    parameter placeholder accepted by most DBAPI drivers and return the
    converted query together with a list of parameter sets suitable for
    ``cursor.executemany``.  Parameters are validated to ensure that
    the number of placeholders matches the number of provided values and
    that the correct parameter type is used (mapping for named, sequence
    for ordinal placeholders).

    The original type of *sql* is preserved; if a ``bytes`` object is passed,
    the returned query will also be ``bytes``.  Argument validation errors
    raise :class:`ValueError` or :class:`TypeError` as appropriate.
    """
    import re
    from collections.abc import Mapping, Sequence, Iterable

    # Preserve the original type of sql (bytes or str)
    is_bytes = isinstance(sql, (bytes, bytearray))
    if is_bytes:
        sql_text = sql.decode()
    else:
        sql_text = str(sql)

    # Regular expressions for named and ordinal placeholders
    named_re = re.compile(r":(\w+)")
    ordinal_re = re.compile(r"\?")

    # Detect style: named if a named placeholder occurs, otherwise ordinal
    if named_re.search(sql_text):
        style = "named"
    elif ordinal_re.search(sql_text):
        style = "ordinal"
    else:
        # No placeholders detected – nothing to do
        return sql, []

    # Build list of placeholder identifiers in order of appearance
    if style == "named":
        placeholders = named_re.findall(sql_text)
    else:
        placeholders = ordinal_re.findall(sql_text)

    if not placeholders:
        # No placeholders – return original sql and an empty params list
        return sql, []

    # Replace all in‑style placeholders with SQLite/DBAPI style '?' placeholders
    if style == "named":
        formatted_sql = named_re.sub("?", sql_text)
    else:
        formatted_sql = sql_text

    # Prepare the list of converted parameter sets
    out_params = []
    placeholder_count = len(placeholders)

    # Helper to convert a single parameter set
    def _convert_param_set(params):
        if style == "named":
            if not isinstance(params, Mapping):
                raise TypeError(
                    f"Named style SQL expects a mapping for each parameter set, got "
                    f"{type(params).__name__}"
                )
            # Ensure all required keys are present
            for name in placeholders:
                if name not in params:
                    raise KeyError(f"Missing parameter '{name}' in mapping")
            # Build list of values in the order of placeholders (duplicates allowed)
            return [params[name] for name in placeholders]
        else:
            # Ordinal style
            if not isinstance(params, Sequence) or isinstance(params, (str, bytes)):
                raise TypeError(
                    f"Ordinal style SQL expects a sequence for each parameter set, got "
                    f"{type(params).__name__}"
                )
            if len(params) != placeholder_count:
                raise ValueError(
                    f"Expected {placeholder_count} parameters, got {len(params)}"
                )
            return list(params)

    # Iterate over the iterable of parameter sets
    for idx, param_set in enumerate(many_params):
        try:
            out_params.append(_convert_param_set(param_set))
        except Exception as exc:
            raise type(exc)(f"Error processing param set at index {idx}: {exc}") from exc

    # Return using the original sql type
    if is_bytes:
        return formatted_sql.encode(), out_params
    return formatted_sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        import json
    except Exception:
        return False

    # Determine if path is a filesystem path (string) or a pyfilesystem object
    if isinstance(path, str):
        if not os.path.isdir(path):
            return False
        fs_root = path
        is_fs = False
    elif hasattr(path, "listdir") or hasattr(path, "getinfo"):
        # Assume pyfilesystem interface
        fs_root = path
        is_fs = True
    else:
        return False

    # Helper functions for existence checks
    def _exists(file_path):
        if is_fs:
            try:
                # listdir returns list of file names for the given directory
                return file_path in fs_root.listdir("")
            except Exception:
                return False
        else:
            return os.path.isfile(file_path)

    def _open(file_path, mode="r"):
        if is_fs:
            try:
                return fs_root.open(file_path, mode)
            except Exception:
                return None
        else:
            try:
                return open(file_path, mode, encoding="utf-8")
            except Exception:
                return None

    # Check for mandatory `.ocfl.json` file
    ocfl_json_path = ".ocfl.json" if is_fs else os.path.join(fs_root, ".ocfl.json")
    if not _exists(ocfl_json_path):
        return False

    # Read and parse the JSON descriptor
    try:
        with _open(ocfl_json_path, "r") as f:
            if f is None:
                return False
            data = json.load(f)
    except Exception:
        return False

    # A minimal valid OCFL object must contain the `ocfl_version` key
    if not isinstance(data, dict) or "ocfl_version" not in data:
        return False

    # Optional content validation can be added here (warnings allowed)
    # For now, we consider the object valid if it passes the above checks.
    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        from pathlib import Path
        import json, re, hashlib
    except Exception:
        # Required modules not available
        return False
    # Normalize input to Path
    try:
        p = Path(path)
    except Exception:
        return False
    # Ensure path exists
    if not p.exists():
        return False
    # Resolve to directory
    if p.is_file():
        p = p.parent
    # Find the OCFL object root (nearest ancestor containing .ocfl-info)
    root = None
    for candidate in [p] + list(p.parents):
        if (candidate / ".ocfl-info").exists():
            root = candidate
            break
    if root is None:
        return False
    # Load .ocfl-info
    try:
        with open(root / ".ocfl-info", "r", encoding="utf-8") as f:
            info = json.load(f)
    except Exception:
        return False
    # Basic checks for required keys
    required_keys = {"format", "contentDigestAlgorithm", "manifestDigestAlgorithm"}
    if not required_keys.issubset(info.keys()):
        return False
    # Get checksum algorithm names (case-insensitive)
    content_algo = info["contentDigestAlgorithm"].upper()
    manifest_algo = info["manifestDigestAlgorithm"].upper()
    # Verify at least one version directory exists: "vxxxx" pattern
    version_dirs = [d for d in root.iterdir() if d.is_dir() and re.match(r"^v\d{4}$", d.name)]
    if not version_dirs:
        return False
    # Validate each version directory
    for ver in sorted(version_dirs):
        # Ensure hashmanifest file exists
        manifest_file = ver / "hashmanifest.txt"
        if not manifest_file.exists():
            # Missing manifest file is a fatal error
            return False
        # Parse hashmanifest lines
        try:
            with open(manifest_file, "r", encoding="utf-8") as mf:
                lines = mf.readlines()
        except Exception:
            return False
        # Build a mapping from path to expected digest
        expected_hashes = {}
        for line in lines:
            parts = line.strip().split(",")
            if len(parts) != 2:
                # Malformed line
                return False
            rel_path, digest = parts
            expected_hashes[Path(rel_path)] = digest.lower()
        # Verify each file present and digest matches
        for rel_path, expected_digest in expected_hashes.items():
            abs_file = ver / rel_path
            if not abs_file.exists() or not abs_file.is_file():
                return False
            try:
                hasher = hashlib.new(content_algo)
            except Exception:
                return False
            try:
                with open(abs_file, "rb") as fh:
                    for chunk in iter(lambda: fh.read(8192), b""):
                        hasher.update(chunk)
            except Exception:
                return False
            if hasher.hexdigest().lower() != expected_digest:
                return False
    # All checks passed
    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Import here to avoid module level imports
        import os
    except Exception:
        return False

    # Ensure the path exists and is a directory
    if not os.path.isdir(path):
        return False

    # OCFL root should contain a .ocfl-root file
    ocfl_root_file = os.path.join(path, ".ocfl-root")
    if not os.path.isfile(ocfl_root_file):
        return False

    # Load the .ocfl-root file to confirm basic structure
    try:
        with open(ocfl_root_file, "r", encoding="utf-8") as f:
            content = f.read()
        # Simple check: file shouldn't be empty
        if not content.strip():
            return False
    except Exception:
        return False

    # The root must contain an 'objects' directory
    objects_dir = os.path.join(path, "objects")
    if not os.path.isdir(objects_dir):
        return False

    # For each object directory, perform minimal validation
    try:
        for entry in os.listdir(objects_dir):
            obj_path = os.path.join(objects_dir, entry)
            if not os.path.isdir(obj_path):
                continue  # Skip non-directories
            # Each object should have a 'object-id.json'
            obj_id_file = os.path.join(obj_path, "object-id.json")
            if not os.path.isfile(obj_id_file):
                return False
            # At least one version directory (numeric)
            versions = [
                d
                for d in os.listdir(obj_path)
                if os.path.isdir(os.path.join(obj_path, d)) and d.isdigit()
            ]
            if not versions:
                return False
            # Basic check: each version directory should contain a 'manifest.json'
            for v in versions:
                vdir = os.path.join(obj_path, v)
                if not os.path.isfile(os.path.join(vdir, "manifest.json")):
                    return False
    except Exception:
        return False

    # If all checks pass, return True
    return True

