    if not isinstance(prefix, str):
        raise TypeError("prefix must be of type str")

    status_parts = []

    # Determine base status
    try:
        is_valid = getattr(self, 'valid', None)
        if is_valid is None:
            is_valid = getattr(self, 'is_valid', None)
    except Exception:
        is_valid = None

    if is_valid is True:
        status_parts.append('VALID')
    elif is_valid is False:
        status_parts.append('INVALID')
    else:
        # If we cannot determine validity, try to infer
        errors = getattr(self, 'errors', None)
        try:
            if errors is None or (hasattr(errors, '__len__') and len(errors) == 0):
                status_parts.append('VALID')
            else:
                status_parts.append('INVALID')
        except Exception:
            status_parts.append('UNKNOWN')

    # Add error/warning counts if available
    for attr_name, label in (('errors', 'errors'), ('warnings', 'warnings')):
        attr = getattr(self, attr_name, None)
        if attr is not None:
            try:
                count = len(attr)
                if count > 0:
                    status_parts.append(f'{label}={count}')
            except Exception:
                # If we can't determine length, skip
                pass

    # Add any custom message attribute if present
    custom_msg = getattr(self, 'message', None)
    if isinstance(custom_msg, str) and custom_msg:
        status_parts.append(custom_msg)

    status_str = ', '.join(status_parts)
    return f'{prefix} {status_str}'.strip() if prefix else status_str

