    elif hasattr(self, 'valid') and isinstance(getattr(self, 'valid'), bool):
        status_val = "PASS" if getattr(self, 'valid') else "FAIL"

    # 3. Check for 'errors' attribute; if there are no errors we consider it PASS
    elif hasattr(self, 'errors') and isinstance(getattr(self, 'errors'), (list, tuple, set, dict)):
        errors = getattr(self, 'errors')
        if isinstance(errors, dict):
            err_str = ', '.join(f"{k}={v}" for k, v in errors.items())
        else:
            err_str = ', '.join(map(str, errors))
        status_val = "PASS" if not errors else f"FAIL: {err_str}"

    # Fallback if none of the expected attributes are found
    else:
        status_val = "STATUS UNKNOWN"

