def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a dict
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine specification version
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # Accept common type identifiers
            if type_val.lower() in ('inventory_v1', 'v1', 'type_v1'):
                self.spec_version = 'v1'
            elif type_val.lower() in ('inventory_v2', 'v2', 'type_v2'):
                self.spec_version = 'v2'
            else:
                # Fall back to default spec_version if available
                if not hasattr(self, 'spec_version') or self.spec_version is None:
                    raise ValueError(f"Unrecognized type value '{type_val}' and no default spec_version set")
        else:
            # No valid type field, use default if set
            if not hasattr(self, 'spec_version') or self.spec_version is None:
                raise ValueError("No type value provided and no default spec_version set")

    # Specify validation rules per spec_version
    if self.spec_version == 'v1':
        required_keys = {'name', 'hosts'}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(f"Missing required keys for spec v1: {missing}")

        hosts = inventory.get('hosts')
        if not isinstance(hosts, list):
            raise ValueError("In spec v1, 'hosts' must be a list")

        for idx, host in enumerate(hosts):
            if not isinstance(host, dict):
                raise ValueError(f"Host at index {idx} is not a dict")
            if 'hostname' not in host or 'ip' not in host:
                raise ValueError(f"Host at index {idx} missing 'hostname' or 'ip' fields")

    elif self.spec_version == 'v2':
        required_keys = {'name', 'nodes'}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(f"Missing required keys for spec v2: {missing}")

        nodes = inventory.get('nodes')
        if not isinstance(nodes, dict):
            raise ValueError("In spec v2, 'nodes' must be a dict")

        for node_name, node_info in nodes.items():
            if not isinstance(node_info, dict):
                raise ValueError(f"Node '{node_name}' info is not a dict")
            if 'hostname' not in node_info:
                raise ValueError(f"Node '{node_name}' missing 'hostname' field")

    else:
        raise ValueError(f"Unsupported specification version '{self.spec_version}'")

    return True

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Basic input checks
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a dictionary")

        # Allowed specification types
        valid_types = {"1.0": ["git", "https", "local"],
                       "2.0": ["git", "https", "s3", "local"]}

        # Determine spec_version if requested
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            inv_type = inventory.get("type")
            if inv_type and isinstance(inv_type, str):
                # Determine spec_version based on type presence
                for ver, types in valid_types.items():
                    if inv_type in types:
                        spec_version = ver
                        break
            # If still no spec_version, fall back to self.spec_version
            if not spec_version:
                spec_version = getattr(self, "spec_version", None)
        if not spec_version:
            raise ValueError("Specification version could not be determined")

        # Basic inventory checks based on spec_version
        required_keys = ["url"]
        if spec_version == "2.0":
            required_keys.append("metadata")

        missing = [k for k in required_keys if k not in inventory]
        if missing:
            raise ValueError(f"Missing required keys for spec_version {spec_version}: {missing}")

        # Type-specific validation
        if "type" in inventory:
            inv_type = inventory["type"]
            if not isinstance(inv_type, str):
                raise ValueError("inventory type must be a string")
            if inv_type not in valid_types.get(spec_version, []):
                raise ValueError(f"Unsupported inventory type '{inv_type}' for spec_version {spec_version}")

        # After any checks pass, update instance's spec_version if extracted
        if extract_spec_version and spec_version != getattr(self, "spec_version", None):
            self.spec_version = spec_version

        return True

    except Exception as exc:
        raise ValueError(f"Inventory validation failed: {exc}") from exc

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, (list, set, tuple)):
        raise TypeError(f"Expected manifest_files to be a list, set, or tuple, got {type(manifest_files).__name__}")
    if not isinstance(digests_used, (list, set, tuple)):
        raise TypeError(f"Expected digests_used to be a list, set, or tuple, got {type(digests_used).__name__}")

    manifest_set = set(manifest_files)
    used_set = set(digests_used)

    # Digests in the manifest that are not used
    missing_in_used = manifest_set - used_set
    if missing_in_used:
        raise ValueError(
            f"Digests required by the manifest but not used: {', '.join(sorted(missing_in_used))}"
        )

    # Digests that are used but not present in the manifest
    unused_in_manifest = used_set - manifest_set
    if unused_in_manifest:
        raise ValueError(
            f"Digests used but not present in the manifest: {', '.join(sorted(unused_in_manifest))}"
        )
    return None

