def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if not isinstance(manifest_files, (list, tuple)):
        raise TypeError("manifest_files must be a list or tuple")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set or list or tuple")
    digests_used_set = set(digests_used)

    # Extract digests from manifest files
    manifest_digests = set()
    for mf in manifest_files:
        if not isinstance(mf, dict):
            continue
        digest = mf.get('digest')
        if isinstance(digest, str):
            manifestation = digest.strip()
            if manifestation:
                manifest_digests.add(manifestation)

    # Determine discrepancies
    missing_in_used = manifest_digests - digests_used_set
    missing_in_manifest = digests_used_set - manifest_digests
    errors = []

    if missing_in_used:
        errors.append(
            f"Digests present in manifest but not used: {sorted(missing_in_used)}"
        )
    if missing_in_manifest:
        errors.append(
            f"Digests used but not present in manifest: {sorted(missing_in_manifest)}"
        )

    if errors:
        raise ValueError("; ".join(errors))

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and existence checks
    if prior is None:
        raise ValueError("prior cannot be None.")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}.")

    # Retrieve inventory containers (attributes or dicts)
    try:
        self_inventory = getattr(self, "inventory")
    except AttributeError as exc:
        raise ValueError("Current instance must have an 'inventory' attribute.") from exc

    try:
        prior_inventory = getattr(prior, "inventory")
    except AttributeError as exc:
        raise ValueError("Prior instance must have an 'inventory' attribute.") from exc

    # Functions to get value from dicts or objects
    def _get(attr_obj, names):
        for name in names:
            if isinstance(attr_obj, dict) and name in attr_obj:
                return attr_obj[name]
            if hasattr(attr_obj, name):
                return getattr(attr_obj, name)
        return None

    # Identify inventory (e.g., id, uuid, name)
    self_id = _get(self_inventory, ("id", "uuid", "name"))
    prior_id = _get(prior_inventory, ("id", "uuid", "name"))

    if self_id is None or prior_id is None:
        raise ValueError("Both inventories must expose an identifier (id/uuid/name).")

    if self_id != prior_id:
        raise ValueError("Inventory identifiers do not match; cannot validate prior version.")

    # Retrieve versions
    self_version = _get(self_inventory, ("version", "ver", "rev"))
    prior_version = _get(prior_inventory, ("version", "ver", "rev"))

    if self_version is None or prior_version is None:
        raise ValueError("Both inventories must expose a numeric version value.")

    if not isinstance(self_version, (int, float)) or not isinstance(prior_version, (int, float)):
        raise TypeError("Inventory versions must be numeric.")

    # Ensure prior is indeed older
    if prior_version >= self_version:
        raise ValueError("Prior inventory must have a lower version number than the current inventory.")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic input validation
    if prior is None:
        raise ValueError("The `prior` argument cannot be None.")
    if not isinstance(prior, type(self)):
        raise TypeError(f"`prior` must be an instance of {type(self).__name__}, got {type(prior).__name__}.")
    try:
        # Retrieve and validate the inventory_version attributes
        current_version = getattr(self, "inventory_version", None)
        prior_version = getattr(prior, "inventory_version", None)
        if current_version is None or prior_version is None:
            raise AttributeError("Both inventory objects must expose an 'inventory_version' attribute.")
        if not isinstance(current_version, int) or not isinstance(prior_version, int):
            raise TypeError("The 'inventory_version' attribute must be of type int.")
        # Ensure the prior version is indeed older than the current one
        if prior_version >= current_version:
            raise ValueError(f"Prior version ({prior_version}) must be less than current version ({current_version}).")
    except Exception as exc:
        # Wrap and re‑raise with a clearer message
        raise ValueError(f"Failed to validate inventory versions: {exc}") from exc

    # Optional consistency checks based on a dictionary representation
    has_to_dict_self = hasattr(self, "to_dict") and callable(getattr(self, "to_dict"))
    has_to_dict_prior = hasattr(prior, "to_dict") and callable(getattr(prior, "to_dict"))
    if has_to_dict_self and has_to_dict_prior:
        try:
            self_dict = self.to_dict()
            prior_dict = prior.to_dict()
            if not isinstance(self_dict, dict) or not isinstance(prior_dict, dict):
                raise TypeError("`to_dict` must return a dictionary.")
            # Ensure all keys in the prior appear in the current inventory
            unexpected_keys = set(prior_dict) - set(self_dict)
            if unexpected_keys:
                raise ValueError(f"Prior inventory contains keys not present in current inventory: {sorted(unexpected_keys)!r}.")
        except Exception as exc:
            raise ValueError(f"Failed to compare inventory dictionary representations: {exc}") from exc

    # If all checks pass, the prior inventory is considered valid
    return None

def validate_as_prior_version(self, prior):
    """
