    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Expected prior to be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}."
        )
    # Ensure the objects have a version or timestamp for ordering
    self_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if self_version is None or prior_version is None:
        raise AttributeError(
            "Both inventories must have a 'version' attribute for comparison."
        )
    if prior_version >= self_version:
        raise ValueError(
            f"Prior version ({prior_version}) must be less than current version ({self_version})."
        )
    # Ensure both inventories expose an inventory mapping
    self_inv = getattr(self, "inventory", None)
    prior_inv = getattr(prior, "inventory", None)
    if self_inv is None or prior_inv is None:
        raise AttributeError("Both inventories must have an 'inventory' attribute.")
    if not isinstance(self_inv, dict) or not isinstance(prior_inv, dict):
        raise TypeError("The 'inventory' attribute must be a dictionary.")
    # Validate that all items in current are present in prior and prior quantities are <= current
    for item, qty in self_inv.items():
        prior_qty = prior_inv.get(item)
        if prior_qty is None:
            raise ValueError(
                f"Item '{item}' is missing from the prior inventory."
            )
        if prior_qty > qty:
            raise ValueError(
                f"Prior inventory has a higher quantity for item '{item}' "
                f"({prior_qty}) than current inventory ({qty})."
            )
    return True

def validate_as_prior_version(self, prior):
