        if not hasattr(inv, "version"):
            raise AttributeError(f"'{name}' lacks a 'version' attribute")

    # Compare the versions; prior's version must be strictly less than current's
    cur_version = self.inventory.version
    prior_version = prior.inventory.version
    try:
        if prior_version >= cur_version:
            raise ValueError(
                f"prior version ({prior_version}) must be earlier than "
                f"current version ({cur_version})"
            )
    except TypeError as exc:
        # If the versions cannot be compared directly, attempt to cast them
        try:
            cur_val = float(cur_version)
            pri_val = float(prior_version)
            if pri_val >= cur_val:
                raise ValueError(
                    f"prior version ({prior_version}) must be earlier than "
                    f"current version ({cur_version})"
                )
        except Exception:
            # The versions are not comparable; raise the original error
            raise ValueError(
                f"Cannot compare versions of current ({cur_version}) "
                f"and prior ({prior_version}) inventories"
            ) from exc

    # If we reach this point, validations passed
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure that prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError("`prior` must be an instance of the same class as `self`.")

    # Helper to extract a comparable "version" value from an InventoryValidator
    def _get_version(obj):
        # Prefer a method if available
        if hasattr(obj, "get_version") and callable(obj.get_version):
            try:
                return obj.get_version()
            except Exception:
                pass
        # Fallback to common attribute names
        for attr in ("version", "inventory_version", "created_at", "updated_at", "timestamp"):
            if hasattr(obj, attr):
                return getattr(obj, attr)
        return None

    self_ver = _get_version(self)
    prior_ver = _get_version(prior)

    # If we can't obtain a version value, assume the check passes
    if self_ver is None or prior_ver is None:
        return True

    # Attempt a natural comparison; handle incomparable types gracefully
    try:
        if self_ver <= prior_ver:
            raise ValueError(
                f"Current inventory version ({self_ver}) must be newer than prior version ({prior_ver})."
            )
    except TypeError:
        # Fall back to string comparison if comparison fails
        if str(self_ver) <= str(prior_ver):
            raise ValueError(
                f"Current inventory version ({self_ver}) must be newer than prior version ({prior_ver})."
            )

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for a given version in inventory.

    The inventory is expected to be a mapping of version numbers to state mappings.
    Each state mapping should itself be a mapping of logical paths to a list or single
    content file path. The returned dictionary maps each logical path to a set
    of content files.  For the requested *version*, all content files from that
    version *and* from later versions that refer to the same logical path are
    included in the resultant set.

    Parameters
    ----------
    inventory : dict
        A dictionary where the keys are version identifiers (int or coercible to
        int) and the values are state dictionaries mapping logical paths to
        content file(s).  Example::

            {
                1: {'/foo': ['file1', 'file2'], '/bar': 'file3'},
                2: {'/foo': ['file4'], '/baz': 'file5'}
            }

    version : int or str
        The version whose logical path map is required.  The value is coerced
        to an integer; a ``ValueError`` is raised if this fails.

    Returns
    -------
    dict
        Mapping of logical path -> set of content file paths for the requested
        version.  Duplicate file paths are collapsed by the set.

    Raises
    ------
    TypeError
        If *inventory* is not a dictionary.
    ValueError
        If *version* cannot be coerced to an integer or if the requested
        version does not exist in *inventory*.
    """
    # Basic input validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    try:
        target_ver = int(version)
    except Exception as exc:
        raise ValueError(f"version must be convertible to an integer, got {version!r}") from exc

    if target_ver not in inventory:
        raise ValueError(f"Requested version {target_ver} not found in inventory")

    # Build the map by scanning all versions >= target_ver
    result = {}
    try:
        for ver in sorted(inventory.keys()):
            # Skip any non‑numeric version keys
            try:
                ver_int = int(ver)
            except Exception:
                continue
            if ver_int < target_ver:
                continue

            state_map = inventory[ver]
            if not isinstance(state_map, dict):
                continue

            for logical_path, files in state_map.items():
                if logical_path not in result:
                    result[logical_path] = set()

                # Accept a single file or an iterable of files
                if isinstance(files, (list, tuple, set)):
                    for f in files:
                        result[logical_path].add(str(f))
                else:
                    result[logical_path].add(str(files))
    except Exception as exc:
        # General catch to avoid leaking internal structure
        raise RuntimeError("Error while building logical path map") from exc

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if version is None:
        raise ValueError("version cannot be None")
    try:
        path_map = {}
        # inventory is expected to be a mapping of logical_path -> data
        for logical_path, data in inventory.items():
            if not isinstance(data, dict):
                continue
            # The data dict may use version keys directly
            if version in data:
                value = data[version]
                # Resolve content file reference
                content_file = None
                if isinstance(value, dict):
                    # Common keys that may contain the path
                    for key in ("content_file", "file", "path"):
                        if key in value:
                            content_file = value[key]
                            break
                else:
                    # Assume value itself is the file path
                    content_file = value
                if content_file:
                    if isinstance(content_file, (list, tuple, set)):
                        path_map[logical_path] = set(content_file)
                    else:
                        path_map[logical_path] = {content_file}
        return path_map
    except Exception as exc:
        raise RuntimeError(f"Failed to generate logical path map: {exc}") from exc

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory type
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping version identifiers to logical path maps")
    # Helper for sorting keys that may be numeric or string
    def _sort_key(k):
        try:
            return float(k)
        except Exception:
            return float("inf")
    # Ensure the requested version is present or find the nearest available <= version
    if version not in inventory:
        # Find the largest version key less than or equal to the requested one
        candidates = [k for k in inventory if isinstance(k, (int, float))]
        if candidates:
            try:
                upper = max(k for k in candidates if k <= version)
                chosen_version = upper
            except ValueError:
                # No candidate less than or equal, return empty map
                return {}
        else:
            # No numeric keys: fall back to exact match search
            chosen_version = None
        if chosen_version is None:
            return {}
        version = chosen_version
    # Build the logical path map aggregating from the requested version forward
    result = {}
    # Order keys in ascending order to process from chosen version onward
    for v_key in sorted(inventory.keys(), key=_sort_key):
        try:
            v_num = float(v_key)
        except Exception:
            # Skip keys that cannot be interpreted as numbers
            continue
        if v_num < version:
            continue
        level_map = inventory[v_key]
        if not isinstance(level_map, dict):
            continue
        for logical_path, content_files in level_map.items():
            # Skip if content_files is not iterable
            if not isinstance(content_files, (list, tuple, set)):
                continue
            if logical_path not in result:
                result[logical_path] = set()
            # Update the set; if duplicate files exist in later versions they will be added
            result[logical_path].update(content_files)
    return result

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in later versions
    than the version being described.
    """
    # Basic validation of inputs
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")
    if version not in inventory:
        raise ValueError(f"Version {version!r} not present in inventory")

    # Ensure the data for the requested version is a mapping
    state_paths = inventory.get(version, {})
    if not isinstance(state_paths, dict):
        raise ValueError(f"Inventory entry for version {version!r} must be a mapping")

    # Attempt to order versions for later processing
    try:
        # try numeric sort if possible, otherwise lexicographic
        def _key(v):
            try:
                return float(v)
            except Exception:
                return str(v)
        sorted_versions = sorted(inventory.keys(), key=_key)
    except Exception:
        sorted_versions = list(inventory.keys())

    result = {}

    for logical_path, files in state_paths.items():
        # Convert whatever iterable to a set of file paths
        try:
            files_set = set(files)
        except Exception:
            files_set = {files}

        # Include duplicates from later versions
        for later_version in sorted_versions:
            try:
                if _key(later_version) <= _key(version):
                    continue
            except Exception:
                # Fallback if comparison fails
                if later_version <= version:
                    continue

            later_paths = inventory.get(later_version, {})
            if not isinstance(later_paths, dict):
                continue
            if logical_path in later_paths:
                try:
                    later_files = set(later_paths[logical_path])
                except Exception:
                    later_files = {later_paths[logical_path]}
                files_set.update(later_files)

        result[logical_path] = files_set

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic validation of input types
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, set, or tuple")

    # The fixity block must contain a 'files' key pointing to an iterable
    if "files" not in fixity:
        raise ValueError("fixity block missing required 'files' key")
    files_collection = fixity["files"]
    if not isinstance(files_collection, (list, tuple)):
        raise ValueError("'files' key in fixity block must reference a list or tuple")

    # Convert manifest to a set for fast lookup
    manifest_set = set(manifest_files)
    seen_paths = set()

    required_keys = {"path", "checksum", "size", "digest_algorithm"}
    for idx, file_entry in enumerate(files_collection):
        if not isinstance(file_entry, dict):
            raise ValueError(f"File entry at index {idx} is not a dictionary")
        missing = required_keys - file_entry.keys()
        if missing:
            raise ValueError(f"File entry at index {idx} missing keys: {', '.join(missing)}")

        path = file_entry["path"]
        if not isinstance(path, str) or not path:
            raise ValueError(f"Invalid 'path' value in file entry at index {idx}")
        if path not in manifest_set:
            raise ValueError(f"Path '{path}' referenced in fixity not found in manifest")
        if path in seen_paths:
            raise ValueError(f"Duplicate path '{path}' found in fixity block")
        seen_paths.add(path)

        checksum = file_entry["checksum"]
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(f"Invalid 'checksum' for path '{path}'")

        size = file_entry["size"]
        if not isinstance(size, int) or size < 0:
            raise ValueError(f"Invalid 'size' for path '{path}', must be non‑negative integer")

        algo = file_entry["digest_algorithm"]
        if not isinstance(algo, str) or not algo:
            raise ValueError(f"Invalid 'digest_algorithm' for path '{path}'")

    return True

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Ensure manifest_files is iterable
    if manifest_files is None:
        raise ValueError("Manifest files list cannot be None")
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("Manifest files must be an iterable of file paths")

    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if "files" not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")
    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("'files' key must map to a list of entries")

    # Validate each file entry
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry {idx} in 'files' must be a dictionary")
        if "path" not in entry:
            raise ValueError(f"Entry {idx} missing required 'path' key")
        path = entry["path"]
        if not isinstance(path, str) or not path:
            raise ValueError(f"Entry {idx} has invalid 'path' value: {path!r}")

        # Ensure the file is present in the manifest
        if path not in manifest_set:
            raise ValueError(
                f"File path '{path}' referenced in fixity block "
                "is not listed in the manifest"
            )

        # Optional: Ensure checksum field exists (common in fixity entries)
        if "checksum" not in entry:
            raise ValueError(f"Entry {idx} missing required 'checksum' key")
        checksum = entry["checksum"]
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(f"Entry {idx} has invalid 'checksum' value: {checksum!r}")

    # If we get this far, all checks passed
    return True

def validate_fixity(self, fixity, manifest_files):
        """
        Validate fixity block in inventory.

        Check the structure of the fixity block and make sure that only files
        listed in the manifest are referenced.
        """
        # Coerce manifest_files into a set of strings
        try:
            manifest_set = {str(f) for f in manifest_files}
        except Exception as exc:
            raise TypeError("manifest_files must be an iterable of file path strings") from exc

        # Accept empty or None as valid (no fixity requirements)
        if not fixity:
            return True

        if not isinstance(fixity, dict):
            raise TypeError("fixity block must be a dictionary mapping file paths to their fixity data")

        allowed_algorithms = {
            'md5', 'sha-1', 'sha-256', 'sha-384', 'sha-512',
            'sha-224', 'sha-512/224', 'sha-512/256'
        }

        for file_path, details in fixity.items():
            if not isinstance(file_path, str):
                raise TypeError(f"Fixity key {file_path!r} is not a string representing a file path")

            if file_path not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{file_path}' not present in manifest")

            if not isinstance(details, dict):
                raise TypeError(f"Fixity entry for file '{file_path}' must be a dictionary")

            # Required structure checks
            required_keys = ('bytes', 'checksum', 'checksum-algorithm')
            missing = [k for k in required_keys if k not in details]
            if missing:
                raise ValueError(f"Missing required keys {missing} in fixity entry for file '{file_path}'")

            # Validate 'bytes'
            bytes_val = details['bytes']
            if not isinstance(bytes_val, int) or bytes_val < 0:
                raise ValueError(f"Invalid 'bytes' value {bytes_val!r} for file '{file_path}' (must be non‑negative integer)")

            # Validate 'checksum'
            checksum_val = details['checksum']
            if not isinstance(checksum_val, str):
                raise ValueError(f"'checksum' must be a string in fixity entry for file '{file_path}'")
            # Basic hex format check if it looks hexadecimal
            if checksum_val and not all(c in '0123456789abcdefABCDEF' for c in checksum_val):
                # Permit non‑hex checksums silently; raise only if entirely nonhex
                if not any(c.isalpha() for c in checksum_val):
                    raise ValueError(f"Checksum for file '{file_path}' appears non‑hexadecimal and contains no alphabetic characters")

            # Validate 'checksum-algorithm'
            alg = details['checksum-algorithm']
            if not isinstance(alg, str) or not alg.strip():
                raise ValueError(f"Checksum algorithm for file '{file_path}' must be a non‑empty string")
            alg_lower = alg.lower()
            if alg_lower not in allowed_algorithms and not alg_lower.startswith('sha'):
                raise ValueError(
                    f"Unsupported checksum algorithm '{alg}' for file '{file_path}'. "
                    "Allowed: MD5, SHA‑1, SHA‑224, SHA‑256, SHA‑384, SHA‑512, etc."
                )

        # If no errors raised, the fixity block is considered valid
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and ensures that only files
    listed in ``manifest_files`` are referenced.

    Parameters
    ----------
    fixity : dict
        Mapping of file names to a dictionary of hash algorithms and hash
        values. Example::
            {
                "file.txt": {"sha256": "a1b2c3..."},
                "image.png": {"md5": "12345678"}
            }
    manifest_files : iterable
        Iterable of file names (strings) that were listed in the PDFA
        manifest.

    Raises
    ------
    ValueError
        If ``fixity`` is not a dictionary, if any file name or algorithm
        is not a string, if any hash value is not a string, or if a file
        referenced in the fixity block is not present in ``manifest_files``.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if not isinstance(manifest_files, (list, tuple, set)):
        raise ValueError("manifest_files must be an iterable of file names.")
    manifest_set = set(manifest_files)

    for file_path, hash_dict in fixity.items():
        if not isinstance(file_path, str):
            raise ValueError(f"File name '{file_path}' must be a string.")
        if file_path not in manifest_set:
            raise ValueError(f"File '{file_path}' referenced in fixity block is not present in the manifest.")
        if not isinstance(hash_dict, dict):
            raise ValueError(f"Hash data for file '{file_path}' must be a dictionary.")
        if not hash_dict:
            raise ValueError(f"Hash dictionary for file '{file_path}' is empty.")
        for algorithm, hash_value in hash_dict.items():
            if not isinstance(algorithm, str):
                raise ValueError(f"Hash algorithm key '{algorithm}' for file '{file_path}' must be a string.")
            if not isinstance(hash_value, str):
                raise ValueError(f"Hash value for algorithm '{algorithm}' in file '{file_path}' must be a string.")

    # If all checks pass, simply return True
    return True

def files_list(path):
    """
    Return the files in `path`.
    """
    os = __import__('os')
    if not isinstance(path, (str, bytes)) and not hasattr(path, '__fspath__'):
        raise TypeError("path must be a string, bytes, or path-like object")
    try:
        entries = os.listdir(path)
    except OSError as e:
        raise RuntimeError(f"Could not list directory '{path}': {e}") from e
    files = []
    for entry in entries:
        full = os.path.join(path, entry)
        if os.path.isfile(full):
            files.append(entry)
    return files

def files_list(path):
    """
    Return the files in `path`
    """
    result = []
    try:
        # Handle both string paths and pathlib.Path objects
        try:
            is_dir = os.path.isdir(path)
        except Exception:
            # If os is not available, try pathlib object methods
            if hasattr(path, "is_dir"):
                is_dir = path.is_dir()
            else:
                return result

        if not is_dir:
            return result

        # List directory contents
        try:
            entries = os.listdir(path)
        except Exception:
            try:
                entries = list(path.iterdir())
            except Exception:
                return result

        for entry in entries:
            try:
                full_path = os.path.join(path, entry) if isinstance(path, str) else os.path.join(path, entry)
            except Exception:
                continue

            try:
                if os.path.isfile(full_path):
                    result.append(full_path)
            except Exception:
                continue
    except Exception:
        # Any unexpected error results in an empty list
        return []

    return result

