def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Base directory or archive path to resolve relative filenames.
    xmls : list
        List of XML filenames.
    files : list
        List of files in the folder or zipfile.

    Returns
    -------
    dict
        Mapping where each key is the basename of an XML file (including the .xml extension)
        and each value is a list of full paths to files that share that basename.
    """
    # Basic validation
    try:
        if not isinstance(source, str) or not source:
            raise TypeError("`source` must be a non‑empty string")
        if not isinstance(xmls, list):
            raise TypeError("`xmls` must be a list")
        if not isinstance(files, list):
            raise TypeError("`files` must be a list")
    except Exception as exc:
        raise ValueError(f"Invalid input: {exc}")

    # Prepare result dictionary
    grouped = {}
    # Build a set of basenames for quick lookup
    try:
        xml_basename_map = {os.path.splitext(xml)[0]: xml for xml in xmls}
    except Exception as exc:
        raise ValueError(f"Error processing xmls list: {exc}")

    for xml_base, xml_name in xml_basename_map.items():
        grouped[xml_name] = []

    # Iterate over files and match basenames
    for fname in files:
        try:
            base, _ = os.path.splitext(os.path.basename(fname))
            # Check if this file matches any XML basename
            for xml_base, xml_name in xml_basename_map.items():
                if base == xml_base:
                    full_path = os.path.join(source, fname)
                    grouped[xml_name].append(full_path)
        except Exception:
            # Skip any file that causes an error
            continue

    # Ensure each XML has at least itself in the list
    for xml_name in grouped:
        xml_path = os.path.join(source, xml_name)
        if xml_path not in grouped[xml_name]:
            grouped[xml_name].insert(0, xml_path)

    return grouped

def match_file_by_prefix(prefix, file_path):
    """Identify if a `file_path` belongs to a document package by a given `prefix`."""
    try:
        import os
        # Validate input types
        if not isinstance(prefix, str) or not isinstance(file_path, str):
            return False
        # Empty prefix does not match anything
        if not prefix:
            return False
        # Extract the file name from the path
        base_name = os.path.basename(file_path)
        # Return True if the file name starts with the given prefix
        return base_name.startswith(prefix)
    except Exception:
        # Any error (e.g., invalid file path format) should be treated as non‑match
        return False

def select_filenames_by_prefix(prefix, files):
    """
    Get files which belongs to a document package.

    Retorna os arquivos da lista `files` cujos nomes iniciam com `prefix`

    Parameters
    ----------
    prefix : str
        Filename prefix
    files : str list
        Files paths
    Returns
    -------
    list
        files paths which basename files matches to prefix
    """
    # Validate input types
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    if not hasattr(files, '__iter__'):
        raise TypeError("files must be an iterable of file paths")

    # Attempt to import os for reliable basename extraction
    try:
        import os
    except Exception:
        os = None

    matched_files = []
    for f in files:
        # Skip non-string entries
        if not isinstance(f, str):
            continue
        try:
            # Use os.path.basename if available, otherwise fallback to split
            if os and hasattr(os.path, 'basename'):
                basename = os.path.basename(f)
            else:
                # Split on both types of path separators
                sep_candidates = ('/', '\\')
                for sep in sep_candidates:
                    if sep in f:
                        basename = f.split(sep)[-1]
                        break
                else:
                    basename = f  # No separator found
            if basename.startswith(prefix):
                matched_files.append(f)
        except Exception:
            # Ignore individual errors and continue
            continue

    return matched_files

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    try:
        import os

        if not isinstance(folder, str):
            return {}

        if not os.path.isdir(folder):
            return {}

        data = {}
        for root, dirs, files in os.walk(folder):
            # Find all XML files in the current directory
            xml_files = [f for f in files if f.lower().endswith('.xml')]
            if not xml_files:
                continue

            # Compute relative directory name from the root folder
            rel_dir = os.path.relpath(root, folder)
            # Normalize '.' to empty string for root level
            if rel_dir == '.':
                rel_dir = ''

            for xml_file in xml_files:
                base_name, _ = os.path.splitext(xml_file)
                # Collect all files in this directory that share the same base name
                related_files = []
                for f in files:
                    if os.path.splitext(f)[0] == base_name:
                        # Build relative path for each related file
                        if rel_dir:
                            rel_path = os.path.join(rel_dir, f)
                        else:
                            rel_path = f
                        related_files.append(rel_path)

                # Build key for the dictionary
                key = os.path.join(rel_dir, base_name) if rel_dir else base_name
                data[key] = related_files

        return data
    except Exception:
        # In case of any unexpected error, return an empty dict
        return {}

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise ValueError("`folder` must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"Folder '{folder}' does not exist or is not a directory")

    package_map = {}

    # First pass: collect XML files and create base keys
    try:
        for root, _, files in os.walk(folder):
            for fname in files:
                if fname.lower().endswith('.xml'):
                    base, _ = os.path.splitext(fname)
                    full_path = os.path.join(root, fname)
                    package_map.setdefault(base, []).append(full_path)
    except Exception as exc:
        raise RuntimeError(f"Failed while scanning folder '{folder}': {exc}") from exc

    # Second pass: associate all files that share a base that has an XML file
    try:
        for root, _, files in os.walk(folder):
            for fname in files:
                base, _ = os.path.splitext(fname)
                if base in package_map:
                    full_path = os.path.join(root, fname)
                    if full_path not in package_map[base]:
                        package_map[base].append(full_path)
    except Exception as exc:
        raise RuntimeError(f"Failed while associating files in '{folder}': {exc}") from exc

    return package_map

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo em análise

    Returns
    -------
    dict
        dicionário contendo 'type' e 'file_path'
    """
    # Validate input types
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a str, got {type(prefix).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"file_path must be a str, got {type(file_path).__name__}")

    # Normalise file path
    file_path = file_path.strip()
    if not file_path:
        return {'type': 'unknown', 'file_path': file_path}

    # Incremental check if file exists; not mandatory but good for robustness
    # If file doesn't exist, we still return unknown type without raising unless kwargs specify otherwise
    import os
    if not os.path.isfile(file_path):
        return {'type': 'unknown', 'file_path': file_path}

    # Define extensions that usually indicate a rendition (image)
    image_exts = {
        '.jpg', '.jpeg', '.png', '.gif', '.tiff', '.bmp', '.svg', '.webp',
        '.ico', '.tga'
    }

    # Define extensions that usually indicate an asset (document, archive, video, etc.)
    doc_exts = {
        '.pdf', '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx', '.txt',
        '.zip', '.rar', '.7z', '.htm', '.html', '.xml', '.mp4', '.avi',
        '.mkv', '.mov', '.wav', '.mp3', '.wav', '.flac', '.ogv', '.jpg'
    }

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    file_type = 'unknown'
    if ext in image_exts:
        file_type = 'rendition'
    elif ext in doc_exts:
        file_type = 'asset'
    else:
        # If not recognized by extension, try a simple heuristic: check if file data starts with common image magic numbers
        try:
            with open(file_path, 'rb') as f:
                header = f.read(8)
                # JPEG
                if header.startswith(b'\xFF\xD8\xFF'):
                    file_type = 'rendition'
                # PNG
                elif header.startswith(b'\x89PNG\r\n\x1a\n'):
                    file_type = 'rendition'
                # GIF
                elif header.startswith(b'GIF87a') or header.startswith(b'GIF89a'):
                    file_type = 'rendition'
                # SVG (text)
                elif header.lstrip().startswith(b'<?xml') or header.lstrip().startswith(b'<svg'):
                    file_type = 'asset'
                # Default remains 'unknown'
        except OSError:
            # If file can't be read, keep type as unknown
            pass

    return {'type': file_type, 'file_path': file_path}

def add_rendition(self, lang, file_path):
        """
        Adds a rendition file for a specific language.
        Example mapping:
            {
                "original": "artigo02.pdf",
                "en": "artigo02-en.pdf",
            }
        """
        # Validate parameter types
        if not isinstance(lang, str):
            raise TypeError("lang must be a string")
        if not isinstance(file_path, str):
            raise TypeError("file_path must be a string")

        # Ensure the file exists by attempting to open it
        try:
            with open(file_path, "rb"):
                pass
        except FileNotFoundError:
            raise FileNotFoundError(f"File not found: {file_path}")
        except Exception as exc:
            raise IOError(f"Error accessing file '{file_path}': {exc}")

        # Derive the original filename from the given file_path.
        # Strip any language suffix before the extension if present.
        basename = file_path.split("/")[-1].split("\\")[-1]
        name, ext = basename.rsplit(".", 1) if "." in basename else (basename, "")
        # If the basename ends with "-lang.ext", remove the "-lang" part for original
        if lang and name.endswith(f"-{lang}"):
            original_name = name[: -len(f"-{lang}")] + (f".{ext}" if ext else "")
        else:
            original_name = basename

        # Ensure the renditions dictionary exists
        if not hasattr(self, "_renditions") or not isinstance(self._renditions, dict):
            self._renditions = {}

        # Add or update the rendition entry
        if original_name not in self._renditions:
            self._renditions[original_name] = {}
        self._renditions[original_name][lang] = file_path

        # No explicit return value; the state is updated in self._renditions

