def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a list of dicts each containing 'filename' and 'content'.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    groups = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if not info.filename.lower().endswith('.xml'):
                    continue
                basename = os.path.splitext(os.path.basename(info.filename))[0]
                try:
                    with zf.open(info) as f:
                        content = f.read().decode('utf-8')
                except Exception as e:
                    content = None
                groups.setdefault(basename, []).append(
                    {'filename': info.filename, 'content': content}
                )
    except zipfile.BadZipFile as e:
        raise ValueError(f"Bad zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return groups

