def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    The representation is produced recursively for nested containers
    and objects that provide a :py:meth:`pretty` method. The
    ``indent`` parameter controls the number of spaces used for each
    nesting level and to avoid infinite recursion, already visited
    objects are replaced by the string ``"<circular ref>"``.
    When ``debug`` is ``True`` type information is appended after
    each value where relevant.

    Returns
    -------
    str
        A human‑readable representation of ``self``.
    """
    # Guard against nonsensical indent values
    try:
        indent = int(indent)
    except Exception:
        indent = 0
    if indent < 0:
        indent = 0

    # Helper to escape strings
    def _repr_str(s):
        return repr(s)

    # Tracker for circular references
    _seen = set()

    def _pretty(obj, level):
        obj_id = id(obj)
        if obj_id in _seen:
            return "<circular ref>"
        _seen.add(obj_id)

        prefix = " " * (level * indent)

        # Primitive types
        if obj is None:
            return "None" + (f"  # <class 'NoneType'>" if debug else "")
        if isinstance(obj, (int, float, complex, bool)):
            return repr(obj) + (f"  # <class '{type(obj).__name__}'>"
                                if debug else "")
        if isinstance(obj, str):
            return _repr_str(obj) + (f"  # <class 'str'>"
                                    if debug else "")

        # Containers
        if isinstance(obj, (list, tuple, set, frozenset)):
            opening = "[" if isinstance(obj, list) else (
                "(" if isinstance(obj, tuple) else ("{" if isinstance(obj, set) else "{"))
            closing = "]" if isinstance(obj, list) else (
                ")" if isinstance(obj, tuple) else ("}" if isinstance(obj, set) else "}")
            inner = []
            for idx, item in enumerate(obj):
                inner.append(_pretty(item, level + 1))
            joined = ",\n".join(" " * ((level + 1) * indent) + i for i in inner)
            return f"{opening}\n{joined}\n{prefix}{closing}" if inner else f"{opening}{closing}"

        if isinstance(obj, dict):
            inner = []
            for k, v in obj.items():
                key_repr = (
                    _repr_str(k) if isinstance(k, str) else _pretty(k, 0)
                )
                val_repr = _pretty(v, level + 1)
                inner.append(f"{key_repr}: {val_repr}")
            joined = ",\n".join(" " * ((level + 1) * indent) + i for i in inner)
            return f"{{\n{joined}\n{prefix}}}" if inner else "{}"

        # Objects with a custom pretty method
        if hasattr(obj, "pretty") and callable(getattr(obj, "pretty")):
            try:
                return obj.pretty(indent, debug)
            except Exception:
                # Fallback to __repr__
                pass

        # Fallback: use __dict__ if available
        if hasattr(obj, "__dict__"):
            attrs = vars(obj)
            if attrs:
                inner = []
                for k, v in attrs.items():
                    val_repr = _pretty(v, level + 1)
                    inner.append(f"{k}={val_repr}")
                joined = ",\n".join(" " * ((level + 1) * indent) + i for i in inner)
                return f"{obj.__class__.__name__}(\n{joined}\n{prefix})"
            else:
                return f"{obj.__class__.__name__}()"

        # Fallback to repr
        return repr(obj)

    return _pretty(self, 0)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    The representation prints nested structures with indentation.
    If debug is True, type information is added after each value.
    """
    visited = set()

    def _format(obj, level):
        """Recursively format obj with indentation level."""
        prefix = "    " * level
        obj_id = id(obj)
        if obj_id in visited:
            return f"{prefix}*RECURSION*"

        # Primitive types
        if isinstance(obj, (str, int, float, bool, type(None))):
            base = repr(obj)
            return f"{prefix}{base} ({type(obj).__name__})" if debug else f"{prefix}{base}"

        # Dictionaries
        if isinstance(obj, dict):
            visited.add(obj_id)
            if not obj:
                return f"{prefix}{{}}"
            lines = [f"{prefix}{{"]
            for k, v in obj.items():
                key_repr = repr(k) if not debug else f"{repr(k)} ({type(k).__name__})"
                lines.append(f"{prefix}    {key_repr}: {_format(v, level + 1)}")
            lines.append(f"{prefix}}}")
            return "\n".join(lines)

        # Sequences
        if isinstance(obj, (list, tuple, set, frozenset)):
            visited.add(obj_id)
            if isinstance(obj, list):
                opener, closer = "[", "]"
            elif isinstance(obj, tuple):
                opener, closer = "(", ")"
            elif isinstance(obj, set):
                opener, closer = "{", "}"
            else:  # frozenset
                opener, closer = "frozenset({", "})"
            if not obj:
                return f"{prefix}{opener}{closer}"
            lines = [f"{prefix}{opener}"]
            for item in obj:
                lines.append(f"{prefix}    {_format(item, level + 1)}")
            lines.append(f"{prefix}{closer}")
            return "\n".join(lines)

        # Objects with their own pretty method
        if hasattr(obj, "pretty") and callable(obj.pretty):
            try:
                return obj.pretty(level, debug)
            except Exception:
                pass

        # Objects with __dict__
        if hasattr(obj, "__dict__"):
            return _format(vars(obj), level)

        # Fallback to repr
        try:
            base = repr(obj)
            return f"{prefix}{base} ({type(obj).__name__})" if debug else f"{prefix}{base}"
        except Exception:
            return f"{prefix}<unrepresentable object>"

    return _format(self, indent)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate arguments
    if not isinstance(indent, int):
        raise TypeError(f"indent must be an integer, got {type(indent).__name__}")
    if not isinstance(debug, bool):
        raise TypeError(f"debug must be a boolean, got {type(debug).__name__}")

    # Track visited objects to avoid infinite recursion
    seen = set()

    def _pretty(obj, level):
        """
        Recursively format the object.
        """
        # Avoid infinite recursion
        obj_id = id(obj)
        if obj_id in seen:
            return '...'
        seen.add(obj_id)

        # If the object has a custom pretty method, use it
        if hasattr(obj, "pretty") and callable(obj.pretty):
            try:
                return obj.pretty(indent=level, debug=debug)
            except Exception:
                pass  # Fallback to default handling

        # Handle basic data types
        if isinstance(obj, (int, float, bool, type(None))):
            return repr(obj)

        # Handle strings
        if isinstance(obj, str):
            return f"'{obj}'"

        # Handle lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            elem_strs = ",\n".join(_pretty(e, level + 2) for e in obj)
            opener = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{"
            closer = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}"
            return f"{openr}{elem_strs}{closer}"

        # Handle dictionaries
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                k_str = _pretty(k, level + 2)
                v_str = _pretty(v, level + 2)
                items.append(f"{' ' * (level+2)}{k_str}: {v_str}")
            return f"dict(\n" + "\n".join(items) + f"\n{' ' * level})"

        # Fallback for other objects
        if hasattr(obj, "__dict__"):
            cls_name = obj.__class__.__name__
            items = []
            for key, val in vars(obj).items():
                val_str = _pretty(val, level + 2)
                if debug:
                    items.append(f"{' ' * (level+2)}{key} ({type(val).__name__}): {val_str}")
                else:
                    items.append(f"{' ' * (level+2)}{key} = {val_str}")
            return f"{cls_name}(\n" + "\n".join(items) + f"\n{' ' * level})"

        # Final fallback
        return repr(obj)

    try:
        return _pretty(self, indent)
    except Exception as exc:
        # In case of unexpected errors, return a simple representation
        return f"<Error pretty-printing {self!r}: {exc}>"

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces to prepend to each line (default 0).
    debug : bool, optional
        If True, include class name and memory address in the output. Default is False.

    Returns
    -------
    str
        A human‑readable representation of *self*.
    """
    try:
        if not isinstance(indent, int):
            raise TypeError("indent must be an integer")
        if not isinstance(debug, bool):
            raise TypeError("debug must be a boolean")

        indent_str = " " * indent

        if debug:
            return f"{indent_str}{self.__class__.__name__} at 0x{id(self):x}"

        # Start building the pretty string
        parts = [f"{indent_str}{self.__class__.__name__}:"]

        # Works for objects that expose a __dict__ (typical user class)
        if hasattr(self, "__dict__"):
            for key in sorted(self.__dict__):
                value = getattr(self, key)
                if hasattr(value, "pretty") and callable(value.pretty):
                    sub = value.pretty(indent=indent + 4, debug=debug)
                else:
                    sub = repr(value)
                parts.append(f"{indent_str}{' ' * 4}{key} = {sub}")

        # Handles objects using __slots__
        elif hasattr(self, "__slots__"):
            for slot in getattr(self, "__slots__"):
                value = getattr(self, slot)
                if hasattr(value, "pretty") and callable(value.pretty):
                    sub = value.pretty(indent=indent + 4, debug=debug)
                else:
                    sub = repr(value)
                parts.append(f"{indent_str}{' ' * 4}{slot} = {sub}")

        # Fallback if __dict__ and __slots__ are not available
        else:
            parts.append(f"{indent_str}{repr(self)}")

        return "\n".join(parts)

    except Exception as exc:
        # Return a short error message rather than raising
        err_indent = " " * indent
        return f"{err_indent}<pretty() failed: {exc!s}>"

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _repr(obj):
        """Return a simple representation, optionally with type debug."""
        r = repr(obj)
        if debug:
            r += f" <{type(obj).__name__}>"
        return r

    def _pretty(obj, cur_indent):
        """Recursively format obj with indentation."""
        # Simple primitives
        if isinstance(obj, (int, float, bool, type(None), str)):
            return _repr(obj)

        # Recursive sequences
        if isinstance(obj, list):
            if not obj:
                return "[]"
            lines = ["["]
            for item in obj:
                lines.append(" " * (cur_indent + 2) + _pretty(item, cur_indent + 2) + ",")
            lines.append(" " * cur_indent + "]")
            return "\n".join(lines)

        if isinstance(obj, tuple):
            if not obj:
                return "()"
            lines = ["("]
            for item in obj:
                lines.append(" " * (cur_indent + 2) + _pretty(item, cur_indent + 2) + ",")
            lines.append(" " * cur_indent + ")")
            return "\n".join(lines)

        if isinstance(obj, set):
            if not obj:
                return "set()"
            lines = ["set(["]
            for item in obj:
                lines.append(" " * (cur_indent + 2) + _pretty(item, cur_indent + 2) + ",")
            lines.append(" " * cur_indent + "])")
            return "\n".join(lines)

        # Mapping
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            lines = ["{"]
            for k, v in obj.items():
                lines.append(" " * (cur_indent + 2) + f"{_pretty(k, cur_indent + 2)}: {_pretty(v, cur_indent + 2)},")
            lines.append(" " * cur_indent + "}")
            return "\n".join(lines)

        # Custom objects
        if hasattr(obj, "__dict__"):
            cls_name = obj.__class__.__name__
            values = vars(obj)
            if not values:
                return f"{cls_name}()"
            lines = [f"{cls_name}("]
            for key, value in values.items():
                lines.append(" " * (cur_indent + 2) + f"{key}={_pretty(value, cur_indent + 2)},")
            lines.append(" " * cur_indent + ")")
            return "\n".join(lines)

        # Fallback
        return _repr(obj)

    return _pretty(self, indent)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        # Ensure args is a list-like sequence
        expr_list = list(args)
    except Exception as exc:
        raise TypeError(f"`args` must be a sequence of expressions: {exc}") from exc

    # Import sympy lazily
    try:
        from sympy import And, Or, Not
    except Exception as exc:
        raise ImportError("sympy is required to use absorb") from exc

    def _apply_patterns(expr):
        """
        Iteratively apply absorption rules to a single expression until no change.
        """
        changed = True
        while changed:
            changed = False

            # Pattern 1: A & (A | B) -> A
            if expr.is_And:
                for a in expr.args:
                    rest = tuple(x for x in expr.args if x != a)
                    if len(rest) == 1 and rest[0].is_Or and a in rest[0].args:
                        expr = a
                        changed = True
                        break

            if changed:
                continue

            # Pattern 2: A | (A & B) -> A
            if expr.is_Or:
                for a in expr.args:
                    rest = tuple(x for x in expr.args if x != a)
                    if len(rest) == 1 and rest[0].is_And and a in rest[0].args:
                        expr = a
                        changed = True
                        break

            if changed:
                continue

            # Pattern 3: A & (~A | B) -> A & B
            if expr.is_And:
                for a in expr.args:
                    rest = tuple(x for x in expr.args if x != a)
                    if len(rest) == 1 and rest[0].is_Or:
                        neg_a = Not(a)
                        if any(x == neg_a for x in rest[0].args):
                            b_terms = [x for x in rest[0].args if x != neg_a]
                            if len(b_terms) == 1:
                                expr = And(a, b_terms[0])
                            else:
                                expr = And(a, Or(*b_terms))
                            changed = True
                            break

            if changed:
                continue

            # Pattern 4: A | (~A & B) -> A | B
            if expr.is_Or:
                for a in expr.args:
                    rest = tuple(x for x in expr.args if x != a)
                    if len(rest) == 1 and rest[0].is_And:
                        neg_a = Not(a)
                        if any(x == neg_a for x in rest[0].args):
                            b_terms = [x for x in rest[0].args if x != neg_a]
                            if len(b_terms) == 1:
                                expr = Or(a, b_terms[0])
                            else:
                                expr = Or(a, And(*b_terms))
                            changed = True
                            break

        return expr

    # Apply patterns to each expression
    new_exprs = []
    seen = set()
    for expr in expr_list:
        try:
            simplified = _apply_patterns(expr)
        except Exception:
            # If we cannot simplify, keep original
            simplified = expr

        # Avoid duplicates; compare using hashable representation
        try:
            key = simplified
            if key not in seen:
                seen.add(key)
                new_exprs.append(simplified)
        except Exception:
            # If expression isn't hashable, still include it
            new_exprs.append(simplified)

    return new_exprs

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _absorb(expr):
        # Recursively simplify children first
        if hasattr(expr, 'args') and len(expr.args) > 0:
            new_args = tuple(_absorb(arg) for arg in expr.args)
            expr = expr.func(*new_args)
        try:
            name = expr.func.__name__
        except Exception:
            # Not a symbolic node; return as-is
            return expr

        # Helper to rebuild expression
        def rebuild(args_tuple):
            return expr.func(*args_tuple)

        # Absorption and negative absorption cases
        if name == 'And':
            # Check for patterns of the form A & (A | B) or A & (~A | B)
            for i, a in enumerate(expr.args):
                for j, b in enumerate(expr.args):
                    if i == j:
                        continue
                    if hasattr(b, 'args') and len(b.args) == 2:
                        if b.func.__name__ == 'Or':
                            # Pattern A & (A | B)
                            if a in b.args and a not in (b.args):
                                # Replace the whole And with A
                                return a
                            # Negative absorption: A & (~A | B)
                            not_a_present = False
                            other = None
                            for part in b.args:
                                if part.func.__name__ == 'Not' and part.args[0] == a:
                                    not_a_present = True
                                else:
                                    other = part
                            if not_a_present and other is not None:
                                return rebuild((a, other))
        elif name == 'Or':
            # Check for patterns of the form A | (A & B) or A | (~A & B)
            for i, a in enumerate(expr.args):
                for j, b in enumerate(expr.args):
                    if i == j:
                        continue
                    if hasattr(b, 'args') and len(b.args) == 2:
                        if b.func.__name__ == 'And':
                            # Pattern A | (A & B)
                            if a in b.args and a not in (b.args):
                                return a
                            # Negative absorption: A | (~A & B)
                            not_a_present = False
                            other = None
                            for part in b.args:
                                if part.func.__name__ == 'Not' and part.args[0] == a:
                                    not_a_present = True
                                else:
                                    other = part
                            if not_a_present and other is not None:
                                return rebuild((a, other))
        # No patterns matched; return the (possibly) simplified expression
        return expr

    result = []
    for e in args:
        try:
            simplified = _absorb(e)
            result.append(simplified)
        except Exception:
            # If any unexpected error occurs, keep the original expression
            result.append(e)
    return result

def absorb(self, args):
        """
        Return a new list of expressions applying absorption and negative absorption.
        """
        # First simplify each expression individually (helps with negative absorption).
        try:
            simplified_args = [simplify(arg) for arg in args]
        except Exception:
            # If simplify is unavailable, just copy the originals.
            simplified_args = list(args)

        result = []
        for expr in simplified_args:
            # If the expression already exists in the result, skip
            if any(expr == existing for existing in result):
                continue

            # Remove any existing expressions from result that are absorbed by expr
            removed_indices = []
            for idx, existing in enumerate(result):
                if expr.is_And and existing.is_Or:
                    if set(expr.args).issubset(set(existing.args)):
                        removed_indices.append(idx)
                elif expr.is_Or and existing.is_And:
                    if set(expr.args).issubset(set(existing.args)):
                        removed_indices.append(idx)
                elif expr.is_Not and existing.is_Not:
                    # Negation absorption: if ~A contains A
                    if expr.args[0] == existing.args[0]:
                        removed_indices.append(idx)
            # Remove from end to avoid index shift
            for idx in reversed(removed_indices):
                del result[idx]

            # Check if expr is absorbed by any existing expression
            absorbed = False
            for existing in result:
                if expr.is_And and existing.is_Or:
                    if set(expr.args).issubset(set(existing.args)):
                        absorbed = True
                        break
                elif expr.is_Or and existing.is_And:
                    if set(expr.args).issubset(set(existing.args)):
                        absorbed = True
                        break
                elif expr.is_Not and existing.is_Not:
                    # Negation absorption
                    if expr.args[0] == existing.args[0]:
                        absorbed = True
                        break
            if not absorbed:
                result.append(expr)
        return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    if hook is None:
        raise ValueError("hook cannot be None")
    # Ensure a registry exists on the instance
    if not hasattr(self, "_registry") or not isinstance(self._registry, dict):
        self._registry = {}
    def decorator(func):
        if not callable(func):
            raise TypeError("Handler must be callable")
        listeners = self._registry.setdefault(hook, [])
        listeners.append(func)
        return func
    return decorator

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    # Ensure the registry container exists
    if not hasattr(self, "_handlers"):
        self._handlers = {}
    registry = self._handlers

    # Prepare the list for this hook
    try:
        if hook not in registry:
            registry[hook] = []
    except Exception as exc:
        raise RuntimeError(f"Failed to prepare registry entry for hook {hook!r}") from exc

    def decorator(func):
        """Register the given function as a listener for this hook."""
        if not callable(func):
            raise TypeError(f"Handler must be callable, got {type(func)!r}")

        try:
            registry[hook].append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler {func!r} for hook {hook!r}") from exc

        return func

    return decorator

def on(self, hook):
