    if not isinstance(etcd_port, int) or not (0 <= etcd_port <= 65535):
        raise ValueError("etcd_port must be an integer between 0 and 65535")

    # Construct the configuration dictionary
    config = {
        "user": user,
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }
    return config

