def tzname_in_python2(namefunc):
    """Ensure the wrapped tzname function returns a bytestring in Python 2.

    If running under Python 3 the passed function is returned unchanged.
    Any Unicode string returned by the wrapped function will be encoded
    using UTF‑8. Invalid inputs (non‑callables) raise a TypeError.
    """
    import sys
    if not callable(namefunc):
        raise TypeError('tzname_in_python2 requires a callable')

    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            try:
                result = namefunc(*args, **kwargs)
            except Exception:
                # propagate any exception from the original function
                raise
            # In Python 2, unicode objects need to be encoded to bytes
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except UnicodeEncodeError:
                    # Fallback: encode using latin‑1 to preserve byte values
                    return result.encode('latin1')
            return result
        return wrapper
    else:
        # On Python 3, tzname() already returns a Unicode string;
        # no conversion is necessary.
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    result = {}
    # Primary attempt: use importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError

        # Guess the top‑level package name from the current module
        top_level = __name__.split('.')[0]
        try:
            result['version'] = version(top_level)
        except PackageNotFoundError:
            # If the package is not installed, fall back to environment variable or git
            result['version'] = None

        # Attempt to get full revision ID (e.g., commit hash) via git
        if result.get('version') is None:
            import subprocess, os
            cwd = os.path.dirname(__file__)
            try:
                rev = subprocess.check_output(
                    ["git", "rev-parse", "HEAD"],
                    cwd=cwd,
                    stderr=subprocess.DEVNULL,
                    text=True,
                ).strip()
                result['full-revisionid'] = rev
                # Use a generic version string when we cannot get a tag
                result['version'] = "0+unknown"
            except Exception:
                pass
    except Exception:
        # importlib.metadata might not be available or operation may fail
        result = {}

    # Fallback: try to read a VERSION file in the same directory
    if not result.get('version'):
        try:
            import os
            ver_file = os.path.join(os.path.dirname(__file__), 'VERSION')
            with open(ver_file, 'r', encoding='utf-8') as f:
                result['version'] = f.read().strip()
        except Exception:
            pass

    # Ensure dictionary has both keys
    if 'version' not in result or not result['version']:
        result['version'] = '0+unknown'
    if 'full-revisionid' not in result:
        result['full-revisionid'] = ''

    return result

def get_versions():
    """Get version information or return default if unable to do so."""
    default = {
        'release': '0.0.0',
        'major': 0,
        'minor': 0,
        'patch': 0
    }
    # Try to read a VERSION file in the current working directory
    try:
        with open('VERSION', 'r', encoding='utf-8') as f:
            version_str = f.read().strip()
    except Exception:
        return default
    if not version_str:
        return default
    # Split into major, minor, patch (ignore any pre/post release tags)
    parts = version_str.split('.')
    try:
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0
    except Exception:
        return default
    return {
        'release': version_str,
        'major': major,
        'minor': minor,
        'patch': patch
    }

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        package = __package__ if __package__ else __name__.split('.')[0]
        metadata = __import__('importlib.metadata')
        return metadata.version(package)
    except Exception:
        try:
            pkg_res = __import__('pkg_resources')
            return pkg_res.get_distribution(package).version
        except Exception:
            return '0.0.0 (unknown)'

