def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    import sys

    # Normalize commands to a list of command strings
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        # Ensure each element is a string
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    # arguments for each command (assumed same for all commands if provided)
    if args is None:
        args_list = []
    else:
        if isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise TypeError("args must be None or a list/tuple of strings")

    results = []

    for cmd in cmd_list:
        # Build the full command string with quoted args if using shell
        if args_list:
            quoted_args = " ".join(shlex.quote(str(a)) for a in args_list)
            full_cmd = f"{cmd} {quoted_args}"
        else:
            full_cmd = cmd

        if verbose:
            print(f"Running: {full_cmd}")

        try:
            proc = subprocess.run(
                full_cmd,
                shell=True,
                cwd=cwd,
                capture_output=True,
                text=True,
                env=env,
                stderr=subprocess.DEVNULL if hide_stderr else None,
            )
        except Exception as exc:
            raise RuntimeError(f"Execution of command '{full_cmd}' failed: {exc}") from exc

        if verbose:
            print(f"Return code: {proc.returncode}")
            if not hide_stderr and proc.stderr:
                sys.stderr.write(proc.stderr)

        results.append({
            'command': cmd,
            'returncode': proc.returncode,
            'stdout': proc.stdout,
            'stderr': None if hide_stderr else proc.stderr,
        })

    return results

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os

    # Validate commands
    if isinstance(commands, str):
        cmd_base = [commands]
    elif isinstance(commands, list):
        if not all(isinstance(c, str) for c in commands):
            raise TypeError("All elements of commands must be strings")
        cmd_base = list(commands)
    else:
        raise TypeError("commands must be a string or a list of strings")

    # Validate args
    if not hasattr(args, "__iter__") or isinstance(args, str):
        raise TypeError("args must be an iterable of strings")
    cmd_args = list(args)
    if not all(isinstance(a, str) for a in cmd_args):
        raise TypeError("All elements of args must be strings")

    command = cmd_base + cmd_args
    if verbose:
        print(f"Running command: {' '.join(command)}")

    # Prepare environment
    env_vars = os.environ.copy()
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        env_vars.update(env)

    try:
        result = subprocess.run(
            command,
            cwd=cwd,
            capture_output=True,
            text=True,
            env=env_vars,
        )
        if hide_stderr:
            result = subprocess.CompletedProcess(
                args=result.args,
                returncode=result.returncode,
                stdout=result.stdout,
                stderr="",
            )
        return result
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {commands}") from exc
    except subprocess.CalledProcessError as exc:
        # CalledProcessError is not raised here because we did not set `check=True`.
        # However, if the user wants to catch non-zero exit codes, they can check `exc.returncode`.
        if verbose:
            print(f"Command failed with return code {exc.returncode}")
            if exc.stderr:
                print(f"stderr: {exc.stderr}")
        raise

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Import necessary modules locally to avoid top-level imports
    import subprocess
    import os
    import sys
    import shlex

    # Validate input types
    if not isinstance(commands, (str, list, tuple)):
        raise TypeError(f"'commands' must be a string or a list/tuple, got {type(commands).__name__}")
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError(f"'args' must be a list or tuple, got {type(args).__name__}")
    if env is not None and not isinstance(env, dict):
        raise TypeError(f"'env' must be a dict or None, got {type(env).__name__}")

    # Build the command list
    if isinstance(commands, str):
        # Split command string into tokens
        try:
            cmd = shlex.split(commands)
        except Exception as e:
            raise ValueError(f"Failed to parse command string '{commands}': {e}") from e
    else:
        cmd = list(commands)

    # Append any additional arguments
    cmd.extend(list(args))

    # Resolve environment
    env_dict = os.environ.copy()
    if env:
        env_dict.update(env)

    # Execute the command
    try:
        # Capture output so we can return it or display it
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_dict,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except PermissionError as e:
        raise RuntimeError(f"Permission denied when executing: {' '.join(cmd)}") from e
    except OSError as e:
        raise RuntimeError(f"Failed to execute command: {' '.join(cmd)}\n{e}") from e

    # Optional verbose output
    if verbose:
        # Show the command being executed
        print(f"[run_command] Executing: {' '.join(cmd)}")
        # Show stdout
        if result.stdout:
            print(result.stdout, end='')
        # Show stderr unless hidden
        if not hide_stderr and result.stderr:
            print(result.stderr, file=sys.stderr, end='')

    return result

