_VCS_REGISTRY = {}

def register_vcs_handler(vcs, method=None):
    """
    Decorator to mark a function as the handler for a specific VCS.

    The decorated function will receive an attribute ``__vcs_handler__`` with the
    name of the VCS, and it will be stored in the global :data:`_VCS_REGISTRY`
    mapping VCS names to handler callables.

    The decorator can be applied in two ways::

        @register_vcs_handler('git')
        def my_handler(...):
            ...

    or::

        @register_vcs_handler('git', my_handler)
    """
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")

    def decorator(func):
        if not callable(func):
            raise TypeError("method must be callable")
        # Attach VCS metadata
        setattr(func, "__vcs_handler__", vcs)
        # Register the handler
        if vcs in _VCS_REGISTRY:
            existing = _VCS_REGISTRY[vcs]
            raise RuntimeError(f"VCS handler for '{vcs}' already registered: {existing}")
        _VCS_REGISTRY[vcs] = func
        return func

    if method is None:
        # Usage: @register_vcs_handler('git')
        return decorator
    if not callable(method):
        raise TypeError("method must be callable")
    # Usage: @register_vcs_handler('git', my_handler)
    return decorator(method)

VCS_HANDLERS = {}

def register_vcs_handler(vcs, method):
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not isinstance(method, str):
        raise TypeError("method must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        key = (vcs.lower(), method.lower())
        VCS_HANDLERS[key] = func
        setattr(func, "_vcs", vcs)
        setattr(func, "_method", method)
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to retrieve a collection of objects that represent the hierarchy.
    # The attribute names are guessed; fall back to an empty iterable if not found.
    objects = getattr(self, 'objects', None) or getattr(self, '_objects', None) or getattr(self, 'root_objects', None) \
              or getattr(self, 'root', None) or getattr(self, 'hierarchy', None)

    # Normalize to an iterable of objects
    if isinstance(objects, dict):
        objects = objects.values()
    if not hasattr(objects, '__iter__'):
        # Unable to iterate; treat as no objects
        objects = []

    for obj in objects:
        num_objects += 1
        is_valid = True
        try:
            if validate_objects:
                if hasattr(obj, 'is_valid') and callable(obj.is_valid):
                    is_valid = bool(obj.is_valid())
                elif hasattr(obj, 'valid'):
                    is_valid = bool(obj.valid)
                else:
                    # If no explicit validation method, assume object is valid
                    is_valid = True
        except Exception as e:
            is_valid = False
            if show_warnings:
                print(f"Warning: Object {obj!r} validation raised exception: {e}")

        if is_valid and check_digests:
            try:
                if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                    digest_ok = bool(obj.check_digest())
                elif hasattr(obj, 'verify_digest') and callable(obj.verify_digest):
                    digest_ok = bool(obj.verify_digest())
                else:
                    # Assume digest verified if no method
                    digest_ok = True
            except Exception as e:
                digest_ok = False
                if show_warnings:
                    print(f"Warning: Object {obj!r} digest check raised exception: {e}")
            if not digest_ok:
                is_valid = False

        if is_valid:
            good_objects += 1
        elif show_warnings:
            print(f"Warning: Object {obj!r} failed validation.")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, call each object's ``validate`` method when available.
    check_digests : bool, optional
        If True, call each object's ``check_digest`` method when available.
    show_warnings : bool, optional
        If True, print warnings for validation or digest failures.

    Returns
    -------
    tuple
        (num_objects, good_objects) – the total number of objects examined and
        the number of objects that passed all requested checks.
    """
    #--- Argument validation -------------------------------------------------
    if not isinstance(validate_objects, bool):
        raise TypeError(f"validate_objects must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"check_digests must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"show_warnings must be a bool, got {type(show_warnings).__name__}")

    num_objects = 0
    good_objects = 0

    #--- Recursive traversal of the hierarchy --------------------------------
    stack = [self]
    while stack:
        obj = stack.pop()
        num_objects += 1
        passed = True

        # Validate the object if requested
        if validate_objects and hasattr(obj, "validate"):
            try:
                if not obj.validate():
                    passed = False
                    if show_warnings:
                        print(f"Validation failed for object: {repr(obj)}")
            except Exception as exc:
                passed = False
                if show_warnings:
                    print(f"Exception during validate() for {repr(obj)}: {exc}")

        # Check the digest if requested
        if check_digests and hasattr(obj, "check_digest"):
            try:
                if not obj.check_digest():
                    passed = False
                    if show_warnings:
                        print(f"Digest check failed for object: {repr(obj)}")
            except Exception as exc:
                passed = False
                if show_warnings:
                    print(f"Exception during check_digest() for {repr(obj)}: {exc}")

        if passed:
            good_objects += 1

        # Gather children if the object stores them in a collection
        children = getattr(obj, "children", None)
        if isinstance(children, (list, tuple)):
            stack.extend(children)
        elif hasattr(children, "__iter__") and not isinstance(children, (str, bytes)):
            try:
                stack.extend(list(children))
            except Exception as exc:
                if show_warnings:
                    print(f"Could not iterate children of {repr(obj)}: {exc}")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        Tuple[int, int]: (num_objects, good_objects)
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError(f"'validate_objects' must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"'check_digests' must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"'show_warnings' must be a bool, got {type(show_warnings).__name__}")

    # Determine the collection of objects to validate
    objects = getattr(self, "objects", None)
    if objects is None:
        raise AttributeError("The object does not have an 'objects' attribute to validate")

    # Normalise objects to an iterable
    if isinstance(objects, dict):
        iterable = objects.values()
    elif isinstance(objects, (list, tuple, set)):
        iterable = objects
    else:
        raise TypeError(f"'objects' attribute must be a list, tuple, set, or dict, got {type(objects).__name__}")

    num_objects = 0
    good_objects = 0

    for obj in iterable:
        num_objects += 1
        is_valid = True

        try:
            if validate_objects:
                validator = getattr(obj, "validate", None)
                if validator is not None and callable(validator):
                    if not validator():
                        is_valid = False
                else:
                    # If no validate method, assume the object is invalid
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj!r} lacks a 'validate' method; treated as invalid.")
        except Exception as exc:
            is_valid = False
            if show_warnings:
                print(f"Warning: Validation of object {obj!r} raised an exception: {exc}")

        if is_valid and check_digests:
            try:
                checker = getattr(obj, "check_digest", None)
                if checker is not None and callable(checker):
                    if not checker():
                        is_valid = False
                else:
                    # If no check_digest method, assume digest check fails
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj!r} lacks a 'check_digest' method; digest check failed.")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: Digest check of object {obj!r} raised an exception: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Helper to traverse any nested structure
    def _traverse(node):
        if isinstance(node, (list, tuple)):
            for item in node:
                yield from _traverse(item)
        elif hasattr(node, '__iter__') and not isinstance(node, (str, bytes)):
            for item in node:
                yield from _traverse(item)
        else:
            yield node

    try:
        root = getattr(self, 'root_storage', None)
        if root is None:
            if show_warnings:
                print("Warning: No root_storage attribute found.")
            return num_objects, good_objects

        for obj in _traverse(root):
            num_objects += 1
            is_valid = True

            if validate_objects:
                try:
                    # Assume obj has an is_valid() method; fall back to a default
                    is_valid = getattr(obj, 'is_valid', lambda: True)()
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Validation error for object {obj!r}: {e}")

            if check_digests and is_valid:
                try:
                    # Assume obj has a check_digest() method; fall back to a default
                    digest_ok = getattr(obj, 'check_digest', lambda: True)()
                    if not digest_ok:
                        is_valid = False
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Digest check error for object {obj!r}: {e}")

            if is_valid:
                good_objects += 1

    except Exception as e:
        if show_warnings:
            print(f"Error while validating hierarchy: {e}")

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    from pathlib import Path
    # Ensure the instance has a root path set before initialization.
    try:
        root_attr = getattr(self, "root")
    except AttributeError:
        raise AttributeError(
            "Instance attribute 'root' must be set to the desired repository "
            "location before calling initialize()."
        )
    root = Path(root_attr).expanduser()
    # If the root already exists, we consider that an error.
    if root.exists():
        raise FileExistsError(f"OCFL storage root already exists: {root}")
    # Create the root directory and the required subdirectories.
    try:
        root.mkdir(parents=True, exist_ok=False)
        subdirs = ["objects", "inventories", ".ocfl"]
        for sub in subdirs:
            (root / sub).mkdir(parents=False, exist_ok=False)
        # Write a minimal ocfl‑version file inside the .ocfl directory.
        (root / ".ocfl" / "ocfl-version").write_text("1.0\n")
    except OSError as exc:
        raise RuntimeError(
            f"Failed to create OCFL storage root at {root}: {exc}"
        ) from exc
    # Store the resolved Path object for future reference.
    setattr(self, "root_path", root)
    return root

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str) or not version or not version.isdigit():
            raise ValueError("Invalid version format: must be a non-empty numeric string")
        num = int(version)
        new_num = num + 1

        # Preserve leading zeros if the original version had them
        original_length = len(version)
        if new_num < 10 ** original_length:
            return str(new_num).zfill(original_length)
        else:
            # If the incremented number has more digits, just return it plain
            return str(new_num)
    except Exception as e:
        raise ValueError(f"Error computing next version: {e}") from e

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    parts = version.split('.')
    # Find the last component that is purely numeric
    idx = None
    for i in range(len(parts) - 1, -1, -1):
        if parts[i].isdigit():
            idx = i
            break

    if idx is None:
        raise ValueError("no numeric component found in version string")

    try:
        num = int(parts[idx])
        new_num = num + 1
    except ValueError:
        raise ValueError("numeric component is out of bounds")

    # Preserve leading zeros if present
    width = len(parts[idx])
    new_part = str(new_num).zfill(width) if len(str(new_num)) <= width else str(new_num)
    parts[idx] = new_part
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    Parameters
    ----------
    version_dirs : list of str
        A list of version directory names, assumed to be in numerical order.

    Notes
    -----
    The method stores a dictionary `self.different_digests` mapping each file path that
    has a differing digest to the list of version directories in which the difference
    was found. It raises a ``FileNotFoundError`` if any expected inventory file is
    missing.
    """
    # Load root inventory digests
    root_inventory_path = "inventory.txt"
    root_digests = {}
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = line.split(",", 1)
                if len(parts) == 2:
                    root_digests[parts[0]] = parts[1]
    except FileNotFoundError:
        # If root inventory is missing, treat all digests as differing.
        pass

    self.different_digests = {}
    missing_inventories = []

    for vd in version_dirs:
        inventory_path = f"{vd}/inventory.txt"
        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(",", 1)
                    if len(parts) != 2:
                        continue
                    file_path, digest = parts
                    root_digest = root_digests.get(file_path)
                    if root_digest is None or root_digest != digest:
                        self.different_digests.setdefault(file_path, []).append(vd)
        except FileNotFoundError:
            missing_inventories.append(vd)

    if missing_inventories:
        missing_str = ", ".join(missing_inventories)
        raise FileNotFoundError(
            f"Missing inventory in the following version directories: {missing_str}"
        )

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic validation of input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")

        for idx, ver in enumerate(version_dirs):
            if not isinstance(ver, str) or not ver:
                raise ValueError(f"version_dirs[{idx}] must be a non-empty string representing a directory name")

        # Ensure that the class has the necessary attributes for inventories
        if not hasattr(self, "root_inventory"):
            raise AttributeError("Instance missing 'root_inventory' attribute required for validation")
        if not isinstance(self.root_inventory, dict):
            raise TypeError("'root_inventory' attribute must be a dict mapping path to digest")

        mismatches = {}          # mapping from version name to list of mismatch messages
        previous_inventory = {}  # the inventory of the previous (or earlier) version

        for ver in version_dirs:
            # Attempt to fetch the inventory for this version.
            # It is assumed that an attribute named 'inventory_{ver}' exists.
            inv_attr = f"inventory_{ver}"
            if not hasattr(self, inv_attr):
                mismatches.setdefault(ver, []).append(f"Missing inventory attribute {inv_attr}")
                previous_inventory = {}          # reset because we cannot compare further
                continue
            inventory = getattr(self, inv_attr)
            if not isinstance(inventory, dict):
                mismatches.setdefault(ver, []).append(
                    f"Inventory '{inv_attr}' is not a dict and cannot be validated"
                )
                previous_inventory = inventory  # use whatever was present to continue
                continue

            # Check that all items from the previous inventory are present in this one
            missing_paths = set(previous_inventory.keys()) - set(inventory.keys())
            for path in missing_paths:
                mismatches.setdefault(ver, []).append(
                    f"Missing path '{path}' compared to earlier inventory"
                )

            # Check for digest differences against the root inventory
            for path, digest in inventory.items():
                root_digest = self.root_inventory.get(path)
                if root_digest is None:
                    # If the root inventory doesn't contain this path, skip comparison
                    continue
                if digest != root_digest:
                    mismatches.setdefault(ver, []).append(
                        f"Digest mismatch for '{path}' in version '{ver}'"
                    )

            previous_inventory = inventory

        return mismatches

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        import re

        if not os.path.exists(path):
            return f"Path does not exist: {path}"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            entries = os.listdir(path)
            # If there is a "0=*" file, this directory is at least an OCFL
            # container (object or root).
            if "0=*" in entries:
                # Check for subdirectories that match OCFL object ID pattern
                # (7 hexadecimal characters, case-insensitive).
                subdirs = [
                    d for d in entries
                    if os.path.isdir(os.path.join(path, d))
                ]
                if any(re.fullmatch(r"[0-9a-fA-F]{7}", d) for d in subdirs):
                    # Presence of such named subdirectories indicates a storage root.
                    return "root"
                else:
                    # Otherwise, this is an object directory.
                    return "object"
            else:
                # No inventory file; could be an empty or unrelated directory.
                return "unknown directory"

        return f"Unsupported path type: {path}"

    except Exception as e:
        # Provide the exception message as the error description.
        return f"Error: {e}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    try:
        import os

        if not os.path.exists(path):
            return f"Path does not exist: {path}"

        if os.path.isfile(path):
            return 'file'

        if os.path.isdir(path):
            # Find Namaste files that start with '0='
            namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]
            if not namaste_files:
                return f"No Namaste file found in directory: {path}"
            if len(namaste_files) > 1:
                return f"Multiple Namaste files found in directory: {path}"
            namaste_path = os.path.join(path, namaste_files[0])

            try:
                with open(namaste_path, 'r', encoding='utf-8') as fh:
                    content = fh.read().lower()
            except Exception as e:
                return f"Failed to read Namaste file '{namaste_path}': {e}"

            # Very simple heuristics based on the presence of keywords in the Namaste file
            if 'root' in content:
                return 'root'
            if 'object' in content:
                return 'object'
            return f"Unrecognised Namaste file format in '{namaste_path}'"

        return f"Unrecognised path type: {path}"

    except Exception as exc:
        return f"Error determining path type: {exc}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other    - string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Check that the path exists and is accessible
    try:
        if not os.path.exists(path):
            return f'not_found: {path}'
    except OSError as exc:
        return f'os_error: {exc}'

    # If it's a file, just return 'file'
    if os.path.isfile(path):
        return 'file'

    # If it's a directory, inspect Namaste files
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as exc:
            return f'cannot_list_dir: {exc}'

        # Find files that start with "0=" (Namaste files)
        namaste_files = [
            f for f in entries
            if f.startswith('0=') and os.path.isfile(os.path.join(path, f))
        ]

        if not namaste_files:
            return 'no_namaste_file'

        # Heuristic: look at file contents to decide root vs object
        root_keywords = {'repo', 'repository', 'storage', 'root'}
        object_keywords = {'object', 'inventory', 'manifest', 'version'}

        root_found = False
        object_found = False

        for nf in namaste_files:
            full = os.path.join(path, nf)
            try:
                with open(full, 'r', encoding='utf-8') as fh:
                    content = fh.read().strip()
            except OSError as exc:
                return f'cannot_read_namaste: {full} ({exc})'

            # Strip leading "0=" if present
            key = content[2:].strip().lower() if content.lower().startswith('0=') else content.lower()

            # Check for root indicators
            if any(k in key for k in root_keywords):
                root_found = True

            # Check for object indicators
            if any(k in key for k in object_keywords):
                object_found = True

        if root_found and not object_found:
            return 'root'
        if object_found and not root_found:
            return 'object'
        if root_found and object_found:
            return 'conflicting_namaste'
        # If we cannot confidently determine
        return 'unknown_namaste_format'

    # If it's neither file nor directory
    return f'unknown_path_type: {path}'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        if not isinstance(path, str):
            return "invalid path: not a string"
        if path == "":
            return "invalid path: empty string"

        p = os.path.normpath(path)
        if not os.path.exists(p):
            return "path does not exist"

        if os.path.isfile(p) or os.path.islink(p):
            return "file"

        if os.path.isdir(p):
            try:
                entries = os.listdir(p)
            except OSError as e:
                return f"error listing directory: {e}"

            namaste_files = [e for e in entries if e.startswith("0=")]
            if not namaste_files:
                return "unknown directory type"
            if len(namaste_files) > 1:
                return "multiple namaste files found"

            namaste_name = namaste_files[0]
            namaste_path = os.path.join(p, namaste_name)

            # If the file is 0=manifest, it is an object
            if namaste_name == "0=manifest":
                return "object"
            # If the file is 0=namaste, we treat it as a root for this implementation
            if namaste_name == "0=namaste":
                return "root"

            # Fallback: inspect the first line of the namaste file
            try:
                with open(namaste_path, "r", encoding="utf-8") as fh:
                    first_line = fh.readline().strip()
            except (OSError, UnicodeDecodeError) as e:
                return f"error reading namaste file: {e}"

            if first_line.upper().startswith("OCFL"):
                # Heuristic based on content
                if "ROOT" in first_line.upper():
                    return "root"
                else:
                    return "object"
            return "unknown namaste file content"

        return "unknown path type"
    except Exception as exc:
        return f"unexpected error: {exc}"

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, Node) tuples that may contain duplicate keys.
    """
    from collections import OrderedDict

    # Simple check to ensure nodes is iterable of tuples of length 2
    if not isinstance(nodes, (list, tuple)):
        raise TypeError("nodes must be a list or tuple of (ScalarNode, Node) pairs")
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each element in nodes must be a tuple (ScalarNode, Node)")

    def merge_mapping_nodes(node1, node2):
        """Deep merge two MappingNode objects, returning a new MappingNode."""
        # Using the tag from the first node for consistency
        tag = node1.tag if hasattr(node1, "tag") else node1[1]
        # Convert mapping values to ordered dicts keyed by scalar value
        mapping1 = OrderedDict()
        mapping2 = OrderedDict()
        for k, v in node1.value:
            mapping1[k.value] = (k, v)
        for k, v in node2.value:
            mapping2[k.value] = (k, v)

        merged = OrderedDict()
        # Preserve order of first occurrence of keys
        for key, kv in mapping1.items():
            merged[key] = kv
        for key, kv in mapping2.items():
            if key in merged:
                # Merge recursively if both values are MappingNode
                existing_k, existing_v = merged[key]
                if hasattr(existing_v, "tag") and hasattr(kv[1], "tag"):
                    if 'map' in getattr(existing_v, "tag", "") and 'map' in getattr(kv[1], "tag", ""):
                        merged[key] = (existing_k, merge_mapping_nodes(existing_v, kv[1]))
                    else:
                        # scalar overwrite
                        merged[key] = (existing_k, kv[1])
                else:
                    merged[key] = (existing_k, kv[1])
            else:
                merged[key] = kv

        merged_list = [(k, v) for (_, (k, v)) in merged.items()]
        return type(node1)(tag=tag, value=merged_list)

    merged = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_value = merged[key][1]
            if hasattr(existing_value, "tag") and hasattr(value_node, "tag"):
                if 'map' in getattr(existing_value, "tag", "") and 'map' in getattr(value_node, "tag", ""):
                    # Both are MappingNode; merge recursively
                    merged[key] = (merged[key][0], merge_mapping_nodes(existing_value, value_node))
                else:
                    # Override with last value
                    merged[key] = (merged[key][0], value_node)
            else:
                merged[key] = (merged[key][0], value_node)
        else:
            merged[key] = (key_node, value_node)

    return [(k, v) for (_, (k, v)) in merged.items()]

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Value) tuples where values may be MappingNode or any other node.
    Duplicate ScalarNode keys are merged:
      * If both values are MappingNode, merge their key/value pairs recursively.
      * Otherwise, the later value overrides the earlier one.
    Parameters
    ----------
    nodes : list
        List of tuples (ScalarNode, Value), where Value can be a MappingNode or any node.
    Returns
    -------
    list
        List of tuples with merged nodes, preserving the original order of first appearance.
    """
    # Helper to detect a MappingNode based on its tag attribute
    def is_mapping_node(node):
        try:
            return getattr(node, "tag", "").startswith("tag:yaml.org,2002:map")
        except Exception:
            return False

    # Recursively merge two values that might be MappingNodes
    def merge_values(v1, v2):
        if is_mapping_node(v1) and is_mapping_node(v2):
            # Merge the list of tuples contained in both MappingNodes
            merged_map = _merge_mapping_lists(v1.value, v2.value)
            # Construct a new MappingNode preserving the tag from the first node
            return type(v1)(tag=v1.tag, value=merged_map)
        else:
            # Non-mapping values: last value wins
            return v2

    # Merge two lists of tuples (key, value) representing a MappingNode's content
    def _merge_mapping_lists(list1, list2):
        merged_dict = {}
        # Preserve insertion order: first occurrences from list1
        for key, val in list1:
            merged_dict[key.value] = (key, val)
        for key, val in list2:
            if key.value in merged_dict:
                existing_key, existing_val = merged_dict[key.value]
                merged_val = merge_values(existing_val, val)
                merged_dict[key.value] = (existing_key, merged_val)
            else:
                merged_dict[key.value] = (key, val)
        return list(merged_dict.values())

    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list of (ScalarNode, Value) tuples")

    result_dict = {}
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError("Each node entry must be a tuple of (ScalarNode, Value)")
        key_node, val_node = entry
        if key_node is None or not hasattr(key_node, "value"):
            raise ValueError("Key node must be a ScalarNode with a 'value' attribute")
        key_id = key_node.value
        if key_id in result_dict:
            existing_key_node, existing_val_node = result_dict[key_id]
            merged_val = merge_values(existing_val_node, val_node)
            result_dict[key_id] = (existing_key_node, merged_val)
        else:
            result_dict[key_id] = (key_node, val_node)

    return list(result_dict.values())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _merge_map_nodes(map1, map2):
        # Merge two mapping nodes (map1 is updated in-place, map2 is not modified)
        # Both map1 and map2 are expected to have a 'value' attribute which is a list of tuples
        # (key_node, value_node)
        merged_entries = {}
        # Add existing entries from map1
        for k_node, v_node in getattr(map1, 'value', []):
            merged_entries[getattr(k_node, 'value', None)] = (k_node, v_node)
        # Merge entries from map2
        for k_node, v_node in getattr(map2, 'value', []):
            key_val = getattr(k_node, 'value', None)
            if key_val in merged_entries:
                old_k_node, old_v_node = merged_entries[key_val]
                if getattr(old_v_node, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(v_node, 'tag', None) == 'tag:yaml.org,2002:map':
                    # Recursively merge nested mapping nodes
                    merged_child = _merge_map_nodes(old_v_node, v_node)
                    merged_entries[key_val] = (old_k_node, merged_child)
                else:
                    # Non-mapping node overrides old value, keep original key node
                    merged_entries[key_val] = (old_k_node, v_node)
            else:
                merged_entries[key_val] = (k_node, v_node)
        # Update map1's value list with the merged result
        map1.value = list(merged_entries.values())
        return map1

    result = {}
    for key_node, value_node in nodes:
        # Skip invalid entries
        if not hasattr(key_node, 'value'):
            continue
        key = key_node.value
        if key in result:
            existing_key_node, existing_value_node = result[key]
            # Merge mapping nodes if both sides are mappings
            if getattr(existing_value_node, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(value_node, 'tag', None) == 'tag:yaml.org,2002:map':
                merged_node = _merge_map_nodes(existing_value_node, value_node)
                result[key] = (existing_key_node, merged_node)
            else:
                # Non-mapping values: last value wins, keep original key node
                result[key] = (existing_key_node, value_node)
        else:
            result[key] = (key_node, value_node)
    # Convert back to list of tuples preserving initial insertion order
    merged_nodes = []
    for key in result:
        key_node, value_node = result[key]
        merged_nodes.append((key_node, value_node))
    return merged_nodes

def deep_merge_nodes(nodes):
    """
    Merge duplicate keys in a list of (ScalarNode, node) tuples.
    For duplicate keys with MappingNode values, merge the mappings.
    For other duplicates, the last value wins.
    Returns a new list of tuples with merged values.
    """
    try:
        if not isinstance(nodes, list):
            raise TypeError("nodes must be a list")
        merged = []
        key_index = {}
        for pair in nodes:
            if (not isinstance(pair, tuple)) or len(pair) != 2:
                raise TypeError("Each item in nodes must be a tuple of length 2")
            key_node, val_node = pair
            if not hasattr(key_node, "value"):
                raise TypeError("Key node must have a 'value' attribute")
            key = key_node.value
            if key in key_index:
                idx = key_index[key]
                existing_key_node, existing_val_node = merged[idx]
                # Merge if both are MappingNodes
                if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                    merged_val = _merge_mapping_nodes(existing_val_node, val_node)
                    merged[idx] = (existing_key_node, merged_val)
                else:
                    # Last value wins
                    merged[idx] = (key_node, val_node)
            else:
                merged.append((key_node, val_node))
                key_index[key] = len(merged) - 1
        return merged
    except Exception as exc:
        raise RuntimeError(f"Failed to deep merge nodes: {exc}") from exc


def _merge_mapping_nodes(node1, node2):
    """
    Recursively merge two MappingNode objects.
    Returns a new MappingNode with merged content.
    """
    # Build dicts of key->index for node1
    mapping1 = {}
    for i, (k, v) in enumerate(node1.value):
        if hasattr(k, "value"):
            mapping1[k.value] = (i, k, v)
    # Prepare new value list
    new_value = list(node1.value)
    for k2, v2 in node2.value:
        if not hasattr(k2, "value"):
            # key of node2 is not a ScalarNode, skip merging
            new_value.append((k2, v2))
            continue
        key = k2.value
        if key in mapping1:
            idx, existing_k, existing_v = mapping1[key]
            if isinstance(existing_v, MappingNode) and isinstance(v2, MappingNode):
                merged_child = _merge_mapping_nodes(existing_v, v2)
                new_value[idx] = (existing_k, merged_child)
            else:
                # last wins
                new_value[idx] = (existing_k, v2)
        else:
            new_value.append((k2, v2))
    return MappingNode(node1.tag, new_value)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    """
    # Ensure the argument is a valid ArgumentParser instance.
    try:
        import argparse
    except ImportError:
        raise ImportError("argparse module is required for parser_flags to work.")
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("Expected an argparse.ArgumentParser instance, got %r" % type(parser))

    # Extract all option strings from the parser's actions.
    flags = []
    for action in getattr(parser, "_actions", []):
