        except Exception:
            # If the parser raises an error (e.g., missing required arguments), exclude it
            parsed_namespaces[name] = None

    # Determine arguments not claimed by any parser
    if unknowns_by_parser:
        # Build set of arguments that are unknown to all parsers
        common_unknown_set = set(unknowns_by_parser[0])
        for unk in unknowns_by_parser[1:]:
            common_unknown_set.intersection_update(unk)
        # Preserve original order of appearance
        remaining = [arg for arg in unparsed_arguments if arg in common_unknown_set]
    else:
        # No parsing attempted, return all arguments as remaining
        remaining = list(unparsed_arguments)

    return parsed_namespaces, remaining

