def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode key, Node value) tuples producing a list with unique keys.
    MappingNode values are merged recursively; other value collisions are resolved by the last
    occurrence. The original key node from the first appearance is retained.
    """
    # Validate input
    if not isinstance(nodes, list):
        raise TypeError(f"nodes must be a list, got {type(nodes).__name__}")

    merged = {}
    for item in nodes:
        try:
            key_node, val_node = item
        except Exception:
            raise TypeError("each element of nodes must be a 2-tuple of (ScalarNode, Node)")

        # Key validation
        if not hasattr(key_node, "value"):
            raise TypeError(f"expected ScalarNode as key, got {type(key_node).__name__}")
        key = key_node.value

        if key in merged:
            existing_key_node, existing_val_node = merged[key]

            # Determine if both values are MappingNode
            if (
                hasattr(ruamel.yaml.nodes, "MappingNode")
                and isinstance(existing_val_node, ruamel.yaml.nodes.MappingNode)
                and isinstance(val_node, ruamel.yaml.nodes.MappingNode)
            ):
                # Recursively merge the two mapping nodes
                merged_value = ruamel.yaml.nodes.MappingNode(
                    tag=existing_val_node.tag,
                    value=deep_merge_nodes(existing_val_node.value + val_node.value),
                )
                # Preserve the original key node
                merged[key] = (existing_key_node, merged_value)
            else:
                # Non-mapping collision: last value wins
                merged[key] = (existing_key_node, val_node)
        else:
            # New key entry
            merged[key] = (key_node, val_node)

    return list(merged.values())

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode key, node value) tuples, merging MappingNode values for duplicate keys.
    """
    # Basic validation
    if not isinstance(nodes, (list, tuple)):
        raise TypeError("nodes must be a list or tuple of key/value pairs")
    # Helper: determine if node looks like a MappingNode
    def is_mapping(node):
        return hasattr(node, "value") and hasattr(node, "tag") and isinstance(node.value, list)
    # Merge two nodes, giving precedence to the second
    def merge_nodes(a, b):
        if is_mapping(a) and is_mapping(b):
            return merge_mapping_nodes(a, b, b)   # use b's key nodes for new entries
        return b  # last wins
    # Merge two mapping nodes
    def merge_mapping_nodes(ma, mb, key_node_from_mb):
        # Build dictionary of existing keys from ma
        result = []
        existing = {}
        for k_node, v_node in ma.value:
            key = k_node.value
            existing[key] = (k_node, v_node)
            result.append((k_node, v_node))
        # Merge / add entries from mb
        for k_node, v_node in mb.value:
            key = k_node.value
            if key in existing:
                # Merge existing value
                existing_k, existing_v = existing[key]
                merged_v = merge_nodes(existing_v, v_node)
                # Update result entry
                idx = next(i for i, (nk, nv) in enumerate(result) if nk.value == key)
                result[idx] = (k_node, merged_v)
                existing[key] = (k_node, merged_v)
            else:
                # New entry
                result.append((k_node, v_node))
                existing[key] = (k_node, v_node)
        # Construct new mapping node with original tag from ma
        mapping_cls = type(ma)
        return mapping_cls(tag=ma.tag, value=result)
    # Map from key string to its first key node and current value node
    key_node_map = {}
    value_map = {}
    order = []
    for item in nodes:
        try:
            k_node, v_node = item
        except Exception:
            continue  # skip invalid entries
        if not hasattr(k_node, "value"):
            continue
        key = k_node.value
        if key in value_map:
            value_map[key] = merge_nodes(value_map[key], v_node)
        else:
            value_map[key] = v_node
            key_node_map[key] = k_node
            order.append(key)
    # Build result list preserving original order of first occurrence
    result = [(key_node_map[key], value_map[key]) for key in order]
    return result

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a simple dictionary mapping option names to values. Supports:
        --name=value
        --name value
        -n value
    Positional arguments are numbered sequentially.
    '''
    args = {}
    it = iter(arguments)
    for arg in it:
        if arg.startswith('--'):
            if '=' in arg:
                key, value = arg[2:].split('=', 1)
            else:
                key = arg[2:]
                try:
                    value = next(it)
                except StopIteration:
                    # flag without value, interpret as True
                    value = True
        elif arg.startswith('-') and len(arg) > 1:
            key = arg[1:]
            try:
                value = next(it)
            except StopIteration:
                value = True
        else:
            # positional argument
            pos_key = f'pos{len([k for k in args if k.startswith("pos")])}'
            args[pos_key] = arg
            continue
        args[key] = value
    return args

