    if url_args is None:
        return url
    if not isinstance(url_args, dict) and not hasattr(url_args, "__getitem__"):
        raise TypeError("url_args must be a mapping type")
    import re
    pattern = re.compile(r'\{(\w+)\}')
    def replacement(match):
        key = match.group(1)
        try:
            return str(url_args[key])
        except Exception:
            return match.group(0)
    return pattern.sub(replacement, url)

def is_none_string(val: any) -> bool:
    """
    Check if a string represents a None value.

    Returns True if:
        - the argument itself is None
        - the argument is a string that when stripped and lowercased is one of
          {"", "none", "null", "nil", "na", "n/a"}.
    For any other value type or content, returns False.

    The function gracefully handles non-string inputs without raising exceptions.
    """
    try:
        if val is None:
            return True
        if not isinstance(val, str):
            return False
        cleaned = val.strip().lower()
        return cleaned in {"", "none", "null", "nil", "na", "n/a"}
    except Exception:
        # In case of unexpected errors, conservatively return False
        return False

