def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolution path
    call this function with a set that will store all the entries and
    the entry to test. If the entry is already in the set, report the issue
    and return ``True``. Otherwise, add the entry to the set and return
    ``False`` to allow the path to be processed.

    Args:
        processed: Set to store processed pathnames
        path_name: Path to a directory or file
        verbose: True if verbose output is requested

    Returns:
        True if it's already in the set. False if not.
    """
    # Validate inputs
    if not hasattr(processed, "add") or not hasattr(processed, "__contains__"):
        raise TypeError("processed must be a set-like object")
    if not isinstance(path_name, str) and path_name is not None:
        raise TypeError("path_name must be a string (or None)")

    # Ensure path_name is not None
    if path_name is None:
        if verbose:
            print("was_processed called with path_name=None")
        return False

    try:
        # Expand to absolute path; this may raise if os not available
        abs_path = os.path.abspath(path_name)
    except Exception as exc:
        if verbose:
            print(f"Error expanding path {path_name!r}: {exc}")
        return False

    try:
        if abs_path in processed:
            if verbose:
                print(f"Already processed: {abs_path}")
            return True
    except Exception as exc:
        if verbose:
            print(f"Error checking processed set for {abs_path}: {exc}")
        # If we can't check, assume not processed to allow mild recovery
        return False

    try:
        processed.add(abs_path)
    except Exception as exc:
        # If adding fails, we keep the set unchanged but indicate processed
        if verbose:
            print(f"Error adding {abs_path} to processed set: {exc}")
        # Return True to avoid reprocessing in case of failure
        return True

    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    try:
        if not isinstance(number, int):
            raise TypeError("number must be an integer")
        if number < 0:
            raise ValueError("number must be non-negative")
        if not isinstance(alphabet, (list, tuple)) or len(alphabet) < 2:
            raise ValueError("alphabet must be a list/tuple with at least two symbols")
        for sym in alphabet:
            if not isinstance(sym, str):
                raise TypeError("alphabet elements must be strings")

        base = len(alphabet)
        if number == 0:
            result = alphabet[0]
        else:
            digits = []
            n = number
            while n > 0:
                n, rem = divmod(n, base)
                digits.append(alphabet[rem])
            result = ''.join(reversed(digits))

        if padding is not None:
            if not isinstance(padding, int):
                raise TypeError("padding must be an integer or None")
            if padding < 0:
                raise ValueError("padding must be non-negative")
            if padding > len(result):
                result = alphabet[0] * (padding - len(result)) + result

        return result
    except Exception as e:
        raise e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    # Validate alphabet
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of single-character strings.")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct characters.")
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError("each element in alphabet must be a single-character string.")
    # Validate number
    if not isinstance(number, int):
        raise TypeError("number must be an integer.")
    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None.")
        if padding < 0:
            raise ValueError("padding must be non-negative.")
    # Handle zero
    if number == 0:
        result = alphabet[0]
        if padding is not None and len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
        return result
    # Handle sign
    sign = ""
    if number < 0:
        sign = "-"
        number = -number
    # Convert number to base
    digits = []
    try:
        while number > 0:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        converted = "".join(reversed(digits))
    except Exception as e:
        raise RuntimeError("Error during conversion") from e
    # Pad if needed
    if padding is not None and len(converted) < padding:
        converted = alphabet[0] * (padding - len(converted)) + converted
    return sign + converted

