def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: Updated dictionary with replacements applied
    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    # The register_value can be any hashable type, but if it is not hashable we cannot compare keys
    # We'll treat it as a string representation if necessary
    def replace(item):
        if isinstance(item, dict):
            new_dict = {}
            for k, v in item.items():
                # Replace key if it matches register_value
                new_key = register_number if k == register_value else k
                # Recursively replace in the value
                new_dict[new_key] = replace(v)
            return new_dict
        elif isinstance(item, list):
            return [replace(element) for element in item]
        elif item == register_value:
            return register_number
        else:
            return item

    # Perform replacement
    try:
        updated_flow = replace(flow_params)
    except Exception as exc:
        raise RuntimeError(f"Error while replacing register values: {exc}") from exc
    return updated_flow

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

