    if not isinstance(register_number, (int, str)):
        raise TypeError("register_number must be an int or string")

    def _recurse(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                new_key = register_number if k == register_value else k
                new_dict[new_key] = _recurse(v)
            return new_dict
        if isinstance(obj, list):
            return [_recurse(item) for item in obj]
