def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError("string must be a str instance.")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list instance.")
    if not alphabet:
        raise ValueError("alphabet must not be empty.")

    # Build mapping from symbol to its numeric value
    symbol_to_value = {}
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"Alphabet element at index {idx} is not a str.")
        if len(sym) != 1:
            raise ValueError(f"Alphabet element '{sym}' at index {idx} must be a single character.")
        if sym in symbol_to_value:
            raise ValueError(f"Duplicate symbol '{sym}' found in alphabet.")
        symbol_to_value[sym] = idx

    base = len(alphabet)

    # Empty string is considered invalid for this conversion
    if string == "":
        raise ValueError("input string must not be empty.")

    # Compute numeric value
    result = 0
    for pos, ch in enumerate(string):
        if ch not in symbol_to_value:
            raise ValueError(f"Character '{ch}' at position {pos} not found in alphabet.")
        result = result * base + symbol_to_value[ch]

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if alphabet is None:
        raise ValueError("alphabet must not be None")
