    if base == 0:
        raise ValueError("alphabet must contain at least one character")
    if string is None:
        raise ValueError("string must not be None")
    # Special handling for base-1 (unary) alphabets
    if base == 1:
        if any(ch != alphabet[0] for ch in string):
            raise ValueError("Invalid character for base-1 alphabet")
        return len(string)
    # Build a lookup dictionary for digit values
    try:
        val_map = {char: idx for idx, char in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError("failed to build digit mapping") from exc
    total = 0
    for ch in string:
        if ch not in val_map:
            raise ValueError(f"Invalid character '{ch}' for given alphabet")
        total = total * base + val_map[ch]
    return total

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
