    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct characters to represent a base >= 2.")

    # Ensure each alphabet entry is a single-character string
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"Alphabet entry #{idx} is not a single-character string: {ch!r}")

    # Create a mapping from character to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    # Edge case: empty string returns 0
    if string == "":
        return 0

    value = 0
    for position, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' at position {position} is not in the provided alphabet.")
        digit = char_to_value[ch]
        value = value * base + digit

