def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected string, got {type(s).__name__}")

    # Default to POSIX when platform is 'this' or unspecified
    if platform == 'this':
        platform = 1

    # Helper for POSIX splitting
    def _posix_split(cmd):
        # This regular expression matches double‑quoted strings, single‑quoted
        # strings, or sequences of non‑whitespace characters.
        token_re = re.compile(r'''
            "(?:\\.|[^"])*" |   # double quoted string
            '(?:\\.|[^'])*' |   # single quoted string
            [^\s]+              # unquoted
        ''', re.VERBOSE)
        tokens = token_re.findall(cmd)
        result = []
        for t in tokens:
            if t[0] in ("'", '"'):
                q = t[0]
                t = t[1:-1]
                # Handle escaped quotes inside the string
                t = t.replace(f'\\{q}', q)
            # Unescape backslashes
            t = t.replace('\\\\', '\\')
            result.append(t)
        return result

    # Helper for Windows cmd splitting
    def _windows_split(cmd):
        args = []
        cur = []
        i = 0
        length = len(cmd)
        while i < length:
            c = cmd[i]
            if c in (' ', '\t'):
                if cur:
                    args.append(''.join(cur))
                    cur = []
                i += 1
                continue
            if c == '"':
                # Count preceding backslashes
                bs_count = 0
                j = i - 1
                while j >= 0 and cmd[j] == '\\':
                    bs_count += 1
                    j -= 1
                if bs_count % 2 == 0:  # unescaped quote
                    i += 1
                    # consume quoted section
                    while i < length:
                        if cmd[i] == '"':
                            # Count backslashes before this quote
                            bs2 = 0
                            k = i-1
                            while k >=0 and cmd[k] == '\\':
                                bs2 += 1
                                k -=1
                            if bs2 % 2 == 0:
                                i += 1
                                break
                        if cmd[i] == '\\' and i+1 < length and cmd[i+1] == '\\':
                            cur.append('\\')
                            i += 2
                        else:
                            cur.append(cmd[i])
                            i += 1
                    continue
                else:
                    # Escaped quote: replace with a single quote
                    cur.append('"')
                    i += 1
                    continue
            else:
                cur.append(c)
                i += 1
        if cur:
            args.append(''.join(cur))
        return args

    if platform == 1:
        try:
            return _posix_split(s)
        except Exception as exc:
            raise ValueError(f"POSIX splitting failed: {exc}") from exc
    elif platform == 0:
        try:
            return _windows_split(s)
        except Exception as exc:
            raise ValueError(f"Windows splitting failed: {exc}") from exc
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Import modules locally to avoid polluting namespace
    try:
        from pathlib import Path
        import shutil
        import uuid
        import os
    except Exception as exc:
        raise RuntimeError(f"Failed to import required modules: {exc}") from exc

    # Validate archive_path
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive path does not exist or is not a file: {archive_path}")

    # Resolve tmp_path
    tmp_dir = Path(tmp_path)
    try:
        tmp_dir = tmp_dir.resolve()
    except Exception as exc:
        raise RuntimeError(f"Failed to resolve temporary path '{tmp_path}': {exc}") from exc

    if not tmp_dir.is_dir():
        # Try to create the temp directory if it doesn't exist
        try:
            tmp_dir.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            raise PermissionError(f"Cannot create temporary directory '{tmp_path}': {exc}") from exc

    # Ensure tmp_dir is writable
    if not os.access(tmp_dir, os.W_OK):
        raise PermissionError(f"Temporary directory '{tmp_path}' is not writable.")

    # Create a unique extraction directory
    extract_dir_name = f"repo_{uuid.uuid4().hex}"
    extract_dir = tmp_dir / extract_dir_name
    try:
        extract_dir.mkdir(parents=True, exist_ok=False)
    except Exception as exc:
        raise RuntimeError(f"Could not create extraction directory '{extract_dir}': {exc}") from exc

    # Unpack the archive
    try:
        shutil.unpack_archive(str(archive), str(extract_dir))
    except shutil.ReadError as exc:
        # Could be unsupported format or corrupted archive
        # Clean up partially extracted files
        try:
            shutil.rmtree(str(extract_dir))
        except Exception:
            pass
        raise ValueError(f"Failed to unpack archive '{archive_path}': unsupported format or corrupted file.") from exc
    except Exception as exc:
        # General extraction error
        try:
            shutil.rmtree(str(extract_dir))
        except Exception:
            pass
        raise RuntimeError(f"Failed to unpack archive '{archive_path}': {exc}") from exc

    # Determine repository root directory. If the archive produced a single top‑level folder,
    # use that folder as the repo root; otherwise use the extraction directory itself.
    try:
        entries = [p for p in extract_dir.iterdir() if p.is_dir() or p.is_file()]
        if len(entries) == 1 and entries[0].is_dir():
            repo_root = entries[0]
        else:
            repo_root = extract_dir
    except Exception as exc:
        # Cleanup on failure
        try:
            shutil.rmtree(str(extract_dir))
        except Exception:
            pass
        raise RuntimeError(f"Could not determine repository root: {exc}") from exc

    # Construct a file URL suitable for use as a git remote origin
    repo_url = f"file://{repo_root.resolve().as_posix()}"

    return repo_url

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    # Validate input
    import os
    import subprocess
    from pathlib import Path

    if not isinstance(archive_path, str):
        raise TypeError(f"archive_path must be a string, got {type(archive_path).__name__}")
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"No such archive: {archive_path}")

    # Determine temporary base directory
    tmp_dir = str(tmp_path)
    if not os.path.isdir(tmp_dir):
        try:
            os.makedirs(tmp_dir, exist_ok=True)
        except Exception as e:
            raise RuntimeError(f"Unable to create temporary directory '{tmp_dir}': {e}")

    # Derive extraction directory name
    base_name = os.path.basename(archive_path)
    if filename is None:
        # Strip common archive extensions
        for ext in (".tar.gz", ".tgz", ".tar.bz2", ".tar", ".zip"):
            if base_name.lower().endswith(ext):
                filename = base_name[: -len(ext)]
                break
        else:
            # Fallback: strip any extension
            filename = os.path.splitext(base_name)[0]
    dest_dir = os.path.abspath(os.path.join(tmp_dir, filename))

    # Remove if already exists to avoid stale data
    if os.path.isdir(dest_dir):
        import shutil
        try:
            shutil.rmtree(dest_dir)
        except Exception as e:
            raise RuntimeError(f"Unable to remove existing directory '{dest_dir}': {e}")

    os.makedirs(dest_dir, exist_ok=True)

    # Detect archive type and extract accordingly
    try:
        if base_name.lower().endswith(".zip"):
            cmd = ["unzip", "-q", "-o", archive_path, "-d", dest_dir]
        elif base_name.lower().endswith((".tar.gz", ".tgz", ".tar.bz2", ".tar")):
            # tar will auto-detect compression based on file name
            cmd = ["tar", "-xf", archive_path, "-C", dest_dir]
        else:
            raise ValueError(f"Unsupported archive format for file: {archive_path}")
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    except subprocess.CalledProcessError as e:
        # Clean up partial extraction
        if os.path.isdir(dest_dir):
            import shutil
            shutil.rmtree(dest_dir)
        error_msg = e.stderr.strip() if e.stderr else str(e)
        raise RuntimeError(f"Extraction failed for '{archive_path}': {error_msg}") from e
    except FileNotFoundError as e:
        # Dependencies like unzip or tar not available
        raise RuntimeError(f"Required tool missing for extraction: {e}") from e

    # Return a file URL to the extracted directory
    return f"file://{dest_dir}"

