            # IPv6 loopback
            elif family == socket.AF_INET6:
                # Normalize IPv6 address to canonical form
                if ip.lower() in ("::1", "0:0:0:0:0:0:0:1"):
                    return True
    except socket.gaierror:
        # Host could be an IP literal that failed to resolve via getaddrinfo
        pass
    except Exception:
        # Any unforeseen error results in False for safety
        return False

    # Fallback: directly check the string for loopback patterns
    # IPv4 literal
    if host.startswith("127.") and "." in host:
        # Basic validation of octets
        parts = host.split(".")
        if len(parts) == 4 and all(part.isdigit() and 0 <= int(part) <= 255 for part in parts):
            return True
    # IPv6 literal loopback
    if host.lower() == "::1":
        return True

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        if not host or not isinstance(host, str):
            return False
        h = host.strip()
        if h.lower() == "localhost" or h == "127.0.0.1" or h == "::1":
            return True
        # Resolve the host to IP addresses
        host_ips = []
        for res in socket.getaddrinfo(h, None):
            host_ips.append(res[4][0])
    except (socket.gaierror, ValueError):
        # Invalid host name or unresolved
        return False
    except Exception:
        return False

    try:
        # Get local machine IP addresses
        local_ips = set()
        for res in socket.getaddrinfo(socket.gethostname(), None):
            local_ips.add(res[4][0])
        # Include the standard loopback addresses explicitly
        local_ips.update({"127.0.0.1", "::1"})

        # Check for any overlap
        for ip in host_ips:
            if ip in local_ips:
                return True
        return False
    except Exception:
        # In case of any unexpected error while retrieving local addresses
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        return False
    host = host.strip()
    if not host:
        return False

    # Common localhost names and addresses
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1" or host == "::1":
        return True

    try:
        # Resolve all addresses for the given host
        infos = socket.getaddrinfo(host, None)
    except (socket.gaierror, ValueError):
        return False

    for info in infos:
        family, _, _, _, sockaddr = info
        try:
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127.") or ip == "127.0.0.1":
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0].split("%")[0]  # ignore zone index if present
                if ip == "::1":
                    return True
        except Exception:
            # Skip malformed socket info entries
            continue

    return False

