def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Git Bash runs under Windows, so os.name must be 'nt'
        if os.name != 'nt':
            return False
        # MSYSTEM is set in MINGW/Msys environments and indicates the subsystem
        msystem = os.getenv('MSYSTEM')
        if msystem:
            msystem = msystem.upper()
            if msystem in ('MINGW32', 'MINGW64', 'MSYS'):
                return True
        # Some Git Bash setups set OSTYPE to 'msys' regardless of MSYSTEM
        if os.getenv('OSTYPE', '').lower() == 'msys':
            return True
        # As a further fallback, check for a typical Bash shell path
        shell = os.getenv('SHELL', '').lower()
        if shell.endswith('bash'):
            return True
    except Exception:
        # In case of any unforeseen errors, default to False
        pass
    return False

def is_gitbash():
