def oneline(script, seperator=" && "):
    try:
        if not isinstance(script, str):
            raise TypeError("script must be a string")
        lines = script.splitlines()
        cleaned = []
        for line in lines:
            stripped = line.strip()
            if not stripped:
                continue
            cleaned.append(stripped)
        return seperator.join(cleaned) if cleaned else ""
    except Exception as e:
        raise RuntimeError(f"Error converting script to one line: {e}") from e

