            var_name = matcher.group(1)
            default = matcher.group(2) if matcher.lastindex and matcher.lastindex >= 2 else None
    except Exception as exc:
        raise ValueError("Matcher does not provide a suitable interface to extract environment variable name and default.") from exc

    if not isinstance(var_name, str) or not var_name:
