def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    If strip is True, leading and trailing whitespace is removed.
    Supports glob-style wildcards: '*' is replaced with '.*' and
    '?' is replaced with '.'.
    Returns a compiled re.Pattern object.
    Raises:
        TypeError: if pattern is not a string.
        ValueError: if the resulting regex is invalid.
    """
    if pattern is None:
        raise TypeError("pattern must be a string, not None")
