            escaped_parts.append(re.escape(ch))
    regex = '^' + ''.join(escaped_parts) + '$'
    try:
        return re.compile(regex)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern generated from '{pattern}': {exc}") from exc

