def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd_parts = [commands]
    else:
        try:
            cmd_parts = list(commands)
        except TypeError:
            raise ValueError("commands must be a string or an iterable of strings")
    # Append additional arguments if provided
    if args:
        if isinstance(args, str):
            cmd_parts.append(args)
        else:
            try:
                cmd_parts.extend(map(str, args))
            except TypeError:
                raise ValueError("args must be a string or an iterable of strings")
    # Prepare subprocess parameters
    stdout_pipe = subprocess.PIPE
    stderr_pipe = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        result = subprocess.run(
            cmd_parts,
            cwd=cwd,
            env=env,
            stdout=stdout_pipe,
            stderr=stderr_pipe,
            text=True,
            check=True
        )
        if verbose:
            print(f"Command succeeded: {' '.join(cmd_parts)}")
            if result.stdout:
                print(result.stdout.rstrip())
        return result
    except subprocess.CalledProcessError as e:
        if verbose or (e.stdout is None and e.stderr is None):
            print(f"Command failed: {' '.join(cmd_parts)}")
            if e.stdout:
                print("STDOUT:")
                print(e.stdout.rstrip())
            if e.stderr:
                print("STDERR:")
                print(e.stderr.rstrip())
        raise
    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {cmd_parts[0]}")
    except Exception as exc:
        raise RuntimeError(f"An error occurred while running command {' '.join(cmd_parts)}: {exc}")

