        if not isinstance(shape, (tuple, list)):
            raise TypeError(f"shape must be a tuple or list, got {type(shape).__name__}")
        if not shape:  # empty shape allowed but may reflect scalar
            shape = ()
        for dim in shape:
            if not isinstance(dim, int):
                raise TypeError(f"Shape dimensions must be integers, got {dim!r} of type {type(dim).__name__}")
            if dim < 0:
