def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        arr = np.array(x, dtype=float)
    except Exception as exc:
        raise TypeError("Input must be a numeric value or an array-like of numeric values.") from exc
    mu, sigma = 0.2, 0.1
    return np.exp(-((arr - mu)**2) / (2 * sigma**2))

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x)
        mu = 0.2
        sigma = 0.1
        factor = 1.0 / (sigma * np.sqrt(2 * np.pi))
        exponent = -((x_arr - mu) ** 2) / (2 * sigma ** 2)
        return factor * np.exp(exponent)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Invalid input for gaussian function: {exc}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
    - dict of configuration filename to corresponding parsed configuration,
    - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import logging
    import os
    import re

    # Validate inputs
    if not isinstance(config_filenames, (list, tuple)):
        raise TypeError("config_filenames must be a list or tuple of filenames")
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dict or None")
    if not isinstance(resolve_env, bool):
        raise TypeError("resolve_env must be a boolean")

    config_map = {}
    error_records = []
    logger_name = __name__ if __name__ else 'load_configurations'

    def _make_error_record(filename, exc):
        # Create a LogRecord with error level
        exc_tuple = (type(exc), exc, exc.__traceback__)
        return logging.LogRecord(
            logger_name, logging.ERROR,
            pathname=filename, lineno=0,
            msg=f"Error processing {filename}: {exc}",
            args=None, exc_info=exc_tuple
        )

    def _resolve_env_vars(obj):
        """
        Recursively resolve environment variable placeholders in the form ${VAR}
        """
        if isinstance(obj, str):
            # Replace all ${VAR} with value from environment
            def replacer(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return re.sub(r'\$\{([^}]+)\}', replacer, obj)
        elif isinstance(obj, dict):
            return {k: _resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_vars(item) for item in obj]
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if resolve_env:
                data = _resolve_env_vars(data)
            config_map[filename] = data
        except FileNotFoundError as e:
            error_records.append(_make_error_record(filename, e))
        except json.JSONDecodeError as e:
            error_records.append(_make_error_record(filename, e))
        except Exception as e:
            error_records.append(_make_error_record(filename, e))

    # Apply overrides if provided
    if overrides:
        for filename, cfg in config_map.items():
            if isinstance(cfg, dict):
                cfg.update(overrides)
            else:
                # If config is not a dict, skip override and log warning
                warning_msg = f"Overrides ignored for {filename} because config is not a dict"
                warning_record = logging.LogRecord(
                    logger_name, logging.WARNING,
                    pathname=filename, lineno=0,
                    msg=warning_msg,
                    args=None, exc_info=None
                )
                error_records.append(warning_record)

    return config_map, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import re
    import logging
    try:
        import yaml
    except Exception:
        yaml = None

    def _deep_merge(target, source):
        for key, val in source.items():
            if key in target and isinstance(target[key], dict) and isinstance(val, dict):
                _deep_merge(target[key], val)
            else:
                target[key] = val

    env_pattern = re.compile(r'\$\{([^}:\s]+)(?::([^}]*))?\}')

    def _resolve_value(value):
        if isinstance(value, str):
            def _replace(match):
                var, default = match.group(1), match.group(2)
                return os.getenv(var, default if default is not None else '')
            return env_pattern.sub(_replace, value)
        elif isinstance(value, dict):
            return {k: _resolve_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_value(v) for v in value]
        else:
            return value

    parsed_configs = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fp:
                if filename.lower().endswith(('.yaml', '.yml')):
                    if yaml is None:
                        raise RuntimeError('pyyaml library is required for YAML files')
                    loaded = yaml.safe_load(fp)
                elif filename.lower().endswith('.json'):
                    loaded = json.load(fp)
                else:
                    raise ValueError('Unsupported configuration file type')
                if not isinstance(loaded, dict):
                    raise ValueError('Configuration must be a dictionary')
                # Apply overrides if provided
                if overrides and filename in overrides:
                    if not isinstance(overrides[filename], dict):
                        raise ValueError('Override for {} must be a dictionary'.format(filename))
                    _deep_merge(loaded, overrides[filename])
                if resolve_env:
                    loaded = _resolve_value(loaded)
                parsed_configs[filename] = loaded
        except Exception as exc:
            record = logging.LogRecord(__name__, logging.ERROR, filename, 0,
                                       f"Error loading configuration '{filename}': {exc}", None, None)
            error_records.append(record)

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    # Helper to resolve environment variables in a dict/list/string structure
    def _resolve_env_in_obj(obj):
        try:
            env = __import__('os').environ
        except Exception:
            env = {}
        # Use a simple regex to find ${VAR} placeholders
        try:
            re_mod = __import__('re')
        except Exception:
            re_mod = None
        if re_mod:
            pattern = re_mod.compile(r'\$\{([^}]+)\}')
            def replace(match):
                var_name = match.group(1)
                return env.get(var_name, '')
            def _deep_resolve(o):
                if isinstance(o, dict):
                    return {k: _deep_resolve(v) for k, v in o.items()}
                elif isinstance(o, list):
                    return [_deep_resolve(i) for i in o]
                elif isinstance(o, str):
                    return re_mod.sub(replace, o)
                else:
                    return o
            return _deep_resolve(obj)
        else:
            # Fallback: return original object if regex unavailable
            return obj

    # Ensure config_filenames is iterable
    if isinstance(config_filenames, str):
        config_filenames = [config_filenames]

    if not hasattr(config_filenames, '__iter__'):
        raise TypeError("config_filenames must be an iterable of file paths")

    if overrides is not None and not isinstance(overrides, dict):
        # Overrides must be a dict; log a warning record but continue
        record = logging.LogRecord('load_configurations', logging.WARNING, __file__, 0,
                                   f"Overrides argument is not a dict: {type(overrides).__name__}", None, None)
        # just ignore overrides
        overrides = None

    # Prepare results
    parsed_configurations = {}
    error_records = []

    for filename in config_filenames:
        try:
            if not isinstance(filename, str):
                raise ValueError(f"Filename must be a string, got {type(filename).__name__}")

            # Check file existence
            os_mod = __import__('os')
            if not os_mod.path.isfile(filename):
                record = logging.LogRecord('load_configurations', logging.ERROR, filename, 0,
                                           f"Configuration file not found: {filename}", None, None)
                error_records.append(record)
                continue

            # Read file content
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()

            # Attempt to parse JSON first, then YAML
            parsed = None
            try:
                json_mod = __import__('json')
                parsed = json_mod.loads(content)
            except Exception:
                try:
                    yaml_mod = __import__('yaml')
                    parsed = yaml_mod.safe_load(content)
                except Exception as ye:
                    record = logging.LogRecord('load_configurations', logging.ERROR, filename, 0,
                                               f"Failed to parse file {filename}: {ye}", None, None)
                    error_records.append(record)
                    continue

            if not isinstance(parsed, dict):
                record = logging.LogRecord('load_configurations', logging.ERROR, filename, 0,
                                           f"Parsed configuration is not a dictionary: {filename}", None, None)
                error_records.append(record)
                continue

            # Apply overrides if provided
            if overrides:
                parsed.update(overrides)

            # Resolve environment variables if requested
            if resolve_env:
                parsed = _resolve_env_in_obj(parsed)

            parsed_configurations[filename] = parsed

        except Exception as e:
            record = logging.LogRecord('load_configurations', logging.ERROR, filename, 0,
                                       f"Unexpected error processing {filename}: {e}", None, None)
            error_records.append(record)

    return parsed_configurations, error_records

