@classmethod
def from_ticks(cls, ticks, tz=None):
    """
    Create a Time instance from the number of nanoseconds since midnight.
    """
    # Validate input type
    try:
        ticks = int(ticks)
    except (TypeError, ValueError):
        raise TypeError("ticks must be an integer representing nanoseconds since midnight")

    # Check bounds
    MAX_TICKS = 86400 * 10**9  # 24 hours in nanoseconds
    if ticks < 0 or ticks >= MAX_TICKS:
        raise ValueError("ticks must be in the range [0, 86400000000000)")

    # Convert ticks into conventional time components
    ns_per_sec = 1_000_000_000
    total_secs, ns_rem = divmod(ticks, ns_per_sec)

    mins, secs = divmod(total_secs, 60)
    hrs, mins = divmod(mins, 60)

    microsecs, nanos = divmod(ns_rem, 1_000)

    # Attempt to instantiate Time with the full component set.
    # Some implementations may not expect a nanosecond argument, so we
    # provide a graceful fallback.
    try:
        return cls(hrs, mins, secs, microseconds=microsecs, nanoseconds=nanos, tzinfo=tz)
    except TypeError:
        # Fallback: try without nanoseconds
        try:
            return cls(hrs, mins, secs, microseconds=microsecs, tzinfo=tz)
        except Exception as exc:
            # If construction still fails, surface a clear error
            raise RuntimeError(
                f"Failed to create Time instance from ticks: {exc}"
            ) from exc

