    """
    Create a Bookmarks object from a list of raw bookmark string values.

    :param values: Iterable of ASCII string values (raw bookmarks).
    :return: An instance of the class.
    """
    # Allow an empty or None input to produce an empty Bookmarks instance
    if values is None:
        values = []
    # Ensure the supplied argument is iterable
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("The 'values' argument must be an iterable of strings") from None

    cleaned = []
    for raw in values:
        if not isinstance(raw, str):
            raise TypeError(f"Bookmark values must be str, got {type(raw).__name__}")
        # Strip whitespace and skip empty strings
        stripped = raw.strip()
        if stripped:
            cleaned.append(stripped)

    # Preserve original order while removing duplicates
    unique_values = list(dict.fromkeys(cleaned))

    # Instantiate the Bookmarks object with the cleaned, unique values.
    # It is assumed that the class constructor accepts an iterable of strings.
    try:
        return cls(unique_values)
    except Exception as exc:
        raise ValueError(f"Failed to create {cls.__name__} from raw values: {exc}") from exc

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: Bookmarks instance populated with parsed bookmarks
    :raises TypeError: if values is not iterable or contains non-string entries
    :raises ValueError: if a raw string cannot be parsed into a bookmark
    """
    if values is None:
        raise TypeError("values must be an iterable of strings")

    instance = cls()

    for v in values:
        if not isinstance(v, str):
            raise TypeError(f"Expected string bookmark values, got {type(v).__name__}")

        try:
            bookmark = Bookmark.from_raw(v)
        except Exception as exc:
            raise ValueError(f"Failed to parse raw bookmark value {repr(v)}: {exc}") from exc

        if hasattr(instance, "add"):
            instance.add(bookmark)
        elif hasattr(instance, "append"):
            instance.append(bookmark)
        else:
            try:
                getattr(instance, "_bookmarks").append(bookmark)
            except Exception:
                if not hasattr(instance, "bookmarks"):
                    instance.bookmarks = []
                instance.bookmarks.append(bookmark)

    return instance

@classmethod
