        processed.append(val.strip())

    # Instantiate the class with the processed list
    try:
        return cls(processed)
    except Exception as exc:
        raise RuntimeError(f"Failed to construct {cls.__name__} from raw values: {exc}") from exc

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    try:
        # Strings and bytes are considered sequences, return as-is
        if isinstance(seq, (str, bytes, bytearray)):
            return seq, type(seq)
        # Check for generic sequence types
        try:
            from collections.abc import Sequence as _Sequence
        except Exception:
            _Sequence = None
        if _Sequence and isinstance(seq, _Sequence):
            return seq, type(seq)
        # If not a sequence, materialize into a list
        if bufsize is None:
            seq_obj = list(seq)
        else:
            import itertools
            seq_obj = list(itertools.islice(seq, bufsize))
    except Exception as exc:
        msg = f"Failed to convert {seq!r} to a sequence: {exc}"
        raise ValueError(msg) from exc
    return seq_obj, type(seq_obj)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    try:
        # Handle None explicitly
        if seq is None:
            seq_val = ()
        else:
            # If seq is a built‑in sequence type, use it directly
            if isinstance(seq, (list, tuple, str, bytes, bytearray)):
                seq_val = seq
            # Otherwise, try to iterate over seq
            elif hasattr(seq, '__iter__') and not isinstance(seq, (str, bytes, bytearray)):
                # If a bufsize is given, use it to limit the produced sequence
                if bufsize is not None and isinstance(bufsize, int) and bufsize > 0:
                    it = iter(seq)
                    seq_list = []
                    for _ in range(bufsize):
                        try:
                            seq_list.append(next(it))
                        except StopIteration:
                            break
                    seq_val = seq_list
                else:
                    seq_val = list(seq)
            else:
                # Fall back to a one‑element tuple
                seq_val = (seq,)
        seq_type = type(seq_val)
        return seq_val, seq_type
    except Exception:
        # In case of any unexpected error, return a safe default
        return None, None

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    try:
        seq_type = type(seq)
        # Determine if seq is a "sequence type" suitably interpreted
        # Treat built‑in sequences and string/bytes/bytearray as sequences
        seq_is_seq = False
        if isinstance(seq, (str, bytes, bytearray)):
            seq_is_seq = True
        else:
            # Heuristic: if it has both __len__ and __getitem__ and is not a mapping
            if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
                # Exclude mapping types like dict
                if not isinstance(seq, dict):
                    seq_is_seq = True
        if seq_is_seq:
            return seq, seq_type
        # Otherwise, derive a list from the iterable
        derived = list(seq)
        if bufsize is not None:
            # Chunk the list into sublists of at most bufsize elements
            derived = [derived[i:i + bufsize] for i in range(0, len(derived), bufsize)]
        return derived, seq_type
    except Exception as exc:
        raise ValueError(f"Unable to derive sequence from {seq!r}") from exc

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Handle None explicitly
    if seq is None:
        return ([], None)

    # Determine if the input is already a sequence type
    try:
        from collections.abc import Sequence  # noqa: F401
    except Exception:
        # Fallback: treat known built-in sequences
        Sequence = (list, tuple, str, bytes, bytearray)

    if isinstance(seq, Sequence):
        # For a true sequence, return it unchanged along with its type
        return (seq, type(seq))

    # For non-sequence iterables, materialise into a list
    try:
        if bufsize is not None:
            # Lazily slice up to bufsize elements if possible
            from itertools import islice  # noqa: F401
            seq_items = list(islice(seq, bufsize))
        else:
            seq_items = list(seq)
    except TypeError as exc:
        # seq must be iterable; otherwise raise a clear error
        raise TypeError("Provided 'seq' is not iterable") from exc

    return (seq_items, type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("seq cannot be None")
    original_type = type(seq)

    # Treat objects that are already typical sequences as-is.
    if isinstance(seq, (list, tuple, str, bytes)):
        return seq, original_type

    # For any other iterable, convert to a list (optionally limiting size with bufsize).
    try:
        if bufsize is None:
            seq = list(seq)
        else:
            import itertools
            seq = list(itertools.islice(seq, bufsize))
    except TypeError as exc:
        raise TypeError("Provided object is not iterable") from exc
    except Exception as exc:
        raise RuntimeError("Error converting sequence") from exc

    return seq, original_type

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Sanity checks for the `recompute` flag
    if not isinstance(recompute, bool):
        raise ValueError("`recompute` must be a boolean")

    # Helper to actually compute the integral (scale) of the histogram.
    def _compute_scale():
        # Obtain the bin content array; try common attribute names.
        if hasattr(self, "values"):
            counts = self.values
        elif hasattr(self, "data"):
            counts = self.data
        else:
            raise AttributeError("Histogram instance lacks count data")

        # Determine bin widths if possible.
        widths = None
        if hasattr(self, "edges"):
            edges = self.edges
            if len(edges) < 2:
                raise ValueError("Histogram edges must define at least one bin")
            widths = [edges[i + 1] - edges[i] for i in range(len(edges) - 1)]

        # Compute the integral as sum(contents * widths) or just sum(contents)
        if widths is not None and len(counts) == len(widths):
            try:
                integral = float(sum(c * w for c, w in zip(counts, widths)))
            except Exception as exc:
                raise RuntimeError(f"Error computing integral: {exc}") from exc
        else:
            try:
                integral = float(sum(counts))
            except Exception as exc:
                raise RuntimeError(f"Error computing sum of counts: {exc}") from exc

        # Store and return the result
        self._scale = integral
        return integral

    # If no `other` value was supplied, return (or compute) the current scale.
    if other is None:
        if not hasattr(self, "_scale") or recompute:
            _compute_scale()
        return getattr(self, "_scale", 0.0)

    # `other` was supplied: rescale the histogram.
    if not isinstance(other, (int, float)):
        raise TypeError("`other` must be a numeric value representing the desired scale")

    # Ensure we have the current scale value
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or recompute:
        current_scale = _compute_scale()

    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    # Calculate scaling factor and apply it to all bins.
    factor = other / current_scale
    if hasattr(self, "values"):
        counts = self.values
    elif hasattr(self, "data"):
        counts = self.data
    else:
        raise AttributeError("Histogram instance lacks count data")

    try:
        for i in range(len(counts)):
            counts[i] *= factor
    except Exception as exc:
        raise RuntimeError(f"Error applying scaling factor: {exc}") from exc

    # Update stored scale to match the new desired value.
    self._scale = float(other)   # Preserve float semantics
    return None

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored
    for subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must
    explicitly recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # ----------------------- Helper to get histogram data -----------------------
    def _get_data_attr():
        for name in ("_data", "data", "bins", "counts"):
            if hasattr(self, name):
                return getattr(self, name)
        raise AttributeError(
            "Histogram object does not contain a recognizable data attribute."
        )

    # ----------------------- Getter (no *other*) -------------------------------
    if other is None:
        # Recompute when requested or when no scale stored
        current_scale = getattr(self, "_scale", None)
        if recompute or current_scale is None:
            try:
                data = _get_data_attr()
                # Sum over the data to obtain the integral
                current_scale = float(sum(data))
                setattr(self, "_scale", current_scale)
            except Exception as exc:
                raise ValueError("Failed to compute histogram scale.") from exc
        return current_scale

    # ----------------------- Rescaling (other given) -----------------------------
    if not isinstance(other, (int, float)):
        raise TypeError("Target scale must be a numeric value.")
    if not hasattr(self, "_scale") or getattr(self, "_scale") == 0:
        raise ValueError(
            "Cannot rescale a histogram with an undefined or zero scale."
        )
    try:
        data = _get_data_attr()
        factor = float(other) / float(getattr(self, "_scale"))
        # Multiply all bins by the factor
        for i in range(len(data)):
            data[i] *= factor
        setattr(self, "_scale", float(other))
    except Exception as exc:
        raise ValueError("Failed to rescale histogram.") from exc
    # Chaining is allowed; return self
    return self

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Validate *other* type
    if other is not None and not isinstance(other, (int, float)):
        raise TypeError("other must be a float, int, or None")

    # Helper to obtain the data array
    def _get_data():
        if hasattr(self, "values"):
            return self.values
        elif hasattr(self, "bins"):
            return self.bins
        elif hasattr(self, "data"):
            return self.data
        else:
            raise AttributeError(
                "Histogram instance does not expose an array-like 'values'/"
                "'bins'/or 'data' attribute required for scale calculation."
            )

    # Compute integral if necessary
    if other is None:
        if getattr(self, "scale", None) is None or recompute:
            data = _get_data()
            try:
                # Use built‑in sum which works for lists, tuples and numpy arrays
                self.scale = sum(float(v) for v in data)
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to compute scale from histogram data: {exc}"
                ) from exc
        return self.scale

    # Rescaling requested
    if getattr(self, "scale", None) is None:
        # Lazily compute current scale if not already computed
        self.scale()
        if getattr(self, "scale", None) is None:
            raise RuntimeError("Unable to determine current scale for rescaling.")

    if self.scale == 0:
        raise LenaValueError(
            "Cannot rescale histogram with zero integral (scale)."
        )

    factor = float(other) / float(self.scale)
    data = _get_data()
    try:
        # Preserve original type when possible
        if isinstance(data, list):
            self.values = [v * factor for v in data]
        else:
            # For numpy arrays or other array-like objects
            self.values = data * factor
    except Exception as exc:
        raise RuntimeError(
            f"Failed to rescale histogram data: {exc}"
        ) from exc

    self.scale = float(other)
    return self.scale

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).  Note that after changing (filling) the
    histogram one must explicitly recompute the scale if it was computed before.
    If a float *other* is provided, rescale self to *other*.
    Histograms with scale equal to zero can't be rescaled; a :exc:`.LenaValueError`
    is raised in that case.
    """
    # ======== Retrieve or compute the current scale ========
    if other is None:
        if not recompute and hasattr(self, "_scale"):
            return self._scale
        # Compute the integral of the histogram
        try:
            total = float(self.integral())
        except Exception:
            # Fallback: manually sum over bins if integral() is unavailable
            total = 0.0
            if hasattr(self, "_bins"):
                for val in self._bins:
                    total += val
            elif hasattr(self, "_contents"):
                for val in self._contents:
                    total += val
        self._scale = total
        return self._scale

    # ======== Rescale the histogram to the requested target ========
    if not isinstance(other, (int, float)):
        raise TypeError("Target scale must be a numeric value (int or float).")

    # Ensure we have the current scale; recompute if requested
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or recompute:
        current_scale = self.scale(recompute=True)
    else:
        current_scale = self._scale

    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale.")

    factor = other / current_scale

    # Scale all bin contents; use the most common attribute names if available
    if hasattr(self, "_bins"):
        for i in range(len(self._bins)):
            self._bins[i] *= factor
    if hasattr(self, "_contents"):
        for i in range(len(self._contents)):
            self._contents[i] *= factor
    # Also scale errors if the histogram keeps them
    if hasattr(self, "_errors"):
        for i in range(len(self._errors)):
            self._errors[i] *= factor

    self._scale = other
    return self

def scale(self, other=None):
        """
        Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return current scale if no new scale is provided
        if other is None:
            return getattr(self, "_scale", None)

        # Validate new scale is a numeric value
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value")

        # Retrieve the current scale; raise error if unknown or zero
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or current_scale == 0:
            # Try to import the custom exception, fallback to ValueError otherwise
            try:
                raise LenaValueError(
                    "Cannot rescale graph with unknown or zero current scale."
                )
            except NameError:
                raise ValueError(
                    "Cannot rescale graph with unknown or zero current scale."
                )

        # Compute scaling factor
        factor = other / current_scale

        # Identify the last coordinate field (assuming fields are stored in order)
        fields = getattr(self, "_fields", [])
        if not fields:
            raise ValueError("Graph has no coordinate fields to scale")
        last_field = fields[-1]

        # Rescale the data for the last coordinate
        if hasattr(self, "_data") and last_field in self._data:
            coord_data = self._data[last_field]
            if isinstance(coord_data, (list, tuple)):
                for arr in coord_data:
                    arr *= factor
            else:
                coord_data *= factor

        # Rescale any associated errors for the last coordinate
        if hasattr(self, "_errors") and last_field in self._errors:
            error_data = self._errors[last_field]
            if isinstance(error_data, (list, tuple)):
                for err_arr in error_data:
                    err_arr *= factor
            else:
                error_data *= factor

        # Update the stored scale
        self._scale = other
        return None

def scale(self, other=None):
    """Get or set the scale of the graph."""
    # Get current scale
    current_scale = getattr(self, 'scale', None)
    if other is None:
        return current_scale

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")
    if current_scale is None or current_scale == 0:
        raise ValueError("Cannot rescale graph with unknown or zero current scale")

    factor = other / current_scale

    # Determine the last field to rescale
    fields = getattr(self, 'fields', None)
    data = getattr(self, 'data', {})
    errors = getattr(self, 'errors', {})

    if isinstance(fields, (list, tuple)):
        if not fields:
            raise RuntimeError("No fields available to rescale")
        last_field = fields[-1]
    else:
        # Fallback: infer from data keys
        field_keys = [k for k in data if isinstance(data[k], (list, tuple))]
        if not field_keys:
            raise RuntimeError("No data fields available to rescale")
        last_field = field_keys[-1]

    # Rescale the data of the last field
    if isinstance(data, dict) and last_field in data:
        original = data[last_field]
        try:
            data[last_field] = [v * factor for v in original]
        except Exception:
            # Preserve original data if scaling fails
            raise RuntimeError(f"Failed to rescale data for field '{last_field}'")

    # Rescale the errors associated with the last field
    if isinstance(errors, dict) and last_field in errors:
        original_err = errors[last_field]
        try:
            errors[last_field] = [e * factor for e in original_err]
        except Exception:
            raise RuntimeError(f"Failed to rescale errors for field '{last_field}'")

    # Update the graph's stored scale
    self.scale = other
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a list of graph points."""
    # Basic validation
    if make_value is None:
        make_value = lambda v: v
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be one of 'left', 'right', 'middle'")
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a sequence of strings")
    if len(field_names) < 2:
        raise ValueError("field_names must contain at least two names")

    # Try to get the histogram edges and bin values
    try:
        if hasattr(hist, "edges") and hasattr(hist, "values"):
            edges = hist.edges
            values = hist.values
        elif hasattr(hist, "bin_edges") and hasattr(hist, "bin_contents"):
            edges = hist.bin_edges
            values = hist.bin_contents
        elif hasattr(hist, "__len__") and hasattr(hist, "__getitem__"):
            # Assume hist is a 1‑D iterable of bin objects with left/right/content
            edges = []
            values = []
            for bin_obj in hist:
                if getattr(bin_obj, "left", None) is None:
                    raise AttributeError
                edges.append(bin_obj.left)
                edges.append(bin_obj.right)
                values.append(bin_obj.content)
            # The above will add each right edge twice; remove duplicates
            edges = sorted(set(edges))
        else:
            raise AttributeError
    except Exception as e:
        raise ValueError("Could not extract histogram structure: %s" % e)

    # Check consistency
    if len(edges) != len(values) + 1:
        raise ValueError("Histogram edges length must be one greater than number of bins")

    points = []
    for i, val in enumerate(values):
        # Determine x coordinate
        if get_coordinate == "left":
            x = edges[i]
        elif get_coordinate == "right":
            x = edges[i + 1]
        else:  # middle
            x = (edges[i] + edges[i + 1]) / 2

        # Calculate y (or y and error)
        try:
            y = make_value(val)
        except Exception as e:
            raise ValueError(f"make_value raised an exception for bin content {val!r}: {e}")

        # Normalize y to a tuple
        if not isinstance(y, tuple):
            y = (y,)

        if len(y) != len(field_names) - 1:
            raise ValueError("make_value returned wrong number of values; expected "
                             f"{len(field_names) - 1}, got {len(y)}")

        point = (x,) + y
        points.append(point)

    # Apply scale if requested
    if scale is True:
        # Attempt to fetch scale from histogram; otherwise ignore
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    # Return a simple representation: list of tuples and optional scale metadata
    # If the caller expects a more complex graph object, they can adapt this data.
    return {"points": points, "field_names": field_names, "scale": scale_val}

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Helper to get bins from the histogram
    try:
        bins = hist.bins
    except AttributeError:
        try:
            bins = list(hist)
        except Exception:
            raise ValueError("`hist` must provide a 'bins' attribute or be iterable")

    if make_value is None:
        make_value = lambda v: v

    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("`get_coordinate` must be 'left', 'right', or 'middle'")

    coord_funcs = {
        "left":   lambda b: getattr(b, "left",   getattr(b, "GetXlow",  None)),
        "right":  lambda b: getattr(b, "right",  getattr(b, "GetXup",   None)),
        "middle": lambda b: getattr(b, "center", getattr(b, "GetXcenter", None)),
    }
    coord_func = coord_funcs[get_coordinate]

    # Handle scale
    if scale is True:
        try:
            scale = getattr(hist, "scale", None)
        except Exception:
            scale = None

    # Result container
    points = []

    for bin_obj in bins:
        # Get coordinate
        coord = coord_func(bin_obj)
        if coord is None:
            raise ValueError("Unable to determine coordinate from bin: missing attribute")
        # Get bin content (allow numeric or object with .content)
        try:
            content = getattr(bin_obj, "content", bin_obj)
        except Exception:
            content = bin_obj
        try:
            values = make_value(content)
        except Exception as exc:
            raise ValueError(f"Error applying make_value: {exc}") from exc
        # Ensure values is iterable
        if isinstance(values, (list, tuple)):
            values_iter = list(values)
        else:
            values_iter = [values]
        # Combine coordinate and values
        if len(values_iter) != len(field_names) - 1:
            raise ValueError(f"Expected {len(field_names)-1} values from make_value, got {len(values_iter)}")
        point = (coord,) + tuple(values_iter)
        points.append(point)

    # Simple graph representation
    class Graph:
        __slots__ = ("field_names", "points", "scale")
        def __init__(self, field_names, points, scale):
            self.field_names = tuple(field_names)
            self.points = tuple(points)
            self.scale = scale
        def __iter__(self):
            return iter(self.points)
        def __len__(self):
            return len(self.points)
        def __getitem__(self, idx):
            return self.points[idx]
        def __repr__(self):
            return f"<Graph fields={self.field_names} points={len(self.points)} scale={self.scale!r}>"

    return Graph(field_names, points, scale)

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the interface
      using ``iface.providedBy`` (unless *tentative* is ``True``).
    - Making sure the candidate defines all the necessary methods
    - Making sure the methods have the correct signature (to the
      extent possible)
    - Making sure the candidate defines all the necessary attributes
    """
    errors = []

    # 1.  Check that the candidate claims to provide the interface.
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"{candidate!r} does not provide {iface.__name__}")
        except Exception as exc:
            # ``iface.providedBy`` may raise, propagate that.
            raise

    # 2.  Loop through interface members and validate against the candidate.
    #     we ignore internal attributes and some built‑in helpers.
    excluded = {
        "module", "__module__", "qualname", "__qualname__", "__doc__",
        "providedBy", "conforms", "required", "provides", "factory",
        "is_callable", "is_attribute", "methods", "attributes",
    }

    import inspect

    for name, iface_val in iface.__dict__.items():
        if name in excluded or name.startswith("_"):
            continue

        # Does the candidate even have this member?
        if not hasattr(candidate, name):
            errors.append(f"missing member {name!r}")
            continue

        cand_val = getattr(candidate, name)

        # If the interface member is callable, it must be a method.
        if callable(iface_val):
            if not callable(cand_val):
                errors.append(f"{name!r} is not callable")
                continue

            # 3.  Signature check – we compare parameters only.
            try:
                sig_iface = inspect.signature(iface_val)
                sig_cand = inspect.signature(cand_val)
                if sig_iface.parameters != sig_cand.parameters:
                    errors.append(f"signature mismatch for {name!r}")
            except Exception:
                # If inspection fails, skip signature validation.
                pass
        else:
            # 4.  For non-callable interface members we simply check existence.
            #    Type or value checks are outside the scope of this stub.
            pass

    # 5.  Raise a collective error or succeed.
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        raise zope.interface.Invalid("; ".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Imports used only inside the function to keep module free of top-level imports
    from zope.interface import Invalid
    import inspect
    errors = []

    # Check interface provision
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                msg = f"{candidate!r} does not claim to provide {iface!r}"
                errors.append(msg)
        except Exception as exc:
            errors.append(f"Error checking providedBy: {exc!r}")

    # Optional type check
    if vtype is not None:
        if not isinstance(candidate, vtype):
            errors.append(f"{candidate!r} is not an instance of {vtype!r}")

    # Helper to compare signatures (basic check)
    def _signatures_match(required_sig, candidate_sig):
        try:
            req_params = list(required_sig.parameters.values())
            cand_params = list(candidate_sig.parameters.values())
            if len(req_params) != len(cand_params):
                return False
            for rp, cp in zip(req_params, cand_params):
                if rp.name != cp.name or rp.kind != cp.kind:
                    return False
            return True
        except Exception:
            return False

    # Check required methods
    try:
        required_methods = [sig for sig in iface.methods]
    except Exception:
        required_methods = []

    for req in required_methods:
        name = getattr(req, 'name', None)
        if name is None:
            continue  # skip non-name signatures
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue
        attr = getattr(candidate, name)
        if not callable(attr):
            errors.append(f"Attribute '{name}' is not callable")
            continue
        # Check signature if possible
        required_signature_str = getattr(req, 'signature', None)
        if required_signature_str:
            try:
                # Attempt to parse required signature string using inspect by creating a dummy function
                # This is a heuristic; if parsing fails we skip the check.
                exec(f"def _tmp({required_signature_str}): pass", {})
                req_sig = inspect.signature(_tmp)
                cand_sig = inspect.signature(attr)
                if not _signatures_match(req_sig, cand_sig):
                    errors.append(f"Method '{name}' signature does not match expected signature '{required_signature_str}'")
            except Exception:
                pass  # ignore parsing errors, cannot confirm signature
    # Check required attributes
    try:
        required_attrs = [attr for attr in iface.attributes]
    except Exception:
        required_attrs = []

    for attr_sig in required_attrs:
        name = getattr(attr_sig, 'name', None)
        if name and not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}'")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            msg = "Multiple interface violations: " + "; ".join(errors)
            raise Invalid(msg, errors)
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    try:
        from zope.interface import Invalid
    except Exception:
        # If zope.interface is not available, define a generic exception
        class Invalid(Exception):
            pass

    errors = []

    # 1. Verify interface provision/declaration
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(Invalid(f"Candidate {candidate!r} does not claim to provide interface {iface!r}."))
        except Exception as exc:
            errors.append(Invalid(f"Error checking provided interface: {exc!r}"))

    # Helper to compare signatures if possible
    def signatures_match(interface_func, candidate_func):
        try:
            int_sig = inspect.signature(interface_func)
            cand_sig = inspect.signature(candidate_func)
        except ValueError:
            # Cannot get signature; assume mismatched
            return False
        # Compare names and parameter kinds; ignore defaults
        int_params = int_sig.parameters
        cand_params = cand_sig.parameters
        if len(int_params) != len(cand_params):
            return False
        for (int_name, int_p), (cand_name, cand_p) in zip(int_params.items(), cand_params.items()):
            if int_p.kind != cand_p.kind:
                return False
        return True

    # 2. Check required methods
    # zope.interface interfaces expose methods via __dict__ entries which are
    # descriptor objects (Attribute, method, etc.).  We consider callables.
    for name, member in iface.__dict__.items():
        if name.startswith('_'):
            continue
        # Skip attributes defined via interface.attribute
        if hasattr(member, '__module__') and member.__module__ == 'zope.interface.attribute':
            continue
        if callable(member):
            # Required method
            if not hasattr(candidate, name):
                errors.append(Invalid(f"Candidate {candidate!r} missing required method '{name}'."))
                continue
            cand_method = getattr(candidate, name)
            if not callable(cand_method):
                errors.append(Invalid(f"Candidate {candidate!r} has non-callable attribute '{name}' but interface requires a method."))
                continue
            if not signatures_match(member, cand_method):
                errors.append(Invalid(f"Signature mismatch for method '{name}' in candidate {candidate!r}."))
        else:
            # Non-callable entries e.g., attributes
            if not hasattr(candidate, name):
                errors.append(Invalid(f"Candidate {candidate!r} missing required attribute '{name}'."))
            else:
                # Could add attribute type check if needed
                pass

    # 3. Check effects of interface's declared attributes
    if hasattr(iface, '__attributes__'):
        for attr_name, attr_obj in iface.__attributes__.items():
            if not hasattr(candidate, attr_name):
                errors.append(Invalid(f"Candidate {candidate!r} missing interface attribute '{attr_name}'."))
            # Optional: type check via attr_obj.providedInterface
            # but omitted for brevity

    # Final validation
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            msgs = "; ".join(str(e) for e in errors)
            raise Invalid(f"Multiple interface compliance errors: {msgs}")

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.
    """

    errors = []

    # Check interface provision unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f'Object does not provide interface {iface}')
        except Exception:
            errors.append(f'Error checking providedBy for {iface}')

    # Required methods
    try:
        req_methods = getattr(iface, 'requiredMethods', None)
        if req_methods is None:
            # Fallback: derive from methods attribute list
            req_methods = getattr(iface, 'methods', ())
        for name in req_methods:
            if not hasattr(candidate, name):
                errors.append(f'Method "{name}" required by {iface} is missing')
                continue
            attr = getattr(candidate, name)
            if not callable(attr):
                errors.append(f'"{name}" exists but is not callable')
                continue
            # Optional: signature check if possible
            try:
                import inspect
                iface_sig = inspect.signature(getattr(iface, name))
                cand_sig = inspect.signature(attr)
                if iface_sig != cand_sig:
                    errors.append(
                        f'Signature mismatch for "{name}": expected {iface_sig}, got {cand_sig}'
                    )
            except Exception:
                # If introspection fails, skip signature comparison
                pass
    except Exception:
        errors.append(f'Error inspecting required methods for {iface}')

    # Required attributes
    try:
        req_attrs = getattr(iface, 'requiredAttributes', None)
        if req_attrs is None:
            req_attrs = getattr(iface, 'attributes', ())
        for name in req_attrs:
            if not hasattr(candidate, name):
                errors.append(f'Attribute "{name}" required by {iface} is missing')
    except Exception:
        errors.append(f'Error inspecting required attributes for {iface}')

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        raise zope.interface.Invalid(errors)

    return True

