def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        # Resolve candidate if given as a string 'module.ClassName'
        if isinstance(candidate, str):
            module_name, _, class_name = candidate.rpartition('.')
            if not module_name:
                return False
            module = __import__(module_name, fromlist=[class_name])
            candidate_cls = getattr(module, class_name)
        else:
            candidate_cls = candidate

        # Candidate must be a class/type
        if not isinstance(candidate_cls, type):
            return False

        # First check if it is a subclass of the interface
        try:
            if issubclass(candidate_cls, iface):
                return True
        except TypeError:
            # issubclass can raise if either arg is not a class
            pass

        # Gather abstract or expected method names from iface
        required_methods = {
            name
            for name, member in iface.__dict__.items()
            if callable(member) and not name.startswith('_')
        }

        # Gather method names implemented by candidate
        provided_methods = {
            name
            for name, member in candidate_cls.__dict__.items()
            if callable(member) and not name.startswith('_')
        }

        missing = required_methods - provided_methods
        if not missing:
            return True

        if tentative:
            # In tentative mode, accept if at least one required method is present
            return bool(required_methods & provided_methods)

        return False
    except Exception:
        # If anything goes wrong (import error, missing attributes, etc.), treat as not valid
        return False

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Validate that both parameters are classes
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # If candidate is already a subclass of iface, it satisfies the contract
    if issubclass(candidate, iface):
        return True

    # Otherwise, perform a more detailed check
    # Attempt to ensure that candidate implements all of iface's abstract methods
    try:
        import inspect
    except Exception as exc:
        raise RuntimeError("Failed to import inspect module") from exc

    abstract_methods = getattr(iface, "__abstractmethods__", set())
    missing = []
    for name in abstract_methods:
        if not hasattr(candidate, name):
            missing.append(name)

    # If there are missing abstract methods, the candidate is not a full implementation
    if missing:
        if tentative:
            return False
        else:
            missing_str = ", ".join(missing)
            raise TypeError(
                f"candidate is missing implementations of abstract methods: {missing_str}"
            )

    # Ensure candidate is not itself still abstract
    if inspect.isabstract(candidate):
        if tentative:
            return False
        else:
            raise TypeError("candidate class is still abstract after implementing interface")

    # If no abstract methods are missing and candidate is concrete, consider it valid
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if *candidate* has all non-private callables or
    attributes exposed by *iface*. If *tentative* is True,
    the check only ensures that *candidate* has at least the
    members of *iface*; it does not prohibit additional members.
    The function gracefully handles non-classes and raises
    a TypeError if either argument is not a type, module,
    or instance with attributes.  It does not import any modules.
    """
    # Basic type check for iface and candidate
    if iface is None or candidate is None:
        return False
    try:
        iface_dict = iface.__dict__
    except AttributeError:
        # If iface is not a class/module, attempt to use dir
        iface_dict = {}
    try:
        candidate_dict = candidate.__dict__
    except AttributeError:
        candidate_dict = {}

    # Helper to decide if an attribute is considered an interface member
    def is_interface_member(name, attr):
        if name.startswith('_'):
            return False
        # Exclude magic methods and attributes
        if name in ('__module__', '__dict__', '__weakref__', '__doc__',
                    '__annotations__', '__qualname__'):
            return False
        return True

    # Gather interface members (methods, properties, attributes)
    interface_members = {}
    for name in dir(iface):
        if not is_interface_member(name, getattr(iface, name, None)):
            continue
        interface_members[name] = getattr(iface, name, None)

    # Verify each required member exists in candidate
    for name, iface_attr in interface_members.items():
        if not hasattr(candidate, name):
            return False
        cand_attr = getattr(candidate, name)
        # If interface attribute is callable, candidate must be callable too
        if callable(iface_attr) and not callable(cand_attr):
            return False
        # If interface attribute is a property or descriptor, we only
        # verify existence; type or value are not checked here.

    # If tentative check, we are done
    if tentative:
        return True

    # Non-tentative: ensure candidate does not expose extra members
    # that the interface explicitly forbids? The specification does not
    # require this, so we just return True at this point.

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if verification succeeds, False otherwise when tentative=True.
    Raises TypeError if validation fails and tentative is False.
    """
    # Ensure iface is a class-like object
    if not hasattr(iface, "__dict__"):
        raise TypeError("iface must be a class or protocol object")

    # Resolve candidate to a class if it's an instance
    if isinstance(candidate, type):
        cls = candidate
    else:
        try:
            cls = type(candidate)
        except Exception as exc:
            if tentative:
                return False
            raise TypeError(f"Unable to determine class of candidate: {exc}") from exc

    # Helper to check presence of attribute
    def has_attribute(name):
        return hasattr(cls, name)

    # Check abstract methods if available
    abstract_methods = getattr(iface, "__abstractmethods__", None)
    if abstract_methods:
        missing = [m for m in abstract_methods if not has_attribute(m)]
        if missing:
            if tentative:
                return False
            raise TypeError(f"Candidate is missing abstract methods: {missing}")

    # Iterate through iface's dictionary for concrete members
    for name, member in iface.__dict__.items():
        if name.startswith("__") and name.endswith("__"):
            # Skip dunder attributes
            continue
        # Skip attributes that are not concrete implementations
        if name in ("__module__", "__doc__", "__qualname__", "__annotations__"):
            continue

        # Methods or functions
        if callable(member):
            if not has_attribute(name):
                if tentative:
                    return False
                raise TypeError(f"Candidate missing required method: {name}")
            cand_attr = getattr(cls, name, None)
            if not callable(cand_attr):
                if tentative:
                    return False
                raise TypeError(f"Attribute {name} exists but is not callable in candidate")
        # For properties, we expect the descriptor in the class
        elif isinstance(member, property):
            # In Python, property is found in the class __dict__
            if name not in cls.__dict__:
                if tentative:
                    return False
                raise TypeError(f"Candidate missing required property: {name}")
            # Ensure that the candidate's attribute is a property descriptor
            cand_prop = cls.__dict__.get(name)
            if not isinstance(cand_prop, property):
                if tentative:
                    return False
                raise TypeError(f"Attribute {name} is not a property in candidate")
        else:
            # Other attributes (constants, etc.) just ensure they exist and match
            if not has_attribute(name):
                if tentative:
                    return False
                raise TypeError(f"Candidate missing attribute: {name}")
            # Optionally, we could compare values/types here
    return True

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the appropriate metaclass for a class definition given the
    base classes and an optional explicit __metaclass__.
    """
    # Convert bases to a list (records order, keeps duplicates if any)
    try:
        bases_list = list(bases)
    except Exception:
        raise TypeError("bases must be an iterable of classes") from None

    # Validate that each base is a class (i.e., a type)
    for b in bases_list:
        if not isinstance(b, type):
            raise TypeError(f"base {b!r} is not a class")

    # Determine the set of metaclasses from the bases
    base_mcs = set(type(b) for b in bases_list)

    # No bases: default to type
    if not bases_list:
        if explicit_mc is None:
            return type
        # If an explicit metaclass is provided, ensure it's a class
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")
        return explicit_mc

    # If an explicit metaclass is supplied
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")
        for base_mc in base_mcs:
            if not issubclass(explicit_mc, base_mc):
                raise TypeError(
