def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
        """
        Basic implementation of a date/time string parser.
        Works with ISO‑8601 strings and a handful of common patterns.
        """
        # Validate input
        if not isinstance(timestr, str):
            raise TypeError("timestr must be a string")

        s = timestr.strip()
        if not s:
            raise ValueError("empty date/time string")

        # Try ISO format first
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            dt = None

        # If ISO parsing failed, try some common patterns
        if dt is None:
            patterns = [
                "%Y-%m-%d",                     # 2023-07-15
                "%Y-%m-%d %H:%M:%S",            # 2023-07-15 13:45:00
                "%Y-%m-%d %H:%M",               # 2023-07-15 13:45
                "%d/%m/%Y",                     # 15/07/2023
                "%m/%d/%Y",                     # 07/15/2023
                "%d-%b-%Y",                     # 15-Jul-2023
                "%b %d, %Y",                    # Jul 15, 2023
                "%Y.%m.%d",                     # 2023.07.15
                "%Y%m%d",                       # 20230715
                "%Y-%m-%dT%H:%M:%S%z",          # 2023-07-15T13:45:00+0200
                "%Y-%m-%dT%H:%M:%S%Z",          # 2023-07-15T13:45:00GMT
                "%Y-%m-%dT%H:%M:%S.%f%z",       # 2023-07-15T13:45:00.123+0200
            ]
            for pat in patterns:
                try:
                    dt = datetime.datetime.strptime(s, pat)
                    break
                except Exception:
                    continue

        if dt is None:
            # Try to find a timezone name and handle it manually
            if tzinfos and not ignoretz:
                for tzname, tzvalue in tzinfos.items():
                    if tzname.lower() in s.lower():
                        # Remove the timezone part
                        core = s.lower().replace(tzname.lower(), "").strip()
                        try:
                            base = datetime.datetime.fromisoformat(core)
                        except Exception:
                            try:
                                for pat in patterns:
                                    base = datetime.datetime.strptime(core, pat)
                                    break
                            except Exception:
                                continue
                        else:
                            # Attach timezone offset if integer; otherwise use tzvalue directly
                            if isinstance(tzvalue, int):
                                tzinfo = datetime.timezone(datetime.timedelta(seconds=tzvalue))
                                dt = base.replace(tzinfo=tzinfo)
                            else:
                                dt = base.replace(tzinfo=tzvalue)
                            break
            # If still not parsed, raise an error
            if dt is None:
                raise ValueError(f"Unable to parse date/time string: {timestr}")

        # Handle ignore tz flag
        if ignoretz and dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)

        # If default is provided, merge its fields with parsed components
        if isinstance(default, datetime.datetime):
            # Build new components: use parsed values where available, else default
            fields = ['year', 'month', 'day', 'hour', 'minute', 'second', 'microsecond']
            comp = {f: getattr(dt, f) for f in fields}
            # Keep default tzinfo if parsed tzinfo is None and ignoretz==False
            if dt.tzinfo is None and not ignoretz:
                comp['tzinfo'] = default.tzinfo
            dt = default.replace(**comp)

        return dt

