    """
    Format a datetime in the way that D* nodes expect.
    The format used is ISO 8601 with second precision, without timezone
    information; if the input datetime is timezone aware, it is first
    converted to UTC.
    """
    # Basic type check: must have a ``strftime`` method
    if not hasattr(dt, "strftime"):
        raise TypeError("dt must be a datetime instance")
    # Convert aware datetime to UTC, then drop the tzinfo
    if getattr(dt, "tzinfo", None) is not None:
        try:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception as exc:
