    # Format to ISO 8601 without timezone component
    try:
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    except Exception as exc:
        raise ValueError(f"Error formatting datetime: {exc}") from exc

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be callable or None")

    tags = set()
    result_parts = []
    i = 0
    inside_code = False
    text_len = len(text)

    while i < text_len:
        # Handle entering or exiting code blocks
        if not inside_code:
            if text.startswith("```", i):
                inside_code = True
                result_parts.append("```")
                i += 3
                continue
        else:
            if text.startswith("```", i):
                inside_code = False
                result_parts.append("```")
                i += 3
                continue

        if not inside_code:
            ch = text[i]
            if ch in ("#", "@"):
                # try to parse tag word
                start = i + 1
                j = start
                while j < text_len and (text[j].isalnum() or text[j] in ("_", "-")):
                    j += 1
                if j > start:
                    tag_word = text[start:j]
                    tags.add(tag_word)
                    if replacer:
                        try:
                            rep = replacer(tag_word)
                            if rep is None:
                                result_parts.append(ch + tag_word)
                            else:
                                result_parts.append(rep)
                        except Exception:
                            # on error keep original
                            result_parts.append(ch + tag_word)
                    else:
                        result_parts.append(ch + tag_word)
                    i = j
                    continue
                # lone # or @ with no word following
            result_parts.append(ch)
            i += 1
        else:
            # inside code block, just copy character
            result_parts.append(text[i])
            i += 1

    return tags, "".join(result_parts)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be callable")
    import re

    # Find all fenced code block ranges (```...```)
    code_blocks = []
    for m in re.finditer(r'```.*?```', text, flags=re.DOTALL):
        code_blocks.append((m.start(), m.end()))

    def in_code_block(pos: int) -> bool:
        for start, end in code_blocks:
            if start <= pos < end:
                return True
        return False

    # Detect tags outside code blocks
    tags: Set[str] = set()
    for m in re.finditer(r'[@#]\w+', text):
        if not in_code_block(m.start()):
            tags.add(m.group(0))

    # If no replacer, return tags and original text
    if replacer is None:
        return tags, text

    # Replacement logic
    def replace_tag(match: re.Match) -> str:
        if in_code_block(match.start()):
            return match.group(0)
        try:
            return str(replacer(match.group(0)))
        except Exception:
            return match.group(0)

    replaced_text = re.sub(r'[@#]\w+', replace_tag, text)
    return tags, replaced_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        # Add attributes to existing <a> tags
        def _add_attrs(t):
            start = 0
            parts = []
            while True:
                a_start = t.find('<a ', start)
                if a_start == -1:
                    parts.append(t[start:])
                    break
                parts.append(t[start:a_start])
                a_end = t.find('>', a_start)
                if a_end == -1:
                    parts.append(t[a_start:])
                    break
                tag = t[a_start:a_end+1]
                if 'target=' not in tag:
                    tag = tag[:-1] + ' target="_blank"'
                if 'rel=' not in tag:
                    tag = tag[:-1] + ' rel="noopener noreferrer"'
                parts.append(tag)
                start = a_end + 1
            return ''.join(parts)

        processed = _add_attrs(text)

        # Linkify plain URLs
        words = processed.split(' ')
        for i, word in enumerate(words):
            if word.startswith('http://') or word.startswith('https://'):
                # Separate trailing punctuation
                j = 0
                while j < len(word) and word[j] not in '.,;:!?)]}':
                    j += 1
                url = word[:j]
                tail = word[j:] if j < len(word) else ''
                link = f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
                words[i] = link + tail
        return ' '.join(words)
    except Exception:
        # In case of any unexpected error, return the original text unchanged
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote URL to determine the content type.

    Returns the value of the "Content-Type" header if available; otherwise,
    returns None. Handles common network errors gracefully.
    """
    if not isinstance(url, str) or not url:
        return None
    try:
        # Dynamically import urllib modules to avoid top-level import statements.
        urllib_request = __import__('urllib.request')
        urllib_error = __import__('urllib.error')
        try:
            req = urllib_request.Request(url, method='HEAD')
        except TypeError:
            # For older Python versions that don't support the method kwarg
            req = urllib_request.Request(url)
            req.get_method = lambda: 'HEAD'
        with urllib_request.urlopen(req, timeout=10) as response:
            return response.headers.get('Content-Type')
    except (urllib_error.URLError, urllib_error.HTTPError, ValueError, Exception):
        # ValueError covers malformed URLs; any other exception results in None.
        return None

def fetch_content_type(url: str) -> Optional[str]:
