        return None
    try:
        urllib = __import__('urllib.request')
        req = urllib.Request(url, method='HEAD')
        with urllib.urlopen(req, timeout=10) as resp:
            return resp.getheader('Content-Type')
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    if not isinstance(url, str) or not url:
        return None
    try:
        import urllib.request
        import urllib.error
        # Use a HEAD request if supported; fallback to GET with no body otherwise
        try:
            req = urllib.request.Request(url, method="HEAD")
        except TypeError:
            # For older Python versions that don't support the method keyword
            req = urllib.request.Request(url)
            req.get_method = lambda: "HEAD"
        with urllib.request.urlopen(req, timeout=10) as response:
            content_type = response.headers.get("Content-Type")
            if content_type is not None:
                return content_type.strip()
    except (urllib.error.HTTPError, urllib.error.URLError, ValueError, Exception):
        # Any error (HTTP error, URL error, malformed URL, timeout, etc.) results in None
        return None
    return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        # A tag must consist only of alphanumeric characters, hyphens, or underscores.
        # It cannot start or end with a hyphen or underscore, and cannot contain
        # consecutive hyphens or underscores. The tag must be at least one character long.
        import re
        pattern = re.compile(r'^[A-Za-z0-9]+(?:[_-][A-Za-z0-9]+)*$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag.

    A valid tag follows these rules:
    * Must be a non-empty string.
    * Length not greater than 30 characters.
    * Contains only lowercase ASCII letters, digits, or a single hyphen '-' between characters.
    * Cannot start or end with a hyphen.
    * Cannot contain consecutive hyphens.
    * No other punctuation or whitespace is allowed.

    Returns:
        True if the string satisfies all tag constraints, otherwise False.
    """
    try:
        if not isinstance(tag, str):
            return False
        if not tag:
            return False
        if len(tag) > 30:
            return False

        previous_char = None
        for i, ch in enumerate(tag):
            if not ch.isascii():
                return False
            if ch == '-':
                # Hyphen cannot be at the start or end
                if i == 0 or i == len(tag) - 1:
                    return False
                # Hyphen cannot follow another hyphen
                if previous_char == '-':
                    return False
            elif not ch.islower() and not ch.isdigit():
                return False
            previous_char = ch

        return True
    except Exception:
        return False

