    This is only a shallow conversation - child nodes are not recursively processed.
    The function accepts an Element-like object (e.g., an xml.etree.ElementTree.Element)
    and returns a dictionary mapping each child tag to the child element. If there
    are multiple children with the same tag name, the resulting value will be a
    list of Element instances in the order they appear.
    """
    result = {}
    try:
        # If node is None, return empty dict
        if node is None:
            return result

        # Elements in ElementTree can be iterated over directly.
        # For robustness, detect the interface that provides iterable child access.
        # Try direct iteration; if fails, fall back to getattr('iter') or getattr('getchildren')
        children = None
        try:
            children = list(node)  # direct iteration
        except Exception:
            # Try deprecated getchildren
            if hasattr(node, 'getchildren'):
                children = node.getchildren()
            else:
                # No children
                children = []

        for child in children:
            tag = getattr(child, 'tag', None)
            if tag is None:
                continue  # Skip if tag missing
            # Store mapping: if duplicate tags, use list
            if tag in result:
                current = result[tag]
                if isinstance(current, list):
                    current.append(child)
                else:
                    result[tag] = [current, child]
            else:
                result[tag] = child
        return result
    except Exception as e:
        # Any unexpected error is reported back with a clear message.
        raise ValueError(f"Failed to convert XML children to dict: {e}") from e

