            if ptype and prop.text:
                properties[ptype] = prop.text
        links = []
        for link in root.findall('xrd:link', namespaces=ns):
            link_dict = {k: link.attrib.get(k) for k in ('rel', 'type', 'href') if k in link.attrib}
            if link_dict:
                links.append(link_dict)
        return {
            'subject': subject,
            'aliases': aliases,
            'properties': properties,
            'links': links
        }
    except Exception as e:
        raise ValueError(f"Unable to parse webfinger: {e}") from e

