def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not isinstance(handle, str) or "@" not in handle:
            return None

        acct = f"acct:{handle}"
        domain = handle.split("@", 1)[1].strip()
        if not domain:
            return None

        # Safely encode the resource parameter
        urllib_parse = __import__("urllib.parse")
        encoded_acct = urllib_parse.quote(acct, safe="")

        url = f"https://{domain}/.well-known/webfinger?resource={encoded_acct}"

        urllib_request = __import__("urllib.request")
        with urllib_request.urlopen(url, timeout=5) as resp:
            # Use getcode() for compatibility
            if resp.getcode() != 200:
                return None
            data = resp.read()
            if isinstance(data, bytes):
                return data.decode("utf-8", errors="replace")
            return str(data)
    except Exception:
        return None

