    """Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : Iterable[str]
        A sequence of directory paths to search.
    spec_option : str
        File name pattern to match (e.g., '*.ini').

    Returns
    -------
    List[str]
        Full paths of files that match the specified pattern in the given directories.
    """
    # Input validation
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths.")
    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string pattern.")
    try:
        os_mod = __import__("os")
        fnmatch_mod = __import__("fnmatch")
    except Exception as exc:
        raise RuntimeError("Required modules 'os' or 'fnmatch' are unavailable.") from exc

    matched_files = []
    for directory in settings_dirs:
        if not isinstance(directory, str):
            continue  # Skip non-string entries
        try:
            for entry in os_mod.listdir(directory):
                if fnmatch_mod.fnmatch(entry, spec_option):
                    matched_files.append(os_mod.path.join(directory, entry))
        except (OSError, PermissionError, FileNotFoundError):
            # Skip directories that cannot be accessed
            continue
    return matched_files

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Verify settings_dirs is iterable but not a string
    if not hasattr(settings_dirs, '__iter__') or isinstance(settings_dirs, (str, bytes)):
        raise ValueError("settings_dirs must be an iterable of directory paths")
    result = []
    for dir_path in settings_dirs:
        try:
            entries = os.listdir(dir_path)
        except Exception:
            # Skip directories that cannot be read
            continue
        for entry in entries:
            full_path = os.path.join(dir_path, entry)
            if isinstance(entry, str) and os.path.isfile(full_path):
                if spec_option is None:
                    result.append(full_path)
                else:
                    # Apply simple pattern matching if spec_option is a string
                    try:
                        import fnmatch
                        if fnmatch.fnmatch(entry, spec_option):
                            result.append(full_path)
                    except Exception:
                        # If fnmatch not available or fails, add all files
                        result.append(full_path)
    return result

