    if spec_option is None:
        spec_option = '*'
    if not isinstance(spec_option, str):
        raise TypeError(f"spec_option must be a string, got {type(spec_option).__name__}")

    # Import required modules locally to avoid top-level imports
    import os
    import glob

    matched_files = []
    seen = set()
    for dir_path in settings_dirs:
        try:
            if not os.path.isdir(dir_path):
                continue
            pattern = os.path.join(dir_path, spec_option)
            for file_path in glob.glob(pattern):
