def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    from copy import deepcopy
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")
    try:
        # Recursive helper to resolve an individual group, handling nested includes
        def _resolve_group(group, group_defs, visited):
            result = deepcopy(group)
            includes = result.pop('include', None)
            if includes:
                if isinstance(includes, str):
                    names = [includes]
                elif isinstance(includes, (list, tuple)):
                    names = list(includes)
                else:
                    raise ValueError("'include' must be a string or a list/tuple of strings")
                for name in names:
                    if name in visited:
                        raise ValueError(f"Circular include detected for group '{name}'")
                    if name not in group_defs:
                        raise KeyError(f"Included group '{name}' not found")
                    visited.add(name)
                    sub = _resolve_group(group_defs[name], group_defs, visited.copy())
                    result.update(sub)
            return result

        groups = parser_dict.get('groups', {})
        if not groups:
            # Nothing to resolve
            return deepcopy(parser_dict)

        # Resolve top‑level includes if present
        includes = parser_dict.get('include')
        if not includes:
            return deepcopy(parser_dict)

        resolved = deepcopy(parser_dict)
        resolved.pop('include')
        if isinstance(includes, str):
            names = [includes]
        elif isinstance(includes, (list, tuple)):
            names = list(includes)
        else:
            raise ValueError("'include' must be a string or a list/tuple of strings")

        for name in names:
            if name not in groups:
                raise KeyError(f"Included group '{name}' not found")
            sub = _resolve_group(groups[name], groups, visited=set([name]))
            resolved.update(sub)

        # Optionally remove the groups dict after merging if desired
        resolved.pop('groups', None)
        return resolved
    except Exception as exc:
        raise ValueError(f"Failed to resolve groups: {exc}") from exc

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    The method looks for an ``include`` key in ``parser_dict`` and expands
    each reference into concrete definitions that are expected to be
    available through a group registry accessible as ``self._groups``
    or via a ``_get_group_def`` helper method.  The expansion is
    performed in-place and the ``include`` key is removed after
    processing.

    Supported ``include`` formats::

        # direct mapping of name → alias (where alias can be None)
        {"include": {"group_a": "alias_a", "group_b": None}}

        # list of group names or single-key dicts
        {"include": ["group_c", {"group_d": "alias_d"}]}

    Any invalid format or missing group will raise a descriptive
    exception.

    The function is resilient to the following issues:

    * ``parser_dict`` must be a dictionary; otherwise a ``TypeError`` is raised.
    * The ``include`` entry must be a list or dict; otherwise a ``ValueError`` is raised.
    * Missing group definitions raise ``KeyError`` or ``RuntimeError``.
    * Included definitions that are not dictionaries raise ``TypeError``.
    """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")

    include_directives = parser_dict.get("include")
    if include_directives is None:
        return

    if isinstance(include_directives, dict):
        items = [(name, alias) for name, alias in include_directives.items()]
    elif isinstance(include_directives, list):
        items = []
        for elem in include_directives:
            if isinstance(elem, dict):
                if len(elem) != 1:
                    raise ValueError(
                        f"Invalid include dict element (must contain exactly one mapping): {elem}"
                    )
                name, alias = next(iter(elem.items()))
                items.append((name, alias))
            else:
                items.append((elem, None))
    else:
        raise ValueError(
            f"include directive must be a dict or list, got {type(include_directives).__name__}"
        )

    for name, alias in items:
        # Retrieve the included group definition
        try:
            group_def_retrieval = getattr(self, "_get_group_def", None)
            if callable(group_def_retrieval):
                definition = group_def_retrieval(name)
            else:
                # fallback to an attribute named _groups
                definition = getattr(self, "_groups", {}).get(name)
        except Exception as exc:
            raise RuntimeError(f"Error retrieving group definition for '{name}': {exc}") from exc

        if definition is None:
            raise KeyError(f"Group '{name}' not found in registry")

        if not isinstance(definition, dict):
            raise TypeError(f"Included group '{name}' must be a dict, got {type(definition).__name__}")

        # Recursively resolve includes inside the included definition
        try:
            self._include_groups(definition)
        except Exception as exc:
            raise RuntimeError(f"Error processing nested includes in group '{name}': {exc}") from exc

        # Determine the key under which the definition will be inserted/merged
        key = alias or name

        if key in parser_dict:
            if isinstance(parser_dict[key], dict):
                parser_dict[key].update(definition)
            else:
                # If the existing entry is not a dict, replace it with the new definition
                parser_dict[key] = definition
        else:
            parser_dict[key] = definition

    # Clean up the include directive after processing
    parser_dict.pop("include", None)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, 'spec', {})
    except Exception:
        spec = {}
    if not isinstance(spec, dict):
        return defaults

    parameters = spec.get('parameters', [])
    # Ensure parameters is iterable
    if not isinstance(parameters, (list, tuple)):
        parameters = []

    import os  # local import to avoid global import

    for param in parameters:
        if not isinstance(param, dict):
            continue
        name = param.get('name')
        if not name:
            continue

        # Check for environment variable override
        env_var = param.get('env')
        if env_var:
            env_value = os.getenv(env_var)
            if env_value is not None:
                # Convert to appropriate type if default exists (e.g., int, bool)
                try:
                    default_val = param.get('default')
                    if default_val is not None:
                        if isinstance(default_val, bool):
                            env_value = env_value.lower() in ('1', 'true', 'yes')
                        elif isinstance(default_val, int):
                            env_value = int(env_value)
                        elif isinstance(default_val, float):
                            env_value = float(env_value)
                    defaults[name] = env_value
                    continue
                except Exception:
                    # fall back to string value
                    defaults[name] = env_value
                    continue

        # Fallback to spec default if provided
        if 'default' in param:
            defaults[name] = param['default']

    # Override with any user-provided arguments if present
    user_args = getattr(self, 'args', None)
    if isinstance(user_args, dict):
        for k, v in user_args.items():
            if v is not None:
                defaults[k] = v

    return defaults

