def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Attempt to locate the spec; it may be a dict or a path to a json/yaml file
    spec = getattr(self, "spec", None)
    if spec is None:
        spec_path = getattr(self, "spec_path", None)
        if spec_path is None:
            raise AttributeError(
                "Instance must have a 'spec' attribute or a 'spec_path' attribute pointing to a spec file."
            )
        try:
            with open(spec_path, "r", encoding="utf-8") as f:
                try:
                    import json
                    spec = json.load(f)
                except Exception:
                    try:
                        import yaml
                        spec = yaml.safe_load(f)
                    except Exception as exc:
                        raise RuntimeError(
                            f"Failed to parse spec file '{spec_path}': {exc}"
                        ) from exc
        except Exception as exc:
            raise RuntimeError(f"Unable to read spec file '{spec_path}': {exc}") from exc
    elif not isinstance(spec, dict):
        raise TypeError("Provided 'spec' must be a dictionary.")

    # Extract defaults: each spec entry is either a value or a dict containing a 'default' key
    for key, value in spec.items():
        if isinstance(value, dict) and "default" in value:
            defaults[key] = value["default"]
        else:
            defaults[key] = value

    # Override with environment variables if present (case-insensitive: key uppercased)
    import os
    for key in list(defaults.keys()):
        env_val = os.getenv(key.upper())
        if env_val is not None:
            defaults[key] = env_val

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        defaults = {}
        if not hasattr(self, "spec"):
            return defaults

        spec = self.spec
        # Normalise spec to a list of dicts
        if isinstance(spec, dict):
            items = spec.get("args") or spec.get("parameters") or spec.get("options") or []
        else:
            items = spec

        import os

        for entry in items:
            if not isinstance(entry, dict):
                continue

            name = entry.get("name") or entry.get("arg") or entry.get("parameter") or entry.get("option")
            if not name:
                continue

            # Use default from spec if present
            if "default" in entry and entry["default"] is not None:
                defaults[name] = entry["default"]
                continue

            # Fallback to environment variable if specified
            env_var = entry.get("env") or f"APP_{name.upper()}"
            if env_var in os.environ:
                value = os.environ[env_var]
                # Try to cast to the declared type
                typ = entry.get("type", str)
                try:
                    value = typ(value)
                except Exception:
                    # leave as string if casting fails
                    pass
                defaults[name] = value

        return defaults
    except Exception as exc:
        raise RuntimeError(f"Unable to resolve spec defaults: {exc}") from exc

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, 'spec', {})
        if not isinstance(spec, dict):
            return defaults
        # Ensure os is available for environment variable resolution
        try:
            import os
        except ImportError:
            os = None
        for key, value in spec.items():
            # Handle dict-based spec entries
            if isinstance(value, dict):
                # Prefer default function if provided
                if 'default_fn' in value:
                    try:
                        defaults[key] = value['default_fn']()
                        continue
