                        pass
                # Simple default value
                if 'default' in value:
                    defaults[key] = value['default']
                    continue
                # Environment variable override
                if 'env' in value and os is not None:
                    try:
                        env_val = os.getenv(value['env'])
                        if env_val is not None:
                            defaults[key] = env_val
                            continue
                    except Exception:
                        pass
            # Handle simple attributes with default
            try:
