    """
    # Validate input
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")

    # Attempt to retrieve the command options container
    try:
        command_options_container = getattr(self, "command_options", {})
    except Exception:
        # If attribute access itself fails, treat as empty container
        command_options_container = {}

    # Ensure the container is a dictionary
    if not isinstance(command_options_container, dict):
        raise TypeError("Expected 'command_options' to be a dict")

    # Look up the options for the requested command
    raw_options = command_options_container.get(command_name)

    # If the command is unknown, return an empty list
    if raw_options is None:
        return []

    # Depending on how options are stored, normalize the result to a list.
    if isinstance(raw_options, list):
        return raw_options
    if isinstance(raw_options, dict):
        # Return the values (e.g., option spec objects) rather than keys
        return list(raw_options.values())
    # For any other type, wrap it in a list
    return [raw_options]

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    command_name = command_name.strip()
    if not command_name:
        raise ValueError("command_name cannot be empty")

    try:
        parser = getattr(self, "parser", None)
        if parser is None:
            raise AttributeError("Parser attribute not found on the instance")

        # Try common ways the parser might expose subcommands
        cmd = None
        if hasattr(parser, "commands") and isinstance(parser.commands, dict):
            cmd = parser.commands.get(command_name)
        elif hasattr(parser, "subcommands") and isinstance(parser.subcommands, dict):
            cmd = parser.subcommands.get(command_name)
        else:
            subparsers = getattr(parser, "_subparsers", None)
            if subparsers and hasattr(subparsers, "_actions"):
                for action in subparsers._actions:
                    if getattr(action, "dest", None) == command_name:
                        cmd = action
                        break

        if cmd is None:
            raise KeyError(f"Command '{command_name}' not found in parser")

        # Attempt to retrieve options from known attributes
        if hasattr(cmd, "option_spec") and isinstance(cmd.option_spec, dict):
            return list(cmd.option_spec.keys())
        if hasattr(cmd, "options") and isinstance(cmd.options, (list, tuple)):
            return list(cmd.options)

        # If cmd is a dict, return its keys (might represent option names)
        if isinstance(cmd, dict):
            return list(cmd.keys())
        # If cmd is a list of option names
        if isinstance(cmd, list):
            return cmd

        # As a last resort, look at action objects for option strings
        options = []
        for action in getattr(cmd, "actions", []):
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                options.extend(option_strings)
        return options

    except Exception as exc:
        if hasattr(self, "logger"):
            try:
                self.logger.error(
                    f"Failed to get parser options for command '{command_name}': {exc}",
                    exc_info=True,
                )
            except Exception:
                pass
        raise RuntimeError(f"Could not retrieve options for command '{command_name}': {exc}") from exc

