def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        silent_names = []
        if not args:
            return silent_names
        try:
            # Determine the structure of args
            if isinstance(args, dict):
                iterable = args.items()
            elif isinstance(args, (list, tuple)):
                # Expect a list/tuple of (name, value) pairs
                if all(isinstance(item, tuple) and len(item) == 2 for item in args):
                    iterable = args
                else:
                    # Unsupported format, return empty list
                    return silent_names
            else:
                # Unsupported type (e.g., positional list without names)
                return silent_names

            # Patterns that identify sensitive or "silent" arguments
            patterns = (
                "secret", "apikey", "api_key", "token", "password",
                "pwd", "key", "auth", "credential", "creds", "access"
            )
            for key, _ in iterable:
                if isinstance(key, str) and any(pat.lower() in key.lower() for pat in patterns):
                    silent_names.append(key)
        except Exception:
            # In case of any unexpected error, return an empty list
            silent_names = []

        return silent_names

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Return an empty list if no arguments were provided
    if args is None:
        return []

    silent_args = []

    # If the arguments are provided as a dictionary, treat any key with a None
    # or empty string value as "silenced".
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None or (isinstance(value, str) and value.strip() == ""):
                silent_args.append(str(key))
    else:
        # Otherwise, assume a list-like collection of argument strings.
        for arg in args:
            if isinstance(arg, str):
                # Strip common option prefixes for comparison and return the cleaned name
                cleaned = arg.lstrip("-")
                # Consider arguments containing the term "silent" (case insensitive) as silenced
                if "silent" in cleaned.lower():
                    silent_args.append(cleaned)

    return silent_args

def get_silent_args(self, args):
    """Return a list of argument names that should be treated as silent.

    Parameters
    ----------
    args : Mapping or Iterable
        An object containing argument definitions. It may be a dictionary
        mapping argument names to values or an iterable of objects/dicts
        that expose ``name`` and ``silent`` attributes.

    Returns
    -------
    list
        A list of argument names that are considered silent. Empty if none
        are detected or the input is invalid.
    """
    silent = []
    try:
        # Dictionary input: key prefixes/suffixes indicate silence
        if isinstance(args, dict):
            for key, value in args.items():
                if isinstance(key, str) and (key.startswith("_") or key.endswith("_")):
                    silent.append(key)
                # Boolean values: False considered silent
                if isinstance(value, bool) and not value:
                    silent.append(key)

        # Iterable input: handle objects or dicts with name/silent
        elif isinstance(args, (list, tuple)):
            for item in args:
                # dict with 'name' and optional 'silent'
                if isinstance(item, dict) and "name" in item:
                    if item.get("silent", False):
                        silent.append(item["name"])
                    # fallback: key names starting with underscore
                    elif isinstance(item["name"], str) and (
                        item["name"].startswith("_") or item["name"].endswith("_")
                    ):
                        silent.append(item["name"])
                else:
                    # object with attributes
                    name = getattr(item, "name", None)
                    silent_flag = getattr(item, "silent", False)
                    if name and silence_flag:
                        silent.append(name)
        # Unsupported type: return empty list
    except Exception:
        # Guard against any unexpected errors; silence the exception
        pass

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")
    # Retrieve the list of required argument names; fall back to empty list if not defined.
    required = getattr(self, "required_args", [])
    if not isinstance(required, (list, tuple, set)):
        raise TypeError(f"self.required_args must be an iterable, got {type(required).__name__}")
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")
    return None

