            if not isinstance(opt, dict):
                continue
            opt_name = opt.get("name")
            if not isinstance(opt_name, str):
                continue

            # Skip if the option has no required_when condition.
            if "required_when" not in opt:
                continue

            condition = opt["required_when"]
            try:
                # If condition is a string, evaluate it with the args as
                # local variables.  For safety we disable builtins.
                if isinstance(condition, str):
                    # Allow referencing command_name directly.
                    local_vars = dict(args)
                    local_vars["command_name"] = command_name
                    # Evaluate the condition; if true, add the argument name.
                    if eval(condition, {"__builtins__": {}}, local_vars):
                        required_when_names.append(opt_name)
                # If the condition is callable, call it with args.
                elif callable(condition):
                    if condition(args):
                        required_when_names.append(opt_name)
                # For any other truthy value consider it satisfied.
                else:
                    if condition:
                        required_when_names.append(opt_name)
            except Exception:
                # Any error in evaluating a condition is treated as
                # non‑met; the argument is simply not considered required.
                continue

        return required_when_names

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []

    if args is None:
        args = {}

    for opt in options_spec:
        try:
            req_when = opt.get('required_when')
        except AttributeError:
            # In case opt is not a dict-like object
            continue

        if req_when is None:
            continue

        matched = False

        # If required_when is callable, evaluate it with args
        if callable(req_when):
            try:
                matched = bool(req_when(args))
            except Exception:
                matched = False

        # If required_when is a list of option names, all must be present in args
        elif isinstance(req_when, list):
            try:
                matched = all(name in args for name in req_when)
            except Exception:
                matched = False

        # If required_when is a string expression
        elif isinstance(req_when, str):
            expr = req_when.strip()
            # Handle simple equality or inequality checks
            if '==' in expr:
                key, val = expr.split('==', 1)
                key = key.strip()
                val = val.strip()
                try:
                    matched = key in args and str(args[key]) == val
                except Exception:
                    matched = False
            elif '!=' in expr:
                key, val = expr.split('!=', 1)
                key = key.strip()
                val = val.strip()
                try:
                    matched = key in args and str(args[key]) != val
                except Exception:
                    matched = False
            else:
                # Treat the whole string as a flag name that must be present
                key = expr
                try:
                    matched = key in args
                except Exception:
                    matched = False

        # If required_when is directly a boolean value
        elif isinstance(req_when, bool):
            matched = req_when

        # Anything else is ignored for safety
        else:
            matched = False

        if matched:
            # Use the option's name; fallback to None if missing
            name = opt.get('name')
            if name is not None:
                required.append(name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        def _match_condition(cond):
            """Return True if ``cond`` matches the current command/args."""
            try:
                # If condition is a function, call it
                if callable(cond):
                    return bool(cond(command_name, args))

                # If condition is a dictionary, all key/value pairs must be satisfied
                if isinstance(cond, dict):
                    for k, v in cond.items():
                        # if v is a list, any value in args[k] must match
                        if isinstance(v, (list, tuple)):
                            if not isinstance(args.get(k), (list, tuple)):
                                return False
                            if not any(item == vv for item in args[k] for vv in v):
                                return False
                        else:
                            if args.get(k) != v:
                                return False
                    return True

                # If condition is a list, any element must match
                if isinstance(cond, (list, tuple)):
                    return any(_match_condition(ele) for ele in cond)

                # If condition is a string, match against command name
                if isinstance(cond, str):
                    return command_name == cond

                # If condition is a boolean, use it directly
                if isinstance(cond, bool):
                    return cond

            except Exception:
                # If anything goes wrong evaluate as not matched
                return False
            return False

        required = []
        if not isinstance(options_spec, (list, tuple)):
            return required

        for option in options_spec:
            try:
                if not isinstance(option, dict):
                    continue
                cond = option.get("required_when")
                if cond is None:
                    continue
                if _match_condition(cond):
                    name = option.get("name")
                    if isinstance(name, str):
                        required.append(name)
            except Exception:
                # Skip problematic option specs
                continue

        return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        conditioned = []
        for opt in options_spec:
            try:
                cond = opt.get("required_when")
                if cond is None:
                    continue

                # If the condition is a boolean, use it directly
                if isinstance(cond, bool):
                    if not cond:
                        continue

                # If the condition is a callable (e.g., lambda or function), call it with args
                elif callable(cond):
                    try:
                        if not cond(args):
                            continue
                    except Exception:
                        # If evaluation fails, skip this condition
                        continue

                # If the condition is a dict, interpret as key-value matches in args
                elif isinstance(cond, dict):
                    matched = True
                    for ck, cv in cond.items():
                        if ck not in args:
                            matched = False
                            break
                        if cv is not None and args[ck] != cv:
                            matched = False
                            break
                    if not matched:
                        continue

                else:
                    # Unsupported condition type; skip
                    continue

                # If condition matched, add option name
                name = opt.get("name")
                if isinstance(name, str) and name not in conditioned:
                    conditioned.append(name)

            except Exception:
                # Any error with this option's condition should not stop the whole process
                continue

        return conditioned

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    # Ensure args is a dict; if it's a list or other type we try to convert
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}
    for opt in options_spec:
        # Each option spec is expected to be a dict.
        if not isinstance(opt, dict):
            continue
        opt_name = opt.get("name")
        if not opt_name:
            continue
        cond = opt.get("required_when")
        if cond is None:
            continue
        try:
            match = False
            # If condition is a string, evaluate it in a sandboxed environment.
            if isinstance(cond, str):
                # Provide args and command_name to the eval environment.
                local_vars = dict(args)
                local_vars["command_name"] = command_name
                match = bool(eval(cond, {}, local_vars))
            # If condition is a callable, invoke it with args and command_name.
            elif callable(cond):
                match = bool(cond(args, command_name))
            # If condition is a boolean directly.
            elif isinstance(cond, bool):
                match = cond
            if match:
                required.append(opt_name)
        except Exception:
            # Ignore options whose condition cannot be evaluated and
            # continue processing the rest.
            continue
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. The arguments can be provided as a
        dictionary mapping argument names to values, or as a list/tuple
        of values. For each value that is a string or a collection, the
        length is compared against a hard‑coded maximum of 255
        characters/items. If an argument exceeds this limit a
        ``ValueError`` is raised. Unsupported argument types are ignored.
    """
    # If no arguments were supplied there is nothing to validate.
    if args is None:
        return

    try:
        # Normalize the arguments into an iterable of (name, value) pairs.
        if isinstance(args, dict):
            arg_iter = args.items()
        elif isinstance(args, (list, tuple)):
            # Use the index as the argument name in list/tuple case.
            arg_iter = enumerate(args)
        else:
            raise TypeError("`args` must be a dict or a list/tuple")

        # Iterate over each argument and validate its length.
        for name, value in arg_iter:
            # Only strings and collections have a length that can be checked.
            if isinstance(value, (str, list, tuple, set, dict)):
                if len(value) > 255:
                    # Create a human‑readable name for the offending argument.
                    arg_name = str(name) if isinstance(args, dict) else f"arg{index}"
                    raise ValueError(
                        f"Argument '{arg_name}' exceeds maximum length of 255."
                    )
    except Exception as exc:
        # Store the original exception context to aid debugging.
        raise ValueError(
            f"Failed to validate argument lengths: {exc}"
        ) from exc

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected to be a mapping of argument names to values.
    :raises TypeError: If `args` is not a mapping.
    :raises ValueError: If any argument value exceeds its specified maximum length.
    """
    # Ensure we have a dictionary-like object
    try:
        items = args.items()
    except AttributeError:
        raise TypeError("`args` must be a dictionary-like object") from None

    # Retrieve the mapping of argument names to maximum lengths.
    # The attribute name may vary; we try a few common possibilities.
    max_length_mapping = (
        getattr(self, "_max_length_args", None) or
        getattr(self, "max_length_args", None) or
        getattr(self, "MAX_LENGTH_ARGS", None) or
        {}
    )
    if not isinstance(max_length_mapping, dict):
        max_length_mapping = {}

    for arg_name, value in items:
        max_len = max_length_mapping.get(arg_name)

        # If no max length specified for this argument, skip validation.
        if max_len is None:
            continue

        # Skip non-iterable or None values as they can't be measured by length.
        if value is None:
            continue

        try:
            current_len = len(value)
        except Exception:
            # Value does not support len(); skip or consider as not exceeding length.
            continue

        if current_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length ({current_len}) exceeds "
                f"the allowed maximum ({max_len})."
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if args is None:
        raise TypeError("args cannot be None")

    max_len = getattr(self, "max_length", None)
    if max_len is None:
        raise AttributeError("Instance must have a 'max_length' attribute to validate against")
    if not isinstance(max_len, int) or max_len < 0:
        raise ValueError("max_length must be a non-negative integer")

    if isinstance(args, dict):
        iterable = args.items()
    elif isinstance(args, (list, tuple)):
        iterable = enumerate(args)
    else:
        raise TypeError("args must be a dict, list, or tuple")

    for key, value in iterable:
        try:
            val_len = len(value)
        except TypeError:
            # Skip values without length
            continue
        if val_len > max_len:
            raise ValueError(f"Length of argument '{key}' ({val_len}) exceeds maximum allowed ({max_len})")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises ValueError: If any argument exceeds its specified maximum length.
    :returns: True if all arguments are within their allowed lengths.
    """
    try:
        # Optional mapping of argument names to maximum allowed lengths,
        # e.g. self.max_lengths = {"name": 100, "tags": 10}
        max_lengths = getattr(self, "max_lengths", {})
        for arg_name, value in args.items():
            # Skip items without a specified maximum length
            if arg_name not in max_lengths:
                continue
            max_len = max_lengths[arg_name]
            # Determine length only for iterable types that have a len()
            if isinstance(value, (str, bytes, list, tuple, set, dict)):
                value_len = len(value)
            else:
                # Non-iterable values (e.g., int, float, None) have no length restriction
                continue
            if value_len > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' length ({value_len}) exceeds "
                    f"the allowed maximum of {max_len}."
                )
        return True
    except Exception as exc:
        # Re‑raise as ValueError to keep a clear API contract
        raise ValueError(f"Invalid argument length(s): {exc}") from exc

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to their valid choices.
    # It may be defined as a dict on the instance: {arg_name: [choice1, choice2, ...], ...}
    choices_map = getattr(self, "choices", None)
    if not isinstance(choices_map, dict) or not choices_map:
        # Nothing to validate
        return

    # Convert args to a plain dict regardless of whether it's a dict or Namespace
    if isinstance(args, dict):
        args_dict = args
    else:
        try:
            args_dict = vars(args)
        except Exception as exc:
            raise TypeError("`args` must be a dict or Namespace-like object") from exc

    # Iterate over each argument that has a predefined set of allowed values
    for arg_name, allowed in choices_map.items():
        if arg_name not in args_dict:
            # Argument not provided; no validation needed
            continue

        value = args_dict[arg_name]
        if value is None:
            # Skip None values – typically optional arguments
            continue

        # Handle iterable values (e.g., when `nargs='+'` or `nargs='*'`)
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{arg_name}'. "
                        f"Expected one of [{', '.join(map(str, allowed))}]"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{arg_name}'. "
                    f"Expected one of [{', '.join(map(str, allowed))}]"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Verify that args is a dictionary mapping names to values.
    if not isinstance(args, dict):
        raise TypeError(f"Expected a dict for args, got {type(args).__name__}")
    # Retrieve the choices mapping if present.
    choices = getattr(self, "choices", None)
    if not isinstance(choices, dict):
        # No choices defined; nothing to validate.
        return
    for key, val in args.items():
        allowed = choices.get(key)
        if allowed is None:
            continue  # No restrictions for this argument.
        # Determine if allowed is a collection of acceptable values.
        if isinstance(allowed, (list, tuple, set)):
            if val not in allowed:
                raise ValueError(
                    f"Argument '{key}' has invalid value {val!r}. "
                    f"Allowed choices are: {allowed}"
                )
        else:
            # Treat 'allowed' as a single value.
            try:
                if val not in allowed:
                    raise ValueError(
                        f"Argument '{key}' has invalid value {val!r}. "
                        f"Allowed value is: {allowed}"
                    )
            except TypeError:
                # allowed is not iterable; compare directly.
                if val != allowed:
                    raise ValueError(
                        f"Argument '{key}' has invalid value {val!r}. "
                        f"Allowed value is: {allowed}"
                    )
    # All values are valid.
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Iterate over provided arguments and validate against defined choices.
    for name, value in args.items():
        try:
            # Retrieve the argument definition; ignore unknown arguments.
            arg_def = self._arguments[name]
        except Exception:
            continue

        # Get the allowed choices; skip validation if none are defined.
        choices = getattr(arg_def, 'choices', None)
        if choices is None:
            continue

        # Helper to determine if an object should be treated as an iterable of values.
        def is_iterable(v):
            return isinstance(v, (list, tuple, set))

        # Normalize single and multiple values.
        values_to_check = value
        if isinstance(value, str):
            # Strings should be treated as a single choice, not as an iterable.
            values_to_check = [value]
        elif is_iterable(value):
            # If the value itself is an iterable, iterate through its items.
            values_to_check = value
        else:
            # Non-iterable, single value.
            values_to_check = [value]

        # If the single value is None, skip validation (treated as omitted).
        if len(values_to_check) == 1 and values_to_check[0] is None:
            continue

        # Validate each value.
        for val in values_to_check:
            if val not in choices:
                allowed = ', '.join(repr(c) for c in choices)
                raise ValueError(
                    f"Argument '{name}' has invalid choice {repr(val)}; "
                    f"valid options are: {allowed}."
                )
    # If no validation error occurs, nothing is returned (implicitly None).

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Either a dictionary with keys
                 'value', 'min', and 'max', or a list/tuple of such
                 dictionaries. Raises ValueError if the arguments are
                 invalid or the value is out of bounds.
    :return: True if the value(s) are within the specified bounds.
    """
    def _check_one(arg):
        if not isinstance(arg, dict):
            raise ValueError(f"Argument entry must be a dict, got {type(arg).__name__}")
        for key in ('value', 'min', 'max'):
            if key not in arg:
                raise ValueError(f"Missing required key '{key}' in argument entry")
        value = arg['value']
        min_val = arg['min']
        max_val = arg['max']
        if value is None or min_val is None or max_val is None:
            raise ValueError("None is not allowed for 'value', 'min', or 'max'")
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(f"Value {value} is not between {min_val} and {max_val}")
        except TypeError:
            raise ValueError("'min', 'max', and 'value' must be comparable types")
        return True

    try:
        if isinstance(args, (list, tuple)):
            for arg in args:
                _check_one(arg)
        elif isinstance(args, dict):
            _check_one(args)
        else:
            raise ValueError(f"args must be a dict or list/tuple of dicts, got {type(args).__name__}")
    except Exception as exc:
        # Re-raise with a clear message
        raise ValueError(f"validate_min_max_args failed: {exc}") from None

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    try:
        # If no arguments provided, return False
        if args is None:
            return False

        # Retrieve minimum and maximum limits from the instance
        min_val = getattr(self, "min_value", None)
        max_val = getattr(self, "max_value", None)

        if min_val is None or max_val is None:
            raise AttributeError("Both 'min_value' and 'max_value' must be set on the instance.")

        # Accept values as a single number, list/tuple, or dict (whose values are checked)
        if isinstance(args, dict):
            values = args.values()
        else:
            values = args if isinstance(args, (list, tuple)) else [args]

        for value in values:
            if not isinstance(value, (int, float)):
                raise TypeError(f"Argument value {value!r} is not a numeric type.")
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument value {value!r} is outside the allowed range [{min_val}, {max_val}]."
                )

        return True

    except Exception:
        # In case of any exception during validation, return False
        return False

