def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments, expected to be a list of dictionaries each containing
                 the keys 'value', 'min', and 'max'.
    :raises TypeError: If args is not a list or an element is not a dict, or if
                       the key values are not numeric.
    :raises KeyError: If any expected key is missing.
    :raises ValueError: If the min value is greater than max or if the value is outside
                        the [min, max] inclusive range.
    :return: True if all arguments satisfy the constraints.
    """
    if not isinstance(args, list):
        raise TypeError("args must be a list")

    for idx, arg in enumerate(args):
        if not isinstance(arg, dict):
            raise TypeError(f"Argument at index {idx} must be a dictionary")

        for key in ("value", "min", "max"):
            if key not in arg:
                raise KeyError(f"Missing key '{key}' in argument at index {idx}")

        value = arg["value"]
        min_val = arg["min"]
        max_val = arg["max"]

        # Ensure numeric comparisons
        if not all(isinstance(v, (int, float)) for v in (value, min_val, max_val)):
            raise TypeError(f"Argument at index {idx} must contain numeric 'value', 'min', and 'max'")

        if min_val > max_val:
            raise ValueError(f"Argument at index {idx}: minimum ({min_val}) cannot be greater than maximum ({max_val})")

        if not (min_val <= value <= max_val):
            raise ValueError(
                f"Argument at index {idx} value ({value}) is outside the allowed range [{min_val}, {max_val}]"
            )

    return True

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Expected either a dict with keys 'min', 'max', 'value'
                 or a list/tuple of length 3 where the order is [min, max, value].
    :returns: True if the value is within the inclusive bounds, otherwise False.
    :raises: ValueError or TypeError if inputs are invalid.
    """
    try:
        # Resolve arguments based on type
        if isinstance(args, dict):
            try:
                min_val = args['min']
                max_val = args['max']
                val = args['value']
            except KeyError as e:
                raise ValueError(f"Missing required key in args: {e}") from e
        elif isinstance(args, (list, tuple)):
            if len(args) != 3:
                raise ValueError("Args list/tuple must have exactly 3 elements: [min, max, value]")
            min_val, max_val, val = args
        else:
            raise TypeError(f"Unsupported args type: {type(args).__name__}")

        # Validate types of the values
        if not isinstance(min_val, (int, float)):
            raise TypeError(f"min must be a number, got {type(min_val).__name__}")
        if not isinstance(max_val, (int, float)):
            raise TypeError(f"max must be a number, got {type(max_val).__name__}")
        if not isinstance(val, (int, float)):
            raise TypeError(f"value must be a number, got {type(val).__name__}")

        # Logical consistency check
        if min_val > max_val:
            raise ValueError("min cannot be greater than max")

        # Perform the comparison
        return min_val <= val <= max_val

    except Exception as exc:
        # Re‑raise exceptions with additional context
        raise ValueError(f"Error validating min/max arguments: {exc}") from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
