            if not isinstance(type_name, str) or not type_name:
                raise TypeError("type_name must be a non-empty string")
            if not isinstance(option_name, str) or not option_name:
                raise TypeError("option_name must be a non-empty string")

            # spec_option can be any JSON serializable object; if None, treat as empty dict
            if spec_option is None:
                spec_dict = {}
            elif isinstance(spec_option, dict):
                spec_dict = spec_option
            else:
                # Try to coerce common sequence types into a dict with indices as keys
                if hasattr(spec_option, "__iter__"):
                    spec_dict = {i: v for i, v in enumerate(spec_option)}
                else:
                    # Wrap a single value into a dict under key 'value'
                    spec_dict = {"value": spec_option}

            # Construct the complex type representation
            complex_type = {
                "subcommand": subcommand,
                "type_name": type_name,
                "option_name": option_name,
                "specification": spec_dict
            }
            return complex_type

        except Exception as exc:
            # Preserve the original traceback for debugging purposes
            raise RuntimeError(
                f"Failed to create complex argument type for '{option_name}' "
                f"on subcommand '{subcommand}': {exc}"
            ) from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    fields = spec_option.get("fields", [])
    if not isinstance(fields, list):
        raise TypeError("spec_option['fields'] must be a list of (name, type) tuples")
    # Validate field specifications
    for field in fields:
        if not isinstance(field, (list, tuple)) or len(field) != 2:
            raise ValueError("Each field specification must be a (name, type) tuple")
        name, typ = field
        if not isinstance(name, str) or not name:
            raise ValueError("Field name must be a non-empty string")
        if not isinstance(typ, type):
            raise TypeError(f"Field type for '{name}' must be a type")

    # Dynamically create a class for this complex type
    def make_init(field_specs):
        def __init__(self, **kwargs):
            for fname, ftype in field_specs:
                if fname not in kwargs:
                    raise ValueError(f"Missing value for field '{fname}'")
                val = kwargs[fname]
                # Try to coerce if necessary
                if not isinstance(val, ftype):
                    try:
                        val = ftype(val)
                    except Exception as e:
                        raise TypeError(
                            f"Field '{fname}' expects type {ftype.__name__}, got {type(val).__name__}"
                        ) from e
                setattr(self, fname, val)
        return __init__

    # Generate the initializer
    init_func = make_init(fields)

    # Dynamically create the class
    ComplexType = type(type_name, (object,), {"__init__": init_func})

    # Build defaults for initialization if provided
    defaults = spec_option.get("defaults", {})
    if not isinstance(defaults, dict):
        raise TypeError("spec_option['defaults'] must be a dict")

    instance_kwargs = {}
    for name, ftype in fields:
        if name in defaults:
            instance_kwargs[name] = defaults[name]
        else:
            # Use a safe default: 0 for int, 0.0 for float, "" for str, False for bool, None for others
            if ftype is int:
                default_val = 0
            elif ftype is float:
                default_val = 0.0
            elif ftype is str:
                default_val = ""
            elif ftype is bool:
                default_val = False
            else:
                default_val = None
            instance_kwargs[name] = default_val

    try:
        complex_instance = ComplexType(**instance_kwargs)
    except Exception as e:
        raise RuntimeError(f"Failed to instantiate complex type '{type_name}': {e}") from e

    return complex_instance

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    # spec_option can be any mapping; if not, default to empty dict
    if spec_option is None:
        spec_option = {}
    elif not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary or None")

    # Create a lightweight class to represent the complex type
    class ComplexArgumentType:
        """
        Simple complex argument type holder.
        """

        def __init__(self, subcmd, typ, opt, spec):
            self.subcommand = subcmd
            self.type_name = typ
            self.option_name = opt
            # Store a copy to avoid accidental external mutation
            self.spec_option = dict(spec)

        def __repr__(self):
            return (
                f"<ComplexArgumentType name={self.type_name!r} "
                f"subcommand={self.subcommand!r} option={self.option_name!r}>"
            )

        def validate(self, value):
            """
            Validate a value based on the specs provided.
            The validation logic is intentionally simple and can be expanded
            later. For now it supports:
            - 'choices': a list of acceptable values
            - 'validator': a callable that returns a bool
            """
            try:
                if 'choices' in self.spec_option:
                    if value not in self.spec_option['choices']:
                        return False
                if 'validator' in self.spec_option:
                    validator = self.spec_option['validator']
                    if callable(validator):
                        return bool(validator(value))
                    else:
                        raise ValueError("'validator' must be callable")
                return True
            except Exception:
                return False

    # Instantiate and return the complex argument type
    try:
        return ComplexArgumentType(subcommand, type_name, option_name, spec_option)
    except Exception as exc:
        raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("`subcommand` must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("`type_name` must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("`option_name` must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("`spec_option` must be a dict with argument specifications")

    # Local helper class representing a complex argument type
    class ComplexArgumentType:
        def __init__(self, type_name, spec_option):
            self.type_name = type_name
            self.spec_option = spec_option

        def parse(self, value):
            """
            Parse a raw input value according to the provided specification.
            Supports simple separator-based lists with optional type conversion.
            """
            # Determine separator and item type
            separator = self.spec_option.get("separator", ",")
            type_name = self.spec_option.get("type", "str")

            # Map string type names to Python built-in types
            type_map = {
                "str": str,
                "int": int,
                "float": float,
                "complex": complex,
            }
            if type_name not in type_map:
                raise ValueError(f"Unsupported item type '{type_name}' in spec_option")

            py_type = type_map[type_name]

            try:
                parts = [p.strip() for p in str(value).split(separator)]
                return [py_type(p) for p in parts]
            except Exception as exc:
                raise ValueError(f"Unable to parse value {value!r} as a {type_name} list") from exc

        def __repr__(self):
            return f"<ComplexArgumentType name={self.type_name!r} spec={self.spec_option!r}>"

    return ComplexArgumentType(type_name, spec_option)

