def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments into control and nested arguments.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom Ansible variables to be used instead of the
        normal nested usage.

    :param args: The collected list of args. Expected to be a dict or
                 an iterable of (key, value) pairs.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Initialize containers
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    try:
        # Normalize args to iterable of key-value pairs
        if isinstance(args, dict):
            items = args.items()
        else:
            # Assume list/tuple of (key, value)
            items = args
    except Exception as exc:
        raise ValueError(f"Invalid args format: {exc}") from exc

    for item in items:
        # Accept both (key, value) tuples and 2-element lists
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError(f"Each item must be a 2‑tuple; got {item!r}")
        key, value = item

        if not isinstance(key, str):
            raise ValueError(f"Argument key must be a string; got {key!r}")

        # Control arguments are prefixed with 'control_'
        if key.startswith("control_"):
            control_args[key] = value
        else:
            # All other arguments (including custom ones) go to nested
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """
        Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.  It may be a dict, a list of
            tuples/lists in the form ``[(key, value), ...]``, or any iterable
            of 2‑tuples.  Unknown formats will result in an empty pair of
            dictionaries.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}

        # Helper to normalise args into an iterable of (key, value)
        def _iter_args(a):
            if a is None:
                return []
            if isinstance(a, dict):
                return a.items()
            try:
                # Support list/tuple of 2‑item sequences
                for item in a:
                    if (
                        isinstance(item, (list, tuple))
                        and len(item) == 2
                    ):
                        yield item[0], item[1]
                    else:
                        # Unknown item format; skip
                        continue
            except TypeError:
                # Not iterable
                return []

        for key, val in _iter_args(args):
            if not isinstance(key, str):
                # Skip non‑string keys
                continue
            if key.startswith("control_"):
                clean_key = key[len("control_") :]
                control_args[clean_key] = val
            else:
                # Everything else, including custom_, goes into nested
                nested_args[key] = val

        return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: Iterable of extra-vars represented as ``key=value`` strings,
                           dictionaries, or tuples.
        :return: The updated dictionary
        """
        # Validate input
        if not isinstance(vars_dict, dict):
            raise TypeError(f"'vars_dict' must be a dict, got {type(vars_dict).__name__}")

        # Nothing to merge
        if extra_vars is None:
            return vars_dict

        # If a dict is given, just update
        if isinstance(extra_vars, dict):
            try:
                vars_dict.update(extra_vars)
            except Exception as e:
                raise ValueError(f"Failed to update vars_dict with {extra_vars!r}: {e}") from e
            return vars_dict

        # Otherwise, iterate over the provided iterable
        try:
            for item in extra_vars:
                # Handle key=value strings
                if isinstance(item, str):
                    if '=' in item:
                        key, value = item.split('=', 1)
                        key = key.strip()
                        value = value.strip()
                        if key:  # ignore empty keys
                            vars_dict[key] = value
                    else:
                        # Skip or warn about malformed string
                        continue
                # Handle dictionaries
                elif isinstance(item, dict):
                    vars_dict.update(item)
                # Handle tuple or list with two elements: (key, value)
                elif isinstance(item, (tuple, list)) and len(item) == 2:
                    key, value = item
                    if isinstance(key, str) and key:
                        vars_dict[key] = value
                else:
                    # Unsupported type: ignore
                    continue
        except Exception as e:
            # Unexpected error during merge: raise a ValueError
            raise ValueError(f"Error while merging extra_vars: {e}") from e

        return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")

    if extra_vars is None:
        return vars_dict

    # Normalize extra_vars to an iterable of items
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    elif isinstance(extra_vars, str):
        # Treat a single string as a single item
        extra_vars = [extra_vars]
    elif not isinstance(extra_vars, (list, tuple)):
        # Wrap any other type into a list
        extra_vars = [extra_vars]

    # Helper to set a potentially nested key
    def set_nested(target, key_path, value):
        current = target
        for part in key_path[:-1]:
            if part not in current or not isinstance(current[part], dict):
                current[part] = {}
            current = current[part]
        current[key_path[-1]] = value

    for item in extra_vars:
        if isinstance(item, dict):
            # If item is a dict, merge it directly
            vars_dict.update(item)
            continue
        if not isinstance(item, str):
            # Unsupported type for this item; skip
            continue

        # Strip whitespace
        item = item.strip()
        if not item:
            continue

        # Handle "key=value" strings
        if '=' in item:
            key_str, value_str = item.split('=', 1)
            key_str = key_str.strip()
            value_str = value_str.strip()

            # Try to interpret the value using ast.literal_eval safely
            try:
                parsed_value = __import__('ast').literal_eval(value_str)
            except Exception:
                # Fallback: handle common literals manually
                lowered = value_str.lower()
                if lowered in ('true', 'false'):
                    parsed_value = lowered == 'true'
                else:
                    try:
                        parsed_value = int(value_str)
                    except ValueError:
                        try:
                            parsed_value = float(value_str)
                        except ValueError:
                            parsed_value = value_str
            key_parts = key_str.split('.')
            set_nested(vars_dict, key_parts, parsed_value)
        else:
            # If there's no '=', treat the entire string as a boolean flag key set to True
            key_parts = [item]
            set_nested(vars_dict, key_parts, True)

    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``. `extra_vars` can be a list of strings in the form
    ``key=value`` or a list/dict of key/value pairs. Existing keys will be overridden.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (strings or dictionaries)
    :return: The updated dictionary
    """
    # Validate input types
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    # Allow single dictionary to be passed instead of a list
    if isinstance(extra_vars, dict):
        extra_items = [extra_vars]
    else:
        extra_items = extra_vars
    # Process each item
    for item in extra_items:
        try:
            if isinstance(item, str):
                # Expect form "key=value"
                if '=' not in item:
                    # Invalid format; ignore
                    continue
                key, raw_val = item.split('=', 1)
                key = key.strip()
                raw_val = raw_val.strip()
                if not key:
                    # Empty key; ignore
                    continue
                # Attempt to interpret the value as a Python literal
                try:
                    import ast
                    value = ast.literal_eval(raw_val)
                except Exception:
                    # If eval fails, keep as string
                    value = raw_val
            elif isinstance(item, dict):
                # Merge entire dict
                for k, v in item.items():
                    if isinstance(k, str):
                        vars_dict[k] = v
                continue
            else:
                # Unsupported type; ignore
                continue
            vars_dict[key] = value
        except Exception as exc:
            # If any unexpected error occurs, ignore that item and continue
            continue
    return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.
        ``extra_vars`` can be a dictionary, a string or a list containing dictionaries or strings.
        The function safely parses the input and updates ``vars_dict`` in place.
        It returns the updated dictionary.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :raises TypeError: if ``vars_dict`` is not a dictionary or ``extra_vars`` has unsupported types
        """
        import json

        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if extra_vars is None:
            return vars_dict

        def _update_from_dict(d):
            for k, v in d.items():
                vars_dict[k] = v

        def _parse_string(s):
            """Attempt to parse a string into key/value pairs.
            Supports:
              - Space-separated key=value pairs
              - Comma-separated key=value pairs
              - JSON-formatted string for a single dict
            """
            s = s.strip()
            if not s:
                return

            # Try JSON first
            try:
                data = json.loads(s)
                if isinstance(data, dict):
                    _update_from_dict(data)
                    return
            except Exception:
                pass

            # Split by whitespace or commas
            parts = []
            if ',' in s:
                parts = s.split(',')
            else:
                parts = s.split()

            for part in parts:
                part = part.strip()
                if not part:
                    continue
                if '=' in part:
                    key, val = part.split('=', 1)
                    vars_dict[key] = val
                else:
                    # Ignore malformed entries
                    continue

        if isinstance(extra_vars, dict):
            _update_from_dict(extra_vars)
        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    _update_from_dict(item)
                elif isinstance(item, str):
                    _parse_string(item)
                else:
                    # Unsupported element type; ignore or raise?
                    continue
        elif isinstance(extra_vars, str):
            _parse_string(extra_vars)
        else:
            # Unsupported type
            raise TypeError("extra_vars must be a dict, list, tuple, or string")

        return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into.
        :param extra_vars: Iterable of extra-vars. Items can be dicts, 2‑tuples,
                           or strings in ``key=value`` format. If a string
                           contains no ``=``, it will be treated as a flag
                           with a boolean True value. ``None`` is ignored.
        :return: A new dictionary containing the merged key/value pairs.
        """
        # Validate input types
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return dict(vars_dict)

        # Make a copy so we don't mutate the original
        merged = dict(vars_dict)

        for item in extra_vars:
            try:
                if isinstance(item, dict):
                    merged.update(item)
                    continue

                if isinstance(item, (list, tuple)):
                    if len(item) == 2:
                        key, value = item
                        merged[key] = value
                    else:
                        # Skip invalid tuple/list
                        continue
                    continue

                if isinstance(item, str):
                    if "=" in item:
                        key, val_str = item.split("=", 1)
                        try:
                            import ast
                            value = ast.literal_eval(val_str)
                        except Exception:
                            # Fallback to raw string if eval fails
                            value = val_str
                        merged[key] = value
                    else:
                        # Treat as flag
                        merged[item] = True
                    continue

                # If item type is unsupported, skip it
                continue
            except Exception:
                # Log or handle individual item failure silently
                continue

        return merged

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

        :param ir_workspace: An Infrared Workspace object represents the active
        workspace
        :param ir_plugin: An InfraredPlugin object of the current plugin
        :param playbook_path: the playbook to invoke
        :param verbose: Ansible verbosity level
        :param extra_vars: dict. Passed to Ansible as extra-vars
        :param ansible_args: dict of ansible-playbook arguments to plumb down
            directly to Ansible.
    """
    import subprocess
    import json

    # Basic command
    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append("-" + "v" * min(verbose, 5))
        elif isinstance(verbose, str):
            # Allow 'v', 'vv', etc.
            vv = "v" * min(len(verbose), 5)
            cmd.append("-" + vv)

    # Extra vars
    if extra_vars:
        try:
            extra_json = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", extra_json])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"extra_vars must be JSON serializable: {exc}") from exc

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if key.startswith("-"):
                flag = key
            else:
                flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # If False, skip
            elif value is None:
                # Just a flag
                cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.root if hasattr(ir_workspace, "root") else None,
            capture_output=True,
            text=True,
            check=False,  # We'll handle non-zero exit manually
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # Handle non-zero exit
    if result.returncode != 0:
        err_msg = f"ansible-playbook exited with {result.returncode}\n" \
                  f"stdout:\n{result.stdout}\n" \
                  f"stderr:\n{result.stderr}"
        raise RuntimeError(err_msg)

    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the ansible-playbook command
    cmd = ["ansible-playbook"]

    # Handle verbosity
    if verbose:
        try:
            v = int(verbose)
            if v > 0:
                cmd.append("-" + "v" * v)
        except Exception:
            # If verbosity is not an integer, ignore it
            pass

    cmd.append(playbook_path)

    # Handle extra_vars
    if extra_vars is not None:
        # Build a space-separated key=value string if a dict is provided
        if isinstance(extra_vars, dict):
            ev_items = []
            for k, v in extra_vars.items():
                ev_items.append(f"{k}={v}")
            ev_str = " ".join(ev_items)
        else:
            ev_str = str(extra_vars)
        cmd.extend(["--extra-vars", ev_str])

    # Handle additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            flag = "--" + key.lstrip("-")
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Execute the command
    try:
        # Using subprocess.run which expects subprocess to be available
        result = subprocess.run(
            cmd,
            check=True,
            capture_output=True,
            text=True
        )
        # Log the command if the plugin supports logging
        if hasattr(ir_plugin, "log_debug"):
            ir_plugin.log_debug("Executed ansible-playbook: " + " ".join(cmd))
        return result.stdout
    except Exception as exc:
        # Log error if possible
        if hasattr(ir_plugin, "log_error"):
            ir_plugin.log_error(f"ansible-playbook failed: {exc}")
        # Re-raise to propagate error
        raise

