     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess
    import json

    # Validate the playbook path
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string path")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook file not found: {playbook_path}")

    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non‑negative integer or None")
        cmd.extend(["-" + "v" * verbose])

    # Add custom ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            flag = f"--{key}"
            # Handle boolean flags
            if isinstance(val, bool):
                if val:
                    cmd.append(flag)
                continue
            # For iterable values (e.g., lists), join into a string
            if isinstance(val, (list, tuple)):
                val_str = " ".join(map(str, val))
            else:
                val_str = str(val)
            cmd.extend([flag, val_str])

    # Add extra vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            extra_json = json.dumps(extra_vars, separators=(",", ":"))
        except TypeError as exc:
            raise ValueError(f"extra_vars contains non‑serializable data: {exc}") from exc
        cmd.extend(["--extra-vars", extra_json])

    # Set environment from workspace or plugin if possible
    env = os.environ.copy()
    # If the workspace or plugin provide environment variables, merge them
    # (This is a best‑effort; actual implementation depends on those objects)
    try:
        if hasattr(ir_workspace, "env") and isinstance(ir_workspace.env, dict):
            env.update(ir_workspace.env)
    except Exception:
        pass
    try:
        if hasattr(ir_plugin, "env") and isinstance(ir_plugin.env, dict):
            env.update(ir_plugin.env)
    except Exception:
        pass

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found. Is Ansible installed?") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    if result.returncode != 0:
        # Raise an informative error
        raise RuntimeError(
            f"ansible-playbook exited with non‑zero status {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"STDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}"
        )

    # Successful execution; return the CompletedProcess for caller inspection
    return result

