def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list")
    # Determine the workspace path
    ws_path = None
    if hasattr(ir_workspace, "path"):
        ws_path = ir_workspace.path
    elif hasattr(ir_workspace, "get_path"):
        try:
            ws_path = ir_workspace.get_path()
        except Exception:
            ws_path = None
    if not ws_path:
        raise ValueError("Could not determine workspace path from ir_workspace")
    # Build the ansible-playbook command
    cmd = ["ansible-playbook"]
    cmd.extend(cli_args)
    # Attach the extra vars as JSON
    import json
    cmd.extend(["--extra-vars", json.dumps(vars_dict)])
    # Merge environment variables from the plugin if provided
    import os
    env = os.environ.copy()
    if hasattr(ir_plugin, "env") and isinstance(ir_plugin.env, dict):
        env.update(ir_plugin.env)
    elif hasattr(ir_plugin, "get_env"):
        try:
            env.update(ir_plugin.get_env())
        except Exception:
            pass
    # Execute the command
    try:
        import subprocess
        proc = subprocess.run(
            cmd,
            cwd=ws_path,
            env=env,
            capture_output=True,
            text=True,
            check=False,
        )
        return {
            "returncode": proc.returncode,
            "stdout": proc.stdout,
            "stderr": proc.stderr,
        }
    except FileNotFoundError as e:
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": f"ansible-playbook not found: {e}",
        }
    except Exception as e:
        return {
            "returncode": -1,
            "stdout": "",
            "stderr": str(e),
        }

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Helper function to convert a single string to the best matching type
    def _convert_value(val):
        if val is None:
            return None
        if not isinstance(val, str):
            return val

        # Boolean values
        low = val.lower()
        if low in ('true', 'false', '1', '0', 'yes', 'no', 'y', 'n', 't', 'f'):
            return low in ('true', '1', 'yes', 'y', 't')

        # Integer values
        try:
            return int(val)
        except ValueError:
            pass

        # Float values
        try:
            return float(val)
        except ValueError:
            pass

        # List values separated by commas
        if ',' in val:
            parts = [p.strip() for p in val.split(',')]
            return [_convert_value(p) for p in parts]

        # Return the original string if nothing else matches
        return val

    # Iterate over a snapshot of the items to avoid race conditions
    for key, val in list(values_dict.items()):
        try:
            converted = _convert_value(val)
            values_dict[key] = converted
        except Exception:
            # If any unexpected error occurs skip conversion for this key
            continue
    return None

