def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser associated with the given name.
    # The implementation assumes that a mapping self._parsers exists.
    parser = getattr(self, "_parsers", {}).get(parser_name)
    if parser is None:
        # No parser found – nothing to convert.
        return

    # Iterate over all actions defined in the argparse parser.
    for action in parser._actions:
        dest = action.dest
        if dest not in values_dict:
            continue

        raw_value = values_dict[dest]
        try:
            # If an explicit type is defined in argparse, use it.
            if action.type is not None:
                casted = action.type(raw_value)
            else:
                # Heuristic casting for common types.
                if isinstance(raw_value, str):
                    lowered = raw_value.lower()
                    if lowered in ("true", "false"):
                        casted = lowered == "true"
                    elif lowered in ("1", "0"):
                        casted = bool(int(lowered))
                    else:
                        # Attempt numeric conversions.
                        try:
                            casted = int(raw_value)
                        except ValueError:
                            try:
                                casted = float(raw_value)
                            except ValueError:
                                # Fallback: keep original string.
                                casted = raw_value
                else:
                    # Value is already a non-string type – leave as is.
                    casted = raw_value

            values_dict[dest] = casted
        except Exception:
            # If any conversion fails, preserve the original string value.
            values_dict[dest] = raw_value
