def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Ensure we are working with a dictionary
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    def _convert_value(v):
        """Recursively convert a value to a more specific type if possible."""
        # List handling: convert each element
        if isinstance(v, list):
            return [_convert_value(item) for item in v]

        if isinstance(v, str):
            s = v.strip()
            lower = s.lower()

            # Boolean conversion
            if lower in ("true", "false", "yes", "no"):
                return lower in ("true", "yes")

            # Integer conversion
            try:
                return int(s)
            except ValueError:
                pass

            # Float conversion
            try:
                return float(s)
            except ValueError:
                pass

        # For all other cases, return as-is
        return v

    # Perform conversion for each key-value pair
    for key in list(values_dict.keys()):
        try:
            values_dict[key] = _convert_value(values_dict[key])
        except Exception:
            # If conversion fails for any reason, keep the original value
            pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper for flattening nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    spec = None
    # Determine possible spec file names
    possible_filenames = ['plugin.yaml', 'plugin.yml', 'plugin.json']

    for filename in possible_filenames:
        spec_path = os.path.join(plugin_dir, filename)
        if os.path.isfile(spec_path):
            try:
                if filename.endswith('.json'):
                    with open(spec_path, 'r', encoding='utf-8') as f:
                        spec = json.load(f)
                else:
                    try:
                        import yaml
                    except Exception:
                        # yaml not available, fallback to json if possible
                        with open(spec_path, 'r', encoding='utf-8') as f:
                            try:
                                spec = json.load(f)
                            except json.JSONDecodeError:
                                # Can't parse
                                spec = {}
                    else:
                        with open(spec_path, 'r', encoding='utf-8') as f:
                            spec = yaml.safe_load(f)
                break
            except Exception:
                # Parsing error results in empty spec
                spec = {}
                break

    if spec is None:
        # No spec file found; return empty dictionary
        return {}

    if not isinstance(spec, dict):
        # Spec is not a dict; cannot flatten
        return {}

    try:
        flat_spec = _flatten(spec)
    except Exception:
        # In case of unexpected errors during flattening
        return {}

    return flat_spec

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        import os
        import json
    except Exception as e:
        raise ValueError("Required modules not available") from e

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Provided plugin_dir '{plugin_dir}' is not a directory")

    # locate possible spec files
    spec_filenames = ["plugin.yaml", "plugin.yml", "plugin.json"]
    spec_path = None
    for fname in spec_filenames:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'")

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            content = f.read()
    except OSError as e:
        raise RuntimeError(f"Error reading spec file '{spec_path}': {e}") from e

    # parse spec content
    spec_dict = None
    if spec_path.endswith((".yaml", ".yml")):
        try:
            # YAML parsing
            import yaml  # noqa: F401
            spec_dict = yaml.safe_load(content)
        except Exception as e:
            # fallback to JSON just in case
            try:
                spec_dict = json.loads(content)
            except Exception as je:
                raise ValueError(f"Failed to parse YAML spec: {e}; also invalid JSON: {je}") from e
    else:
        try:
            spec_dict = json.loads(content)
        except Exception as e:
            raise ValueError(f"Failed to parse JSON spec: {e}") from e

    if not isinstance(spec_dict, dict):
        raise ValueError("Parsed plugin spec is not a mapping/dictionary")

    # flatten nested dictionary
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    try:
        return _flatten(spec_dict)
    except Exception as e:
        raise RuntimeError(f"Error flattening plugin spec: {e}") from e

def get_plugin_spec_flatten_dict(plugin_dir):
