def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    try:
        # Use os.path for path normalization and relative path calculation
        import os
        norm_path = os.path.normpath(path)
        norm_root = os.path.normpath(root)
        # Ensure that root is actually a prefix of path
        try:
            if os.path.commonpath([norm_path, norm_root]) != norm_root:
                raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
        except Exception as e:
            raise ValueError(f"Failed to determine common path: {e}")
        # Compute the relative path
        rel = os.path.relpath(norm_path, norm_root)
        # If the relative path is '.', return empty string to indicate no remainder
        return '' if rel == '.' else rel
    except Exception as exc:
        raise ValueError(f"Unable to strip root: {exc}") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    if root == "":
        raise ValueError("root cannot be empty")
    # If path equals root exactly, return empty string
    if path == root:
        return ""
    # Helper to try removing root followed by a separator
    def try_strip(prefix, sep):
        if path.startswith(prefix + sep):
            return path[len(prefix) + 1 :]
        return None
    # Try with common separators
    result = try_strip(root, "/")
    if result is not None:
        return result
    result = try_strip(root, "\\")
    if result is not None:
        return result
    # If root itself ends with a separator, just strip it
    if path.startswith(root):
        if len(path) == len(root):
            return ""
        return path[len(root) :]
    # No match, cannot strip
    raise ValueError("path does not start with root")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Basic input validation
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if root == "":
        raise ValueError("root cannot be an empty string")

    # Attempt to strip root using direct match
    if path.startswith(root):
        stripped = path[len(root):]
    else:
        # Try stripping any trailing path separators from root
        root_clean = root.rstrip('/\\')
        if path.startswith(root_clean):
            stripped = path[len(root_clean):]
        else:
            raise ValueError(f"Path '{path}' does not start with root '{root}'")

    # Remove any leading path separators from the result
    stripped = stripped.lstrip('/\\')

    return stripped
